INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10112606','Verlust von Aufenthalts- oder Ausweisdokumenten','https://service.berlin.de/dienstleistung/10112606/','Sonstiges','{\"id\":\"10112606\",\"name\":\"Verlust von Aufenthalts- oder Ausweisdokumenten\",\"description\":\"<p>Folgenden gestohlene oder verloren gegangene Dokumente, k\\u00f6nnen Sie bei der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung melden:<\\/p>\\n<ul>\\n <li>Aufenthaltsdokument (eAT, Duldung oder Gestattung)<\\/li>\\n <li>ID-Karte (nur bei EU-B\\u00fcrger*innen)<\\/li>\\n <li>Reiseausweis (f\\u00fcr Fl\\u00fcchtlinge, Ausl\\u00e4nder*innen oder Staatenlose)<\\/li>\\n <li>Ausl\\u00e4ndischer Reisepass<\\/li>\\n<\\/ul>\\n<p>Melden Sie uns den Verlust oder Widerruf eines Verlustes <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhverlustid\\/index\\\">online<\\/a> oder per Post. Sie k\\u00f6nnen die Meldung f\\u00fcr Ihre eigenen Ausweisdokumente und f\\u00fcr die Ihrer minderj\\u00e4hrigen Kinder vornehmen.<\\/p>\\n<p>Wir bearbeiten Ihre Verlustanzeige in der Regel innerhalb von 14 Tagen und lassen die Dokumente zur Fahndung ausschreiben. Die so gesperrten Dokumente k\\u00f6nnen f\\u00fcr Reisen nicht mehr genutzt werden.<\\/p>\\n<p>Wenn es sich um einen eAT, Reiseausweis, eine Duldung oder Gestattung handelt, erhalten Sie nach Ihrer Verlustanzeige von uns einen Termin zur Neubestellung des jeweiligen Dokuments. Die Neubestellung des jeweiligen Dokuments kann bis zu 12 Wochen in Anspruch nehmen.<\\/p>\\n<p>Wenn Sie Ihren eAT verloren haben, k\\u00f6nnen Sie von uns als Ersatz f\\u00fcr die Nutzung in Deutschland eine Bescheinigung \\u00fcber den Aufenthaltstitel erhalten.<\\/p>\\n<p>Bei einem Widerruf des Verlustes kann nicht immer mit der sofortigen, weltweiten L\\u00f6schung der Ausschreibung des Dokuments in den internationalen Sachfahndungssystemen gerechnet werden. Daher ist es m\\u00f6glich, dass ein wieder aufgefundenes Dokument nicht uneingeschr\\u00e4nkt weiterverwendet werden kann und es bei sp\\u00e4teren internationalen Reisen zu R\\u00fcckfragen bei Ein- und Ausreisen kommt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"eAT sperren, Elektronischer Aufenthaltstitel sperren, eAT verloren, Sperrhotline, Elektronischer Aufenthaltstitel verloren, eAT-Onlinefunktion sperren, eAT gestohlen, Elektronischer Aufenthaltstitel gestohlen, Online-Ausweisfunktion sperren\",\"translated\":true,\"hash\":\"\",\"id\":\"10112606\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308621\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10112606\\/locations\\/10308621\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10112606\\/locations\\/10308621\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge - Elektronischer Aufenthaltstitel (eAT)\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/Aufenthalt\\/eAufenthaltstitel\\/e-aufenthaltstitel-node.html\",\"description\":false},{\"name\":\"Sperrnotruf\",\"link\":\"https:\\/\\/www.sperr-notruf.de\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge - Elektronischer Aufenthaltstitel (eAT)\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/Aufenthalt\\/eAufenthaltstitel\\/e-aufenthaltstitel-node.html\",\"description\":false},{\"name\":\"Sperrnotruf\",\"link\":\"https:\\/\\/www.sperr-notruf.de\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10112606],\"fees\":\"<p>Verlustanzeige: geb\\u00fchrenfrei<\\/p>\\n<p>Bescheinigung \\u00fcber den Aufenthaltstitel: 18 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10113239','Elternberatung zur Kinderbetreuung','https://service.berlin.de/dienstleistung/10113239/','Sonstiges','{\"id\":\"10113239\",\"name\":\"Elternberatung zur Kinderbetreuung\",\"description\":\"<p>Wir unterst\\u00fctzen Eltern <strong>pers\\u00f6nlich, telefonisch und per E-Mail <strong>\\u2013<\\/strong><\\/strong> zum Beispiel bei:\\u200b<\\/p>\\n<ul>\\n <li>der Suche nach einem passenden Betreuungsplatz f\\u00fcr Kinder bis 10 Jahre<\\/li>\\n <li>der Anmeldung im kita finder+<\\/li>\\n <li>Fragen zu den verschiedenen Betreuungsformen<\\/li>\\n <li>Fragen zum Tagesablauf und zu p\\u00e4dagogischen Konzepten der Einrichtungen<\\/li>\\n <li>Fragen zu unterschiedlichen Tr\\u00e4gern der Kindertagesbetreuung\\n  <br><\\/li>\\n<\\/ul>\\n<p><strong>Zus\\u00e4tzliche Informationen f\\u00fcr Eltern von Grundschulkindern (6\\u201310 Jahre)<\\/strong><\\/p>\\n<p><strong><a href=\\\"https:\\/\\/stadt.muenchen.de\\/infos\\/betreuung-an-muenchner-grundschulen\\\">Betreuungsformen f\\u00fcr Grundschulkinder<\\/a><\\/strong>\\n <br><\\/p>\\n<ul>\\n <li>Gebundener Ganztag<\\/li>\\n <li>Offener Ganztag\\n  <br><\\/li>\\n <li>Kooperative Ganztagsbildung (KoGa)<\\/li>\\n <li>Mittagsbetreuung<\\/li>\\n <li>Tagesheim<\\/li>\\n <li>Hort, Haus f\\u00fcr Kinder, Regionalhaus<\\/li>\\n<\\/ul>\\n<p><strong>Schulplatzwahl<\\/strong><\\/p>\\n<ul>\\n <li><a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063799\\/n0\\/\\\">Sprengelschule<\\/a><\\/li>\\n <li><a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1078384\\/n0\\/\\\">Gastschulantrag<\\/a>\\n  <br><\\/li>\\n<\\/ul>\\n<p><strong>Ferienbetreuung<\\/strong><\\/p>\\n<p>Neben Ferienangeboten am Schulstandort gibt es auch zahlreiche weitere Angebote in den Ferien, die Eltern nutzen k\\u00f6nnen:<\\/p>\\n<ul>\\n <li><a href=\\\"https:\\/\\/www.ferien-muenchen.de\\/\\\">M\\u00fcnchner Ferienportal<\\/a><\\/li>\\n <li><a href=\\\"https:\\/\\/veranstaltungen.muenchen.de\\/ferienangebote-familienpass\\/ferienfreizeiten\\/\\\">Ferienangebote und Familienpass des Sozialreferats<\\/a><\\/li>\\n <li><a href=\\\"https:\\/\\/stadt.muenchen.de\\/infos\\/spielaktionen.html\\\">Spielaktionen und Sportangebote<\\/a><\\/li>\\n<\\/ul>\\n<p>Wenn Sie keine Ferienbetreuung f\\u00fcr Ihr Kind finden, ber\\u00e4t Sie die Elternberatungsstelle und hilft Ihnen weiter.<\\/p>\\n<p><strong>Ihr Weg zum Betreuungsplatz<\\/strong><\\/p>\\n<p><strong>Schritt 1: Anmeldung zur Betreuung<\\/strong>\\n <br>\\n Sie m\\u00fcssen sich bis 11. M\\u00e4rz 2026 anmelden. Melden Sie sich in den Einrichtungen an, die f\\u00fcr Ihr Kind geeignet sind. F\\u00fcr die Kinderkrippe, Kindergarten, Kooperative Ganztagsbildung, Horte, H\\u00e4user f\\u00fcr Kinder, Tagesheime und manche Mittagsbetreuungen k\\u00f6nnen Sie sich online \\u00fcber den kita finder+ anmelden.\\n <br><\\/p>\\n<p><strong>Schritt 2: Nur f\\u00fcr Schulkinder - Schuleinschreibung<\\/strong>\\n <br>\\n Die Schuleinschreibung findet am 11. M\\u00e4rz 2026 statt. Bitte gehen Sie zu Ihrer Sprengelschule. An diesem Tag melden Sie Ihr Kind f\\u00fcr die Schule an. Fragen Sie nach Betreuungsm\\u00f6glichkeiten an der Schule (wie zum Beispiel Offener oder Gebundener Ganztag) und melden Sie Ihr Kind an.<\\/p>\\n<p><strong>Schritt 3: Platzzusage<\\/strong>\\n <br>\\n Die Platzzusagen werden ab dem 12. M\\u00e4rz 2026 vergeben. Die Platzvergabe kann mehrere Monate dauern.<\\/p>\\n<p><strong>Schritt 4: Platz annehmen oder absagen<\\/strong>\\n <br>\\n Wenn Sie eine Zusage bekommen, haben Sie acht bis zehn Tage Zeit, um den Platz anzunehmen. Wenn Sie den zugesagten Platz nicht brauchen, sagen Sie bitte umgehend ab, da andere Kinder noch auf einen Platz warten.<\\/p>\\n<p><strong>Schritt 5: Weitere Platzvergaben<\\/strong>\\n <br>\\n Weitere Zusagen werden in den n\\u00e4chsten Platzvergaberunden vergeben.<\\/p>\\n<p><strong>Schritt 6: Unterst\\u00fctzung Elternberatungsstelle<\\/strong>\\n <br>\\n Wenn Sie keinen Platz bekommen haben, wenden Sie sich bitte an die Elternberatungsstelle.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Betreuungsplatzsuche, Bedarfsgerechter Betreuungsplatz, Platz Kindertagesst\\u00e4tte, Absage f\\u00fcr Betreuungsplatz, Rechtsanspruch Kinderbetreuung\",\"translated\":true,\"hash\":\"\",\"id\":\"10113239\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1063373\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10113239\\/locations\\/1063373\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10113239\\/locations\\/1063373\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99041004000000\",\"public\":true,\"links\":[{\"name\":\"Bedarfsformular f\\u00fcr Kinder bis zehn Jahre\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/05\\/05\\/bedarfsformular_kinder\\/index\",\"description\":false},{\"name\":\"kita finder+ Hilfe f\\u00fcr Sorgeberechtigte bei technischen Fragen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/05\\/05\\/hilfe_kitafinder_plus\\/index\",\"description\":false},{\"name\":\"Formen der Kinderbetreuung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/kinderbetreuung-formen.html\",\"description\":false},{\"name\":\"Betreuungsangebote f\\u00fcr Grundschulkinder\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/betreuung-an-muenchner-grundschulen\",\"description\":false},{\"name\":\"Anmeldung an einer Kindertageseinrichtung (kita finder+)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/10110130\\/n0\\/\",\"description\":false},{\"name\":\"Anmeldung an einer M\\u00fcnchner Grundschule\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/elternberatung\\/10225117\\/\",\"description\":false},{\"name\":\"Schweigepflichtentbindung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/Home\\/Stadtverwaltung\\/Referat-fuer-Bildung-und-Sport\\/kita\\/traeger-stadt\\/Schweigepflichtentbindung.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Bedarfsformular f\\u00fcr Kinder bis zehn Jahre\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/05\\/05\\/bedarfsformular_kinder\\/index\",\"description\":false},{\"name\":\"kita finder+ Hilfe f\\u00fcr Sorgeberechtigte bei technischen Fragen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/05\\/05\\/hilfe_kitafinder_plus\\/index\",\"description\":false},{\"name\":\"Formen der Kinderbetreuung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/kinderbetreuung-formen.html\",\"description\":false},{\"name\":\"Betreuungsangebote f\\u00fcr Grundschulkinder\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/betreuung-an-muenchner-grundschulen\",\"description\":false},{\"name\":\"Anmeldung an einer Kindertageseinrichtung (kita finder+)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/10110130\\/n0\\/\",\"description\":false},{\"name\":\"Anmeldung an einer M\\u00fcnchner Grundschule\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/elternberatung\\/10225117\\/\",\"description\":false},{\"name\":\"Schweigepflichtentbindung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/Home\\/Stadtverwaltung\\/Referat-fuer-Bildung-und-Sport\\/kita\\/traeger-stadt\\/Schweigepflichtentbindung.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10113239],\"fees\":\"Die Beratung ist kostenlos.\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10115737','Internationaler Fahrzeugschein','https://service.berlin.de/dienstleistung/10115737/','Sonstiges','{\"id\":\"10115737\",\"name\":\"Internationaler Fahrzeugschein\",\"description\":\"Ein Internationaler Fahrzeugschein ist die \\u00dcbersetzung (in andere Sprachen) des nationalen Fahrzeugscheins. Sie ben\\u00f6tigen diesen, wenn Sie mit einem in Deutschland angemeldeten Fahrzeug vor\\u00fcbergehend au\\u00dferhalb Europas fahren wollen. Wir empfehlen Ihnen bei der zust\\u00e4ndigen Auslandsvertretung des jeweiligen Landes nachzufragen, ob ein internationaler Fahrzeugschein erforderlich ist.<br \\/>\\n<br \\/>\\nDer internationale Fahrzeugschein wird zus\\u00e4tzlich zur vorhandenen Zulassungsbescheinigung Teil 1 (Fahrzeugschein) erstellt und ist ein Jahr g\\u00fcltig.\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10115737\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10416\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10115737\\/locations\\/10416\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10115737\\/locations\\/10416\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99085005000000\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10115737,1064268,1064345,1064374],\"fees\":\"10,50 Euro\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10176294','Abholung von Führerscheinen','https://service.berlin.de/dienstleistung/10176294/','Sonstiges','{\"id\":\"10176294\",\"name\":\"Abholung von F\\u00fchrerscheinen\",\"description\":\"<p>Sollte der F\\u00fchrerschein nicht innerhalb eines Jahres abgeholt werden, wird der Antrag eingestellt und der F\\u00fchrerschein vernichtet.<\\/p><p>Wenn Sie dazu Fragen haben, dann k\\u00f6nnen Sie uns \\u00fcber unser <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktformularfahrerlaubnisbehoerde\\/index\\\" target=\\\"\\\">Kontaktformular<\\/a> und telefonisch erreichen oder online einen Termin vereinbaren.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10176294\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1094898\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176294\\/locations\\/1094898\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176294\\/locations\\/1094898\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99023001015000\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":5,\"combinable\":[10176294]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10176300','Entziehung des Führerscheins','https://service.berlin.de/dienstleistung/10176300/','Sonstiges','{\"id\":\"10176300\",\"name\":\"Entziehung des F\\u00fchrerscheins\",\"description\":\"<p><strong>Allgemeine Informationen<\\/strong><\\/p><p>Sie haben Fragen zum weiteren Ablauf, nachdem Sie<\\/p><ul><li>von der Fahrerlaubnisbeh\\u00f6rde bereits angeh\\u00f6rt worden sind, weil Ihnen die ausl\\u00e4ndische Fahrerlaubnis aberkannt oder entzogen, die Erteilung der Fahrerlaubnis versagt wurde oder Ihnen untersagt wurde, fahrerlaubnisfreie Fahrzeuge zu f\\u00fchren.<\\/li><li>einen Bescheid bekommen haben \\u00fcber die Entziehung oder Aberkennung der ausl\\u00e4ndischen Fahrerlaubnis, die Versagung der Erteilung einer Fahrerlaubnis oder die Untersagung fahrerlaubnisfreie Fahrzeuge f\\u00fchren zu d\\u00fcrfen.<\\/li><\\/ul><p>In diesem Fall erreichen Sie uns per E-Mail und telefonisch.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Entziehung, Aberkennung ausl\\u00e4ndischer F\\u00fchrerschein\",\"translated\":true,\"hash\":\"\",\"id\":\"10176300\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10387996\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176300\\/locations\\/10387996\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176300\\/locations\\/10387996\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99023001000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":45,\"combinable\":[10176300]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10176306','Beratung zur Fahreignung','https://service.berlin.de/dienstleistung/10176306/','Sonstiges','{\"id\":\"10176306\",\"name\":\"Beratung zur Fahreignung\",\"description\":\"<p><strong>Allgemeine Informationen<\\/strong><\\/p><ul><li>Sie hatten einen Unfall oder leiden an einer Erkrankung, die Sie beim F\\u00fchren eines Kraftfahrzeuges einschr\\u00e4nkt<\\/li><li>Sie f\\u00fchlen sich den Anforderungen des Stra\\u00dfenverkehrs nicht mehr gewachsen oder machen sich Sorgen, dass eine Ihnen bekannte Person nicht mehr dem Stra\\u00dfenverkehr gewachsen ist.<\\/li><\\/ul><p>Wenn Sie dazu Fragen haben, k\\u00f6nnen Sie sich schriftlich oder telefonisch an uns wenden.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10176306\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10387997\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176306\\/locations\\/10387997\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10176306\\/locations\\/10387997\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99075002000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\