INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10216076','Medizinische Rehabilitation','https://service.berlin.de/dienstleistung/10216076/','Sonstiges','{\"id\":\"10216076\",\"name\":\"Medizinische Rehabilitation\",\"description\":\"<p>In der gesetzlichen Rentenversicherung sollen durch Ma\\u00dfnahmen zur Rehabilitation funktionelle Einschr\\u00e4nkungen im Arbeitsleben infolge von Krankheit oder Behinderung ausgeglichen werden. Ziel ist es, weiter im Beruf zu bleiben oder wieder arbeiten zu k\\u00f6nnen. Neben den Leistungen zur medizinischen Rehabilitation k\\u00f6nnen auch erg\\u00e4nzende Leistungen, zum Beispiel Zahlung von \\u00dcbergangsgeld, erbracht werden.<\\/p><p>Die Sachbearbeiter f\\u00fcllen die Antragsformulare \\u201eonline\\u201c aus und leiten diese unmittelbar an den zust\\u00e4ndigen Rentenversicherungstr\\u00e4ger weiter. Dadurch ist eine zeitnahe und vollst\\u00e4ndige Bearbeitung durch den Rentenversicherungstr\\u00e4ger gew\\u00e4hrleistet.<\\/p><p>K\\u00f6nnen Sie selbst nicht kommen, dann kann auch ein Bevollm\\u00e4chtigter - mit schriftlicher Vollmacht - den Antrag f\\u00fcr Sie stellen<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10216076\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10515\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216076\\/locations\\/10515\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216076\\/locations\\/10515\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99134024000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10216076]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10216084','Beitragserstattung aus der Rentenversicherung','https://service.berlin.de/dienstleistung/10216084/','Sonstiges','{\"id\":\"10216084\",\"name\":\"Beitragserstattung aus der Rentenversicherung\",\"description\":\"<ul><li>Mit einer Beitragserstattung k\\u00f6nnen gezahlte Rentenversicherungsbeitr\\u00e4ge an Versicherte beziehungsweise an deren Hinterbliebene \\u2013 auf Antrag \\u2013 zur\\u00fcckgezahlt werden. Eine Beitragserstattung kommt in der Regel bei Beamten, die sich bereits in einem Beamtenverh\\u00e4ltnis auf Lebenszeit befinden, in Frage, wenn sie Beitr\\u00e4ge in die gesetzliche Rentenversicherung gezahlt haben, aber dort die allgemeine Wartezeit noch nicht erf\\u00fcllt haben.<\\/li><li>Bei Ihrem Termin f\\u00fcllen wir die Antragsformulare aus und leiten diese unmittelbar an den zust\\u00e4ndigen Rentenversicherungstr\\u00e4ger weiter. Dadurch ist eine zeitnahe und vollst\\u00e4ndige Bearbeitung durch den Rentenversicherungstr\\u00e4ger gew\\u00e4hrleistet.<br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10216084\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10515\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216084\\/locations\\/10515\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216084\\/locations\\/10515\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10216084]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10216196','Aufenthalt zur medizinischen Behandlung – Privatpatienten und Selbstzahler','https://service.berlin.de/dienstleistung/10216196/','Sonstiges','{\"id\":\"10216196\",\"name\":\"Aufenthalt zur medizinischen Behandlung \\u2013 Privatpatienten und Selbstzahler\",\"description\":\"<p>Aufenthaltserlaubnis zur medizinischen Behandlung f\\u00fcr Privatpatienten und Selbstzahler sowie zur Betreuung durch einen medizinischen Dienstleister.<\\/p>\\n<p>\\u200b <strong>Visumverfahren<\\/strong><\\/p>\\n<p>In vielen F\\u00e4llen brauchen Sie ein g\\u00fcltiges nationales Visum (Typ D). Das nationale Visum wird entweder durch die deutsche Auslandsvertretung oder durch die Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung ausgestellt. Ein Schengen-Visum (Typ C) kann nur unter bestimmten Voraussetzungen als nationales Visum (Typ D) verl\\u00e4ngert werden.<\\/p>\\n<p><strong>Nach der Einreise<\\/strong><\\/p>\\n<p>Sie m\\u00fcssen zuerst Ihren Wohnsitz im <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\\\">B\\u00fcrgerb\\u00fcro<\\/a> anmelden.<\\/p>\\n<p><strong>Antragstellung und Termin<\\/strong><\\/p>\\n<p>Bitte reichen Sie das <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\">Antragsformular<\\/a> sowie die erforderlichen Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/med_behandlung\\/index\\\">online<\\/a> oder per Post ein. Nach Absenden Ihres Online-Antrags k\\u00f6nnen Sie ein ausgef\\u00fclltes Dokument als PDF f\\u00fcr Ihre Unterlagen herunterladen. In dem Dokument wird Ihnen die Antragstellung und die Erlaubnis\\/ Fortgeltung Ihres bisherigen Aufenthalts best\\u00e4tigt. Nach Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin zur pers\\u00f6nlichen Vorsprache.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10216196\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10455\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216196\\/locations\\/10455\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216196\\/locations\\/10455\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10483136\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216196\\/locations\\/10483136\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216196\\/locations\\/10483136\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Deutschland einfach freundlich\",\"link\":\"https:\\/\\/www.germany.travel\\/de\\/specials\\/medizin\\/wichtig-zu-wissen\\/wichtig-zu-wissen.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Deutschland einfach freundlich\",\"link\":\"https:\\/\\/www.germany.travel\\/de\\/specials\\/medizin\\/wichtig-zu-wissen\\/wichtig-zu-wissen.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":4,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10216196]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10216637','Fischereiaufseher - Bestätigung von Fischeraufsehern','https://service.berlin.de/dienstleistung/10216637/','Sonstiges','{\"id\":\"10216637\",\"name\":\"Fischereiaufseher - Best\\u00e4tigung von Fischeraufsehern\",\"description\":\"<p><strong>Aufgaben\\/Pflichten<\\/strong><\\/p>\\n<ul>\\n <li>\\u00dcberwachung der Einhaltung von Rechtsvorschriften, die den Schutz und die Erhaltung der Fischbest\\u00e4nde sowie die Aus\\u00fcbung der Fischerei regeln<\\/li>\\n <li>Feststellung, Verh\\u00fctung, Unterbindung und Mitwirkung bei der Verfolgung einschl\\u00e4giger Verst\\u00f6\\u00dfe, die mit Strafe oder Geldbu\\u00dfe bedroht sind<\\/li>\\n <li>Anzeige von Fischsterben<\\/li>\\n <li>Sichtbares Tragen eines Dienstabzeichens bei T\\u00e4tigkeitsaus\\u00fcbung<\\/li>\\n <li>Vorlage des Dienstausweises bei dienstlichem Einschreiten auf Verlangen, sofern aus Sicherheitsgr\\u00fcnden zumutbar<\\/li>\\n <li>Ausstellen von Bescheinigungen sichergestellter Sachen<\\/li>\\n<\\/ul>\\n<p><strong>Befugnisse<\\/strong><\\/p>\\n<ul>\\n <li>Anhalten und Betreten von Wasserfahrzeugen, von denen aus Fischfang betrieben wird<\\/li>\\n <li>Betreten von Grundst\\u00fccken (nicht Wohnungen und Hausg\\u00e4rten) bei dienstlichem Einschreiten<\\/li>\\n <li>Befahren von Gew\\u00e4ssern (gegebenenfalls mit gesonderter Genehmigung)\\n  <ul>\\n   <li>bei Personen, die auf, an oder in der N\\u00e4he von Gew\\u00e4ssern mit Fangger\\u00e4ten angetroffen werden<\\/li>\\n   <li>Identit\\u00e4tsfeststellung<\\/li>\\n   <li>\\u00dcberpr\\u00fcfung des Fischereischeins\\/ Jugendfischereischeins und Erlaubnisscheins<\\/li>\\n   <li>Besichtigung der mitgef\\u00fchrten Fangger\\u00e4te und der gefangenen Fische (auch in Fahrzeugen) sowie der Fischbeh\\u00e4lter<\\/li>\\n  <\\/ul><\\/li>\\n <li>bei Verdacht einer Zuwiderhandlung zwecks deren Verh\\u00fctung oder Unterbindung\\n  <ul>\\n   <li>Identit\\u00e4tsfeststellung<\\/li>\\n   <li>Platzverweisung<\\/li>\\n   <li>Sicherstellung von Fischen und anderen Sachen, die unberechtigt erlangt worden sind oder bei Zuwiderhandlungen gegen Rechtsvorschriften verwendet wurden oder verwendet werden sollen.<\\/li>\\n  <\\/ul><\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10216637\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216637\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10216637\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bayerisches Fischereigesetz (BayFiG)\",\"link\":\"https:\\/\\/www.gesetze-bayern.de\\/Content\\/Document\\/BayFischG?AspxAutoDetectCookieSupport=1\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bayerisches Fischereigesetz (BayFiG)\",\"link\":\"https:\\/\\/www.gesetze-bayern.de\\/Content\\/Document\\/BayFischG?AspxAutoDetectCookieSupport=1\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10216637],\"fees\":\"Es fallen keine Geb\\u00fchren an.\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10218156','Aufenthaltsgestattung für das Asylverfahren','https://service.berlin.de/dienstleistung/10218156/','Sonstiges','{\"id\":\"10218156\",\"name\":\"Aufenthaltsgestattung f\\u00fcr das Asylverfahren\",\"description\":\"<p>Die Aufenthaltsgestattung ist ein Dokument, das w\\u00e4hrend der Durchf\\u00fchrung eines Asylverfahrens ausgestellt wird. Sie bescheinigt, dass der Aufenthalt im Bundesgebiet zum Zweck der Durchf\\u00fchrung des Asylverfahrens gestattet ist. Die Aufenthaltsgestattung enth\\u00e4lt Angaben zur Person und ein biometrisches Lichtbild.<\\/p>\\n<p>Sie kann f\\u00fcr maximal 6 Monate erteilt und verl\\u00e4ngert werden. In der Aufenthaltsgestattung werden Auflagen und Nebenbestimmungen zur Besch\\u00e4ftigung, zur Wohnsitzverpflichtung und zur r\\u00e4umlichen Beschr\\u00e4nkung eingetragen. Sie enth\\u00e4lt das Datum der Asylantragstellung und das Aktenzeichen, unter dem der Asylantrag beim Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge (BAMF) bearbeitet wird.<\\/p>\\n<p>Die Aufenthaltsgestattung erlischt automatisch, wenn die Entscheidung des BAMF vollziehbar geworden ist.<\\/p>\\n<p>Die Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung ist f\\u00fcr die Ausstellung oder Verl\\u00e4ngerung der Aufenthaltsgestattung nur zust\\u00e4ndig, wenn Sie im Stadtgebiet M\\u00fcnchen gemeldet sind und uns die Zentrale Ausl\\u00e4nderbeh\\u00f6rde Oberbayern die Zust\\u00e4ndigkeit f\\u00fcr Sie \\u00fcbertragen hat.<\\/p>\\n<p>Eine Neuzuweisung liegt vor, wenn Sie einen Zuweisungsbescheid der Regierung von Oberbayern f\\u00fcr die Landeshauptstadt M\\u00fcnchen erhalten haben.<\\/p>\\n<p>Eine Umverteilung liegt vor, wenn Sie bei der bisher f\\u00fcr Sie zust\\u00e4ndigen Ausl\\u00e4nderbeh\\u00f6rde einen Antrag auf Umverteilung gestellt haben und der Zuzug nach M\\u00fcnchen genehmigt wurde.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Asyl\",\"translated\":true,\"hash\":\"\",\"id\":\"10218156\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10308685\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/10308685\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/10308685\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1062496\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/1062496\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218156\\/locations\\/1062496\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99010004000000\",\"public\":false,\"links\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/DSGVO.html\",\"description\":false},{\"name\":\"Wohnsitz in M\\u00fcnchen anmelden (B\\u00fcrgerb\\u00fcro)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung zum Besch\\u00e4ftigungsverh\\u00e4ltnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_zum_Beschaeftigungsverhaeltnis.pdf\",\"description\":false},{\"name\":\"Umverteilungsantrag f\\u00fcr Asylbewerber\",\"link\":\"https:\\/\\/www.regierung.oberbayern.bayern.de\\/aufgaben\\/224354\\/168692\\/leistung\\/leistung_55265\\/index.html\",\"description\":false}],\"forms\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/DSGVO.html\",\"description\":false},{\"name\":\"Wohnsitz in M\\u00fcnchen anmelden (B\\u00fcrgerb\\u00fcro)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung zum Besch\\u00e4ftigungsverh\\u00e4ltnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_zum_Beschaeftigungsverhaeltnis.pdf\",\"description\":false},{\"name\":\"Umverteilungsantrag f\\u00fcr Asylbewerber\",\"link\":\"https:\\/\\/www.regierung.oberbayern.bayern.de\\/aufgaben\\/224354\\/168692\\/leistung\\/leistung_55265\\/index.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10218156],\"fees\":\"<p>Keine Geb\\u00fchr<br><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10218159','Aufenthaltserlaubnis – Flüchtlingseigenschaft und Reiseausweis für Flüchtlinge','https://service.berlin.de/dienstleistung/10218159/','Sonstiges','{\"id\":\"10218159\",\"name\":\"Aufenthaltserlaubnis \\u2013 Fl\\u00fcchtlingseigenschaft und Reiseausweis f\\u00fcr Fl\\u00fcchtlinge\",\"description\":\"<p>Die Aufenthaltserlaubnis wird f\\u00fcr drei Jahre erteilt. Die Verl\\u00e4ngerung erfolgt f\\u00fcr drei Jahre. Der Reiseausweis f\\u00fcr Fl\\u00fcchtlinge wird f\\u00fcr drei Jahre ausgestellt. Die Verl\\u00e4ngerung erfolgt f\\u00fcr drei Jahre.<\\/p><p>Mit der Aufenthaltserlaubnis haben Sie einen uneingeschr\\u00e4nkten Zugang zum deutschen Arbeitsmarkt, das hei\\u00dft eine unselbst\\u00e4ndige und selbst\\u00e4ndige Erwerbst\\u00e4tigkeit sind erlaubt.<\\/p><p>Mit der Aufenthaltserlaubnis haben Sie einen Anspruch auf Teilnahme an einem Integrationskurs.<\\/p><p>Sie sind verpflichtet in dem Bundesland zu wohnen, in dem das Asylverfahren durchgef\\u00fchrt wurde, wenn der Anerkennungsbescheid des Bundesamtes f\\u00fcr Migration und Fl\\u00fcchtlinge ab dem 1.1.2016 erlassen wurde und Leistungen nach dem Sozialgesetzbuch II bezogen werden.<\\/p><p>Hinweis:<\\/p><p>Eine Wohnsitzbeschr\\u00e4nkung besteht nicht, wenn Ihr Ehegatte, eingetragener Lebenspartner oder minderj\\u00e4hriges Kind<\\/p><ul><li>eine sozialversicherungspflichtige Besch\\u00e4ftigung mit einem Umfang von mindestens 15 Stunden w\\u00f6chentlich aufnimmt oder aufgenommen hat, durch die diese Person mindestens \\u00fcber ein Einkommen in H\\u00f6he des monatlichen durchschnittlichen Bedarfs nach den \\u00a7\\u00a7 20, 22 SGB II f\\u00fcr eine Einzelperson verf\\u00fcgt oder<\\/li><li>eine Berufsausbildung aufnimmt oder aufgenommen hat oder<\\/li><li>in einem Studien- oder Ausbildungsverh\\u00e4ltnis steht.<\\/li><\\/ul><p>Da es sich um eine sozialversicherungspflichtige Besch\\u00e4ftigung handeln muss, reichen Minijobs und geringf\\u00fcgige Besch\\u00e4ftigungen nicht aus, um eine Wohnsitzbeschr\\u00e4nkungsfreiheit zu begr\\u00fcnden.<\\/p><p>Wenn eine Wohnsitzbeschr\\u00e4nkung besteht, kann diese auf Antrag aufgehoben werden. Daf\\u00fcr m\\u00fcssen die Voraussetzungen nach \\u00a7 12a Abs. 5 AufenthG vorliegen. Der Antrag muss bei der Ausl\\u00e4nderbeh\\u00f6rde gestellt werden, die f\\u00fcr Ihren aktuellen Wohnort zust\\u00e4ndig ist.<\\/p><p>Schutzberechtigte Personen, denen die Fl\\u00fcchtlingseigenschaft zuerkannt worden ist, haben das Recht auf privilegierten Familiennachzug. Das bedeutet, dass kein Nachweis der Lebensunterhaltssicherung und ausreichenden Wohnraums als Voraussetzung f\\u00fcr die Einreise der Familienangeh\\u00f6rigen notwendig ist. Dies gilt f\\u00fcr den Nachzug der Ehegattin beziehungsweise des Ehegatten und der minderj\\u00e4hrigen ledigen Kinder.<\\/p><p>Hierf\\u00fcr muss der entsprechende Antrag innerhalb von drei Monaten nach Zuerkennung der Schutzberechtigung bei der f\\u00fcr den Aufenthaltsort der Familienangeh\\u00f6rigen zust\\u00e4ndigen deutschen Auslandsvertretung gestellt werden. Wird der Antrag sp\\u00e4ter gestellt, besteht kein Anspruch auf den Nachzug, sondern die Auslandsvertretung entscheidet nach Ermessen.<\\/p><p>F\\u00fcr den Familiennachzug zu Schutzberechtigten aus Syrien sollte der Antrag \\u00fcber das Webportal des Ausw\\u00e4rtigen Amtes elektronisch gestellt werden<\\/p><p>Solange das Asylverfahren l\\u00e4uft, kann grunds\\u00e4tzlich kein Familiennachzug erfolgen.<\\/p><p>Auslandsreisen sind mit dem Reiseausweis f\\u00fcr Fl\\u00fcchtlinge jederzeit m\\u00f6glich. Bitte beachten Sie die Visa- und Einreisebestimmungen des jeweiligen Auslandsreiseziels.<\\/p><p>Der Reiseausweis f\\u00fcr Fl\\u00fcchtlinge berechtigt nicht in das jeweilige Herkunftsland zu reisen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Blaupassinhaber, Humanit\\u00e4rer Aufenthalt, Fl\\u00fcchtling, Jeanspass, Wohnsitzbeschr\\u00e4nkung, Reiseausweis f\\u00fcr Fl\\u00fcchtlinge\",\"translated\":true,\"hash\":\"\",\"id\":\"10218159\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218159\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218159\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059485\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218159\\/locations\\/1059485\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218159\\/locations\\/1059485\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Online-Auskunft Bearbeitungsstand\",\"link\":\"https:\\/\\/www17.muenchen.de\\/EATWebSearch\\/\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"B\\u00fcrgerb\\u00fcro\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag  auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Antrag Reiseausweis f\\u00fcr Fl\\u00fcchtlinge\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:0b5afc09-d0ee-4aa8-89c4-f571acce7311\\/Antrag%20_Reiseausweise.pdf\",\"description\":false},{\"name\":\"Integrationskurs\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/DeutschLernen\\/Integrationskurse\\/integrationskurse-node.html\",\"description\":false},{\"name\":\"Wohnsitzbeschr\\u00e4nkung\",\"link\":\"https:\\/\\/www.gesetze-im-internet.de\\/aufenthg_2004\\/__12a.html\",\"description\":false},{\"name\":\"Familiennachzug zu anerkannten Fl\\u00fcchtlingen\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/AsylFluechtlingsschutz\\/FamilienasylFamiliennachzug\\/familienasylfamiliennachzug-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu Schutzberechtigten aus Syrien\",\"link\":\"https:\\/\\/familyreunion-syria.diplo.de\\/webportal\\/desktop\\/index.html#start\",\"description\":false}],\"forms\":[{\"name\":\"Online-Auskunft Bearbeitungsstand\",\"link\":\"https:\\/\\/www17.muenchen.de\\/EATWebSearch\\/\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"B\\u00fcrgerb\\u00fcro\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag  auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Antrag Reiseausweis f\\u00fcr Fl\\u00fcchtlinge\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:0b5afc09-d0ee-4aa8-89c4-f571acce7311\\/Antrag%20_Reiseausweise.pdf\",\"description\":false},{\"name\":\"Integrationskurs\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/DeutschLernen\\/Integrationskurse\\/integrationskurse-node.html\",\"description\":false},{\"name\":\"Wohnsitzbeschr\\u00e4nkung\",\"link\":\"https:\\/\\/www.gesetze-im-internet.de\\/aufenthg_2004\\/__12a.html\",\"description\":false},{\"name\":\"Familiennachzug zu anerkannten Fl\\u00fcchtlingen\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/AsylFluechtlingsschutz\\/FamilienasylFamiliennachzug\\/familienasylfamiliennachzug-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu Schutzberechtigten aus Syrien\",\"link\":\"https:\\/\\/familyreunion-syria.diplo.de\\/webportal\\/desktop\\/index.html#start\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10218159],\"fees\":\"<p>F\\u00fcr die Ausstellung der Aufenthaltserlaubnis fallen keine Geb\\u00fchren an.<br>F\\u00fcr die Ausstellung eines Reiseausweises f\\u00fcr Fl\\u00fcchtlinge fallen 60 Euro Geb\\u00fchr an.<br>F\\u00fcr die Ausstellung eines Reiseausweises f\\u00fcr Fl\\u00fcchtlinge bis zum vollendeten 24. Lebensjahr fallen 38 Euro an Geb\\u00fchren an.<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10218162','Aufenthaltserlaubnis – subsidiär Schutzberechtigte','https://service.berlin.de/dienstleistung/10218162/','Sonstiges','{\"id\":\"10218162\",\"name\":\"Aufenthaltserlaubnis \\u2013 subsidi\\u00e4r Schutzberechtigte\",\"description\":\"<p>Die Aufenthaltserlaubnis wird f\\u00fcr drei Jahre erteilt und kann f\\u00fcr drei Jahre verl\\u00e4ngert werden.\\n <br><\\/p>\\n<p>Die Aufenthaltserlaubnis wird auf einem Ausweisersatz ausgestellt, wenn kein g\\u00fcltiger Nationalpass vorhanden ist.<\\/p>\\n<p>Mit dem Ausweisersatz ist keine Auslandsreise m\\u00f6glich. F\\u00fcr Auslandsreisen ist in der Regel ein g\\u00fcltiger Nationalpass n\\u00f6tig.<\\/p>\\n<p>Mit der Aufenthaltserlaubnis haben Sie einen uneingeschr\\u00e4nkten Zugang zum deutschen Arbeitsmarkt, das hei\\u00dft eine unselbst\\u00e4ndige und selbst\\u00e4ndige Erwerbst\\u00e4tigkeit sind erlaubt.<\\/p>\\n<p>Mit der Aufenthaltserlaubnis haben Sie einen Anspruch auf Teilnahme an einem Integrationskurs. Sie sind verpflichtet in dem Bundesland zu wohnen, in dem das Asylverfahren durchgef\\u00fchrt wurde, wenn der Anerkennungsbescheid des Bundesamtes f\\u00fcr Migration und Fl\\u00fcchtlinge ab dem 1. Januar 2016 erlassen wurde und Leistungen nach dem Sozialgesetzbuch II bezogen werden.<\\/p>\\n<p>Eine Wohnsitzbeschr\\u00e4nkung besteht nicht, wenn Ihr Ehegatte, eingetragener Lebenspartner oder minderj\\u00e4hriges Kind<\\/p>\\n<ul>\\n <li>eine sozialversicherungspflichtige Besch\\u00e4ftigung mit einem Umfang von mindestens 15 Stunden w\\u00f6chentlich aufnimmt oder aufgenommen hat, durch die diese Person mindestens \\u00fcber ein Einkommen in H\\u00f6he des monatlichen durchschnittlichen Bedarfs nach den \\u00a7\\u00a7 20, 22 SGB II f\\u00fcr eine Einzelperson verf\\u00fcgt, oder<\\/li>\\n <li>eine Berufsausbildung aufnimmt oder aufgenommen hat oder<\\/li>\\n <li>in einem Studien- oder Ausbildungsverh\\u00e4ltnis steht.<\\/li>\\n<\\/ul>\\n<p>Da es sich um eine sozialversicherungspflichtige Besch\\u00e4ftigung handeln muss, reichen Minijobs und geringf\\u00fcgige Besch\\u00e4ftigungen nicht aus, um eine Wohnsitzbeschr\\u00e4nkungsfreiheit zu begr\\u00fcnden.<\\/p>\\n<p>Wenn eine Wohnsitzbeschr\\u00e4nkung besteht, kann diese auf Antrag aufgehoben werden. Daf\\u00fcr m\\u00fcssen die Voraussetzungen nach \\u00a7 12a Abs. 5 AufenthG vorliegen. Der Antrag muss bei der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung gestellt werden, die f\\u00fcr Ihren aktuellen Wohnort zust\\u00e4ndig ist.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Subsidi\\u00e4rer, Humanit\\u00e4rer Aufenthalt, Nationalpass, Wohnsitzbeschr\\u00e4nkung, Fl\\u00fcchtling, Ausweisersatz\",\"translated\":true,\"hash\":\"\",\"id\":\"10218162\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218162\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10218162\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Sozialreferat\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/Stadtverwaltung\\/Sozialreferat\\/Fluechtlinge.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden oder ummelden\",\"link\":\"http:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Informationen zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"http:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Integrationskurs\",\"link\":\"http:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/DeutschLernen\\/Integrationskurse\\/integrationskurse-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu anerkannten Fl\\u00fcchtlingen\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/MigrationAufenthalt\\/ZuwandererDrittstaaten\\/Familie\\/NachzugZuDrittstaatlern\\/nachzug-zu-drittstaatlern-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu Schutzberechtigten aus Syrien\",\"link\":\"https:\\/\\/familyreunion-syria.diplo.de\\/webportal\\/desktop\\/index.html#start\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Sozialreferat\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/Stadtverwaltung\\/Sozialreferat\\/Fluechtlinge.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden oder ummelden\",\"link\":\"http:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Informationen zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"http:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Integrationskurs\",\"link\":\"http:\\/\\/www.bamf.de\\/DE\\/Willkommen\\/DeutschLernen\\/Integrationskurse\\/integrationskurse-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu anerkannten Fl\\u00fcchtlingen\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/MigrationAufenthalt\\/ZuwandererDrittstaaten\\/Familie\\/NachzugZuDrittstaatlern\\/nachzug-zu-drittstaatlern-node.html\",\"description\":false},{\"name\":\"Familiennachzug zu Schutzberechtigten aus Syrien\",\"link\":\"https:\\/\\/familyreunion-syria.diplo.de\\/webportal\\/desktop\\/index.html#start\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10218162],\"fees\":\"<ul>\\n <li>Ersterteilung der Aufenthaltserlaubnis: 100 Euro<\\/li>\\n <li>Verl\\u00e4ngerung der Aufenthaltserlaubnis f\\u00fcr zwei Jahre: 93 Euro<\\/li>\\n <li>Ausweisersatz: 32 Euro<\\/li>\\n<\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10224132','Wohnsitzanmeldung – Familie','https://service.berlin.de/dienstleistung/10224132/','Sonstiges','{\"id\":\"10224132\",\"name\":\"Wohnsitzanmeldung \\u2013 Familie\",\"description\":\"<p>Die An- oder Ummeldung Ihres Wohnsitzes als Familie k\\u00f6nnen Sie entweder online oder pers\\u00f6nlich in einem der B\\u00fcrgerb\\u00fcros vornehmen. Dabei ist es ausreichend, wenn ein Elternteil pers\\u00f6nlich erscheint oder eine bevollm\\u00e4chtigte Person die Anmeldung \\u00fcbernimmt. Minderj\\u00e4hrige Kinder werden dabei automatisch mitangemeldet \\u2013 eine pers\\u00f6nliche Vorsprache der Kinder ist nicht erforderlich.<\\/p>\\n<p><strong>Der Online-Service ist nur f\\u00fcr Hauptwohnsitze m\\u00f6glich. Eine An- oder Ummeldung von Nebenwohnsitzen ist online nicht m\\u00f6glich.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10224132\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224132\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224132\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102523\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":