INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10224136','Änderung der Personendaten im Melderegister','https://service.berlin.de/dienstleistung/10224136/','Sonstiges','{\"id\":\"10224136\",\"name\":\"\\u00c4nderung der Personendaten im Melderegister\",\"description\":\"<p><strong>Eheschlie\\u00dfung im Ausland:<\\/strong><\\/p>\\n<p>Grunds\\u00e4tzlich werden im Ausland geschlossene Ehen in der Bundesrepublik Deutschland anerkannt. Allerdings m\\u00fcssen alle Voraussetzungen f\\u00fcr die Eheschlie\\u00dfung nach dem Recht des Staates erf\\u00fcllt sein, in dem die Ehe geschlossen wurde.<\\/p>\\n<p><strong>Ehescheidung im Ausland<\\/strong>:<\\/p>\\n<p>Grunds\\u00e4tzlich bed\\u00fcrfen ausl\\u00e4ndische Scheidungen oder vergleichbare Entscheidungen der Anerkennung durch das Oberlandesgericht.<\\/p>\\n<p>Die Anerkennung ist nicht erforderlich<\\/p>\\n<ul>\\n <li>wenn beide Ehegatten zum Zeitpunkt der Entscheidung ausschlie\\u00dflich dem Staat angeh\\u00f6rten, dessen Gericht oder Beh\\u00f6rde die Entscheidung getroffen hat (Heimatstaatenentscheidungen).<\\/li>\\n <li>in Ehesachen aus Mitgliedstaaten der Europ\\u00e4ischen Union - au\\u00dfer D\\u00e4nemark<\\/li>\\n<\\/ul>\\n<p><strong>Namens\\u00e4nderung aufgrund einer Eheschlie\\u00dfung oder Ehescheidung im Ausland:<\\/strong><\\/p>\\n<p>Die Namensf\\u00fchrung der Ehepartner richtet sich nach dem jeweiligen Heimatrecht. Falls ein Ehegatte eine ausl\\u00e4ndische Staatsangeh\\u00f6rigkeit besitzt, ist f\\u00fcr die Eintragung in das Melderegister die Namensf\\u00fchrung des ausl\\u00e4ndischen Passes ma\\u00dfgeblich. Die ausl\\u00e4ndische Eheschlie\\u00dfungsurkunde findet keine Beachtung.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10224136\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102523\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102523\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102523\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102524\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102524\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10224136\\/locations\\/102524\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102526\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":