INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10225197','Widerruf der Verlust- oder Diebstahlanzeige von Personalausweis oder Reisepass','https://service.berlin.de/dienstleistung/10225197/','Sonstiges','{\"id\":\"10225197\",\"name\":\"Widerruf der Verlust- oder Diebstahlanzeige von Personalausweis oder Reisepass\",\"description\":\"<p>Alle verlorenen oder gestohlenen Ausweisdokumente werden in der Inpol-Sachfahndung der Polizei ausgeschrieben, um Missbrauch zu vermeiden. Das B\\u00fcrgerb\\u00fcro muss die Sachfahndung in Zusammenarbeit mit der Polizei l\\u00f6schen, sobald der Ausweis wieder gefunden wurde.<\\/p>\\n<p>Sie k\\u00f6nnen Ihr B\\u00fcrgerb\\u00fcro schriftlich benachrichtigen oder pers\\u00f6nlich vorbeikommen. Wenn bei Ihrem Personalausweis vor dem Verlust die Online-Ausweisfunktion aktiviert war, m\\u00fcssen Sie pers\\u00f6nlich vorsprechen, um diese \\u2013nach der Sperrung\\u2013 wieder zu reaktivieren.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10225197\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10225197\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10225197\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102523\",\"