INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10300814','Zulassung Taxi oder Mietwagen','https://service.berlin.de/dienstleistung/10300814/','Sonstiges','{\"id\":\"10300814\",\"name\":\"Zulassung Taxi oder Mietwagen\",\"description\":\"<p>Sie haben die M\\u00f6glichkeit, ein Wunschkennzeichen zu reservieren.<br>Kfz-Zulassungsdienste und H\\u00e4ndler erhalten ihren Service nur direkt bei der Zulassungsbeh\\u00f6rde (nicht beim Gewerblichen Kraftverkehr). Die vorzulegenden Unterlagen k\\u00f6nnen in diesem Fall abweichen.<br>Ist das Fahrzeug finanziert und Sie erhalten die Zulassungsbescheinigung Teil II sowie die EG-\\u00dcbereinstimmungserkl\\u00e4rung nicht im Original ausgeh\\u00e4ndigt, kann die Zulassung nur in der Zulassungsbeh\\u00f6rde (nicht beim Gewerblichen Kraftverkehr) vorgenommen werden.<br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10300814\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1063278\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10300814\\/locations\\/1063278\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10300814\\/locations\\/1063278\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99084012001000\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wunschkennzeichen reservieren\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1064281\\/n0\\/\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wunschkennzeichen reservieren\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1064281\\/n0\\/\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":25,\"combinable\":[10300814,10300817],\"fees\":\"<div>\\nab 40 Euro (wenn besondere Unterlagen\\/Ausnahmen erforderlich sind - bis zu 250 Euro)<\\/div>\"}',NULL,NULL);
