INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10329989','Niederlassungserlaubnis für Personen im Beamtenverhältnis','https://service.berlin.de/dienstleistung/10329989/','Sonstiges','{\"id\":\"10329989\",\"name\":\"Niederlassungserlaubnis f\\u00fcr Personen im Beamtenverh\\u00e4ltnis\",\"description\":\"<p>Die Niederlassungserlaubnis ist ein unbefristeter Aufenthaltstitel, mit dem Sie ohne zeitliche oder \\u00f6rtliche Einschr\\u00e4nkung in Deutschland leben und arbeiten k\\u00f6nnen.<br><br>\\n Beamt*innen haben einen Anspruch auf die Erteilung einer Niederlassungserlaubnis, wenn sie seit drei Jahren in einem Beamtenverh\\u00e4ltnis zu einem deutschen Dienstherrn stehen und einen entsprechenden Aufenthaltstitel besitzen.<\\/p>\\n<p><strong>Antragstellung und Termin<\\/strong><\\/p>\\n<p>Bitte reichen Sie das <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\" target=\\\"_blank\\\">Antragsformular<\\/a> sowie die ben\\u00f6tigten Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/niederlassungserlaubnis\\/index\\\" target=\\\"_blank\\\">online<\\/a> oder per Post ein. Nach Absenden Ihres Online-Antrags k\\u00f6nnen Sie ein ausgef\\u00fclltes Dokument als PDF f\\u00fcr Ihre Unterlagen herunterladen. In dem Dokument wird Ihnen die Antragstellung und die Erlaubnis\\/ Fortgeltung Ihres bisherigen Aufenthalts best\\u00e4tigt. Nach Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin zur pers\\u00f6nlichen Vorsprache.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufenthalt, Verbeamtete, Ausl\\u00e4nderbeh\\u00f6rde M\\u00fcnchen, Unbefristeter, Arbeitsmigration, Dienstverh\\u00e4ltnis\",\"translated\":true,\"hash\":\"\",\"id\":\"10329989\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10446\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10329989\\/locations\\/10446\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10329989\\/locations\\/10446\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Wohnsitz in M\\u00fcnchen anmelden\",\"link\":\"https:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/DSGVO.html\",\"description\":false},{\"name\":\"\\u00dcbertrag des Aufenthaltstitels in den neuen Pass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1080729\\/\",\"description\":false},{\"name\":\"Informationen zum Erl\\u00f6schen der Niederlassungserlaubnis bei Auslandsaufenthalten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1081226\\/\",\"description\":false},{\"name\":\"Allgemeine Niederlassungserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1064106\\/\",\"description\":false},{\"name\":\"Antrag auf Niederlassungserlaubnis\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Best\\u00e4tigung \\u00fcber das Arbeitsverh\\u00e4ltnis\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Arbeitgeberbestaetigung.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung zum Lebensunterhalt\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_Lebensunterhalt.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung \\u00fcber die h\\u00e4usliche Gemeinschaft\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_haeusliche_Gemeinschaft.pdf\",\"description\":false},{\"name\":\"Wohnraumbescheinigung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Wohnraumbescheinigung.pdf\",\"description\":false},{\"name\":\"Biometrisches Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Wohnsitz in M\\u00fcnchen anmelden\",\"link\":\"https:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/DSGVO.html\",\"description\":false},{\"name\":\"\\u00dcbertrag des Aufenthaltstitels in den neuen Pass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1080729\\/\",\"description\":false},{\"name\":\"Informationen zum Erl\\u00f6schen der Niederlassungserlaubnis bei Auslandsaufenthalten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/haupt