INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10330030','Niederlassungserlaubnis aus völkerrechtlichen, humanitären oder politischen Gründen','https://service.berlin.de/dienstleistung/10330030/','Sonstiges','{\"id\":\"10330030\",\"name\":\"Niederlassungserlaubnis aus v\\u00f6lkerrechtlichen, humanit\\u00e4ren oder politischen Gr\\u00fcnden\",\"description\":\"<p>Die Niederlassungserlaubnis ist ein unbefristeter Aufenthaltstitel, mit dem Sie ohne zeitliche oder \\u00f6rtliche Einschr\\u00e4nkung in Deutschland leben und arbeiten k\\u00f6nnen.<\\/p>\\n<p>Sie k\\u00f6nnen eine Niederlassungserlaubnis beantragen, wenn Sie<\\/p>\\n<ul>\\n <li>seit 5 Jahren im Besitz einer Aufenthaltserlaubnis aus v\\u00f6lkerrechtlichen, humanit\\u00e4ren oder politischen Gr\\u00fcnden sind (\\u00a7\\u00a7 22-25 AufenthG) und das 16. Lebensjahr vollendet haben.<\\/li>\\n<\\/ul>\\n<p>Wenn Sie vom Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge (BAMF) eine Anerkennung als Asylberechtigter oder Fl\\u00fcchtling nach der Genfer Fl\\u00fcchtlingskonvention besitzen oder in Deutschland als Resettlement-Fl\\u00fcchtling aufgenommen wurden, besteht f\\u00fcr Sie auch die M\\u00f6glichkeit, eine Niederlassungserlaubnis nach \\u00a7 26 Abs. 3 AufenthG mit abweichenden Voraussetzungen zu beantragen.<\\/p>\\n<p><strong>Antragstellung und Termin<\\/strong><\\/p>\\n<p>Bitte reichen Sie das <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\" target=\\\"_blank\\\">Antragsformular<\\/a> sowie die ben\\u00f6tigten Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/niederlassungserlaubnis\\/index\\\" target=\\\"_blank\\\">online<\\/a> oder per Post ein. Nach Absenden Ihres Online-Antrags k\\u00f6nnen Sie ein ausgef\\u00fclltes Dokument als PDF f\\u00fcr Ihre Unterlagen herunterladen. In dem Dokument wird Ihnen die Antragstellung und die Erlaubnis\\/ Fortgeltung Ihres bisherigen Aufenthalts best\\u00e4tigt. Nach Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin zur pers\\u00f6nlichen Vorsprache. Sie k\\u00f6nnen auch ohne Termin zu unseren \\u00d6ffnungszeiten bei uns vorsprechen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Reiseausweis f\\u00fcr Fl\\u00fcchtlinge, Unbefristeter Aufenthalt, Daueraufenthaltsrecht, Unbefristete Aufenthaltserlaubnis, Humanit\\u00e4r, Ausl\\u00e4nderbeh\\u00f6rde M\\u00fcnchen\",\"translated\":true,\"hash\":\"\",\"id\":\"10330030\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059485\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1059485\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10330030\\/locations\\/1059485\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Wartezeitauskunft beim Versicherungsamt beantragen\",\"link\":\"https:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/10216090\\/\",\"description\":false},{\"name\":\"Wohnsitz in M\\u00fcnchen anmelden\",\"link\":\"https:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/DSGVO.html\",\"description\":false},{\"name\":\"Niederlassungserlaubnis ab 16 Jahren (f\\u00fcr Kinder)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten-auslaenderangelegenheiten\\/1064111\\/\",\"description\":false},{\"name\":\"Allgemeine Niederlassungserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1064106\\/\",\"description\":false},{\"name\":\"\\u00dcbertrag des Aufenthaltstitels in den neuen Pass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/1080729\\/\",\"description\":false},{\"name\":\"Informationen zum Erl\\u00f6schen der Niederlassungserlaubnis bei Auslandsaufenthalten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten\\/10812