INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10331792','Kfz-Angelegenheiten für auswärtige Autohäuser','https://service.berlin.de/dienstleistung/10331792/','Sonstiges','{\"id\":\"10331792\",\"name\":\"Kfz-Angelegenheiten f\\u00fcr ausw\\u00e4rtige Autoh\\u00e4user\",\"description\":\"<p>Als ausw\\u00e4rtiges Autohaus k\\u00f6nnen Sie f\\u00fcr die Erledigung Ihrer Kfz-Angelegenheiten neben den H\\u00e4ndlerf\\u00e4chern in der Kfz-Zulassungsbeh\\u00f6rde auch f\\u00fcr einzelne Zulassungen einen <a href=\\\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/terminvereinbarung.html#\\/services\\/10331792\\/locations\\/10308019\\\" target=\\\"_blank\\\">Termin vor Ort<\\/a> buchen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10331792\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308019\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10331792\\/locations\\/10308019\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10331792\\/locations\\/10308019\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat Fahrzeughalter*in\\/ Kontoinhaber*in\",\"link\"