INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10338647','Verlorenes Fahrrad besichtigen und abholen','https://service.berlin.de/dienstleistung/10338647/','Sonstiges','{\"id\":\"10338647\",\"name\":\"Verlorenes Fahrrad besichtigen und abholen\",\"description\":\"<p>Die Fahrr\\u00e4der, die Sie bei uns besichtigen k\\u00f6nnen, bekommen wir von der Polizei. Nur diese darf gefundene Fahrr\\u00e4der annehmen.<\\/p>\\n<p>F\\u00fcr die Besichtigung der R\\u00e4der im Fahrradkeller m\\u00fcssen Sie online einen Termin vereinbaren. Die Besichtigung findet dienstags in der Ruppertstra\\u00dfe 19, Eingang A, Raum U1001 statt.<\\/p>\\n<p>Wir k\\u00f6nnen Ihnen eine Versicherungsbest\\u00e4tigung ausstellen. Dazu ist eine polizeiliche Diebstahlanzeige erforderlich.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Fundamt, Fundb\\u00fcro, Fundfahrrad, Fundsache\",\"translated\":true,\"hash\":\"\",\"id\":\"10338647\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10352393\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338647\\/locations\\/10352393\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338647\\/locations\\/10352393\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Fahrrad als Finder*in abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10352189\\/\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Fahrrad als Finder*in abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10352189\\/\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10338647],\"fees\":\"<p>Siehe \\u00dcbersicht \\u201eKostenersatz\\u201c (zum Download erh\\u00e4ltlich)<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10338650','Verlustmeldung und Fundsachenbesichtigung','https://service.berlin.de/dienstleistung/10338650/','Sonstiges','{\"id\":\"10338650\",\"name\":\"Verlustmeldung und Fundsachenbesichtigung\",\"description\":\"<p>Informationen zur Verlustmeldung und zur Besichtigung von Fundsachen:<\\/p>\\n<ul>\\n <li>Wenn Sie Gegenst\\u00e4nde im Stadtgebiet verloren haben, k\\u00f6nnen Sie Ihren Verlust <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustanzeige\\/index\\\">online<\\/a> an das Fundb\\u00fcro melden. Sie erhalten eine R\\u00fcckmeldung, wenn der Gegenstand tats\\u00e4chlich bei uns registriert ist. Wir pr\\u00fcfen bis zu vier Monate nach Ihrer Meldung, ob die Fundsache abgegeben wurde. Wenn Sie nichts von uns h\\u00f6ren, konnten wir den Gegenstand nicht ermitteln.<\\/li>\\n <li>Bitte beachten Sie, dass es erfahrungsgem\\u00e4\\u00df oft einige Tage dauert, bis der Gegenstand tats\\u00e4chlich bei uns abgegeben wird.<\\/li>\\n <li>Bei Fundgegenst\\u00e4nden, die sich jemandem pers\\u00f6nlich zuordnen lassen (beispielsweise Ausweise, P\\u00e4sse, Handys mit SIM-Karten), werden die Besitzer*innen automatisch schriftlich von uns informiert.<\\/li>\\n <li>Handelt es sich um einen Gegenstand, der sich nicht einer bestimmten Person zuordnen l\\u00e4sst (beispielsweise Schirm, Kleidung, Brille), k\\u00f6nnen Sie mit Termin zur Besichtigung pers\\u00f6nlich bei uns vorbeikommen.<\\/li>\\n <li>Sie ben\\u00f6tigen auch einen Termin, wenn Sie einen verlorenen Wertgegenstand (beispielsweise Schmuck, Kamera, Uhr) besichtigen wollen.<\\/li>\\n <li><strong>Schl\\u00fcssel k\\u00f6nnen ohne Termin im Erdgeschoss, Implerstra\\u00dfe 11, besichtigt werden. Um den Schl\\u00fcssel mitzunehmen, m\\u00fcssen Sie einen Vergleichs- oder Zweitschl\\u00fcssel mitbringen. Schl\\u00fcssel k\\u00f6nnen nicht online gemeldet werden.<\\/strong><\\/li>\\n <li>Wegen Gegenst\\u00e4nden, die Sie in U-Bahnen, Bussen oder Stra\\u00dfenbahnen sowie an Haltestellen und Bahnsteigen verloren haben, wenden Sie sich bitte an das <a href=\\\"https:\\/\\/www.mvg.de\\/services\\/fundbuero.html\\\" target=\\\"\\\">Fundb\\u00fcro der M\\u00fcnchner Verkehrsgesellschaft (MVG)<\\/a> in der Elsenheimer Stra\\u00dfe 61, 1. Stock.<\\/li>\\n <li>Bei Gegenst\\u00e4nden, die Sie in S-Bahnen, Z\\u00fcgen und dem Bahnhofsbereich verloren haben, wenden Sie sich bitte an das <a href=\\\"https:\\/\\/www.s-bahn-muenchen.de\\/service\\/fundbuero\\\"><strong>DB Fundb\\u00fcro M\\u00fcnchen Hauptbahnhof<\\/strong><\\/a> der Deutschen Bundesbahn in der Schalterstelle des Hauptbahnhofes.<\\/li>\\n <li>F\\u00fcr die <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338649\\/\\\">Besichtigung von Fahrr\\u00e4dern<\\/a>, beachten Sie bitte entsprechende Hinweise.<\\/li>\\n <li>F\\u00fcr Schirme, Handschuhe, Brillen und \\u00e4hnliche Kleingegenst\\u00e4nde gibt es keine Online-Meldung. Um eine Verwechslung bei Massenfundsachen auszuschlie\\u00dfen, kommen Sie bitte pers\\u00f6nlich ins Fundb\\u00fcro.<\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Fundamt, Fundb\\u00fcro, Fundsache\",\"translated\":true,\"hash\":\"\",\"id\":\"10338650\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1061963\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338650\\/locations\\/1061963\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338650\\/locations\\/1061963\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Verlustanzeige\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustanzeige\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Verlorenes Fahrrad besichtigen und abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338649\\/\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Farrad als Finder*in abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10352189\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Verlustanzeige\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustanzeige\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Verlorenes Fahrrad besichtigen und abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338649\\/\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Farrad als Finder*in abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10352189\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[10338650],\"fees\":\"<p>Bei der Abholung f\\u00e4llt ein Kostenersatz an. Siehe \\u00dcbersicht \\u201eKostenersatz\\u201c bei <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundburo\\/10338652\\/?utm_source=chatgpt.com#k-links\\\" target=\\\"\\\">\\u201eLinks und Downloads\\u201c<\\/a> \\u200b<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10338853','Aufenthaltserlaubnis  – Working-Holiday- oder Youth-Mobility-Programm','https://service.berlin.de/dienstleistung/10338853/','Sonstiges','{\"id\":\"10338853\",\"name\":\"Aufenthaltserlaubnis  \\u2013 Working-Holiday- oder Youth-Mobility-Programm\",\"description\":\"<p><strong>Welche Art von Aufenthalt ist hier gemeint?<\\/strong> Um jungen Menschen von au\\u00dferhalb der Europ\\u00e4ischen Union die M\\u00f6glichkeit zu geben, Deutschland, seine Kultur, Bev\\u00f6lkerung und Geografie kennen zu lernen, gibt es die M\\u00f6glichkeit eines bis zu einj\\u00e4hrigen Aufenthalts zur kulturellen Bildung. Im Rahmen dieses Aufenthalts haben Sie auch die M\\u00f6glichkeit, Ihren Lebensunterhalt teilweise durch Erwerbst\\u00e4tigkeit zu finanzieren. <strong>Welche Personen d\\u00fcrfen teilnehmen?<\\/strong> Voraussetzung f\\u00fcr einen solchen Aufenthaltstitel ist ein Abkommen zwischen Ihrem Heimatland und der Bundesrepublik Deutschland. Aktuell bestehen solche Abkommen mit:<\\/p>\\n<ul>\\n <li>Argentinien<\\/li>\\n <li>Australien<\\/li>\\n <li>Brasilien<\\/li>\\n <li>Chile<\\/li>\\n <li>Hongkong<\\/li>\\n <li>Israel<\\/li>\\n <li>Japan<\\/li>\\n <li>Kanada<\\/li>\\n <li>Neuseeland<\\/li>\\n <li>Republik Korea (S\\u00fcdkorea)<\\/li>\\n <li>Taiwan<\\/li>\\n <li>Uruguay<\\/li>\\n<\\/ul>\\n<p>Die Abkommen k\\u00f6nnen dabei verschiedene Bezeichnungen verwenden (wie Work &amp; Travel, Working-Holiday oder Youth Mobility) und unterschiedliche Voraussetzungen und Beschr\\u00e4nkungen haben. Bitte informieren Sie sich vorab bei Ihrem Au\\u00dfenministerium oder der <a href=\\\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/ReiseUndSicherheit\\/deutsche-auslandsvertretungen\\\">deutschen Auslandsvertretung<\\/a> in Ihrem Heimatland \\u00fcber die f\\u00fcr Sie geltenden Voraussetzungen. <strong>Ben\\u00f6tigen Sie ein Visum zur Einreise?<\\/strong> Staatsangeh\\u00f6rige von Australien, Israel, Japan, Kanada und Neuseeland k\\u00f6nnen ohne Visum einreisen und innerhalb von 90 Tagen nach der Einreise die Aufenthaltserlaubnis in Deutschland bei der Ausl\\u00e4nderbeh\\u00f6rde beantragen. Sie k\\u00f6nnen aber auch bereits im Heimatland bei der deutschen Auslandsvertretung daf\\u00fcr ein Visum f\\u00fcr ein Jahr beantragen. Dann m\\u00fcssen Sie keine Aufenthaltserlaubnis bei uns beantragen. Die Staatsangeh\\u00f6rigen der anderen teilnehmenden L\\u00e4nder ben\\u00f6tigen zur Einreise ein Visum und m\\u00fcssen dieses bei der jeweils zust\\u00e4ndigen deutschen Auslandsvertretung beantragen.<\\/p>\\n<p>Zur Beantragung einer Aufenthaltserlaubnis reichen Sie das <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\">Antragsformular<\\/a> sowie die erforderlichen Unterlagen \\u00fcber unser <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\\\">Kontaktformular<\\/a> oder per Post ein.W\\u00e4hlen Sie hierzu beim Kontaktformular bitte Folgendes aus:<\\/p>\\n<ul>\\n <li>\\u201eIch habe eine Frage\\u201c,<\\/li>\\n <li>Kategorie \\u201eErteilung oder Verl\\u00e4ngerung eines Aufenthaltstitels\\u201c,<\\/li>\\n <li>Art des Aufenthalts: \\u201eAufenthalt zur Erwerbst\\u00e4tigkeit\\/ Arbeit\\u201c,<\\/li>\\n <li>Thema \\u201eIch bin keine Fachkraft\\u201c<\\/li>\\n <li>Betreff \\u201eBesch\\u00e4ftigung ohne Studium\\u201c<\\/li>\\n<\\/ul>\\n<p>Nach Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin zur pers\\u00f6nlichen Vorsprache.<\\/p>\\n<p><strong>G\\u00fcltigkeitsdauer<\\/strong><\\/p>\\n<p>Die Aufenthaltserlaubnis wird f\\u00fcr ein Jahr erteilt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10338853\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10446\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338853\\/locations\\/10446\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10338853\\/locations\\/10446\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"FAQ Ausl\\u00e4nderbeh\\u00f6rde M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/faq-auslaenderbehoerde.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"http:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung zum Visumantrag\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_Visumsantrag_Declaration_Visa.pdf\",\"description\":false},{\"name\":\"Ausw\\u00e4rtiges Amt - Working Holiday Programm\",\"link\":\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/fragenkatalog-node\\/06-workingholiday\\/606324\",\"description\":false},{\"name\":\"Work and Travel in Deutschland\",\"link\":\"https:\\/\\/www.deutschland.de\\/de\\/topic\\/leben\\/work-and-travel-in-deutschland\",\"description\":false}],\"forms\":[{\"name\":\"FAQ Ausl\\u00e4nderbeh\\u00f6rde M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/faq-auslaenderbehoerde.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"http:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Erkl\\u00e4rung zum Visumantrag\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Erklaerung_Visumsantrag_Declaration_Visa.pdf\",\"description\":false},{\"name\":\"Ausw\\u00e4rtiges Amt - Working Holiday Programm\",\"link\":\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/fragenkatalog-node\\/06-workingholiday\\/606324\",\"description\":false},{\"name\":\"Work and Travel in Deutschland\",\"link\":\"https:\\/\\/www.deutschland.de\\/de\\/topic\\/leben\\/work-and-travel-in-deutschland\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10338853],\"fees\":\"<p>100 Euro<br>Japanische Staatsangeh\\u00f6rige: Keine Geb\\u00fchr<br><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10339027','Notfall-Hilfe Aufenthaltstitel – Studierende, Arbeitsplatzsuche nach Studium oder erstmalige Beschäftigung nach Studium','https://service.berlin.de/dienstleistung/10339027/','Sonstiges','{\"id\":\"10339027\",\"name\":\"Notfall-Hilfe Aufenthaltstitel \\u2013 Studierende, Arbeitsplatzsuche nach Studium oder erstmalige Besch\\u00e4ftigung nach Studium\",\"description\":\"<p>Es werden nur nachgewiesene Notf\\u00e4lle bearbeitet.<\\/p>\\n<p><strong>Was ist ein Notfall?<\\/strong>\\n <br>\\n Ein Notfall ist eine unvorhersehbare Situation, in der sofort ein Dokument ben\\u00f6tigt wird, da ansonsten ein Schaden droht.<\\/p>\\n<p>Dies gilt in folgenden F\\u00e4llen:<\\/p>\\n<ul>\\n <li>Drohender Verlust des Arbeitsplatzes oder des Arbeitsplatzangebots<\\/li>\\n <li>Drohender Verlust von Leistungen (beispielsweise Studienkredit)<\\/li>\\n <li>Dringende Reise aus pers\\u00f6nlichen oder beruflichen Gr\\u00fcnden innerhalb der n\\u00e4chsten sieben Tage (etwa Dienstreise, Krankheit, Tod)<\\/li>\\n<\\/ul>\\n<p>Die Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung pr\\u00fcft und entscheidet, ob ein Notfall vorliegt.<\\/p>\\n<p><strong>Bitte kommen Sie nicht ohne <a href=\\\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/terminvereinbarung.html#\\/services\\/10339027\\/locations\\/10187259\\\" target=\\\"_blank\\\">Termin<\\/a> !<\\/strong> Vor Ort gibt es keine Terminvergabe oder Wartenummern.Notfalltermine gibt es nur kurzfristig f\\u00fcr den jeweiligen Tag. Die Termine werden t\\u00e4glich am Montag, Mittwoch und Freitag um 6.30 Uhr sowie am Dienstag und Donnerstag um 7.30 Uhr freigeschaltet. Wenn Sie online keinen Termin bekommen, rufen Sie bitte unser <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/auslaenderbehoerde\\/10338844\\/#k-contact\\\">Servicetelefon<\\/a> an, um einen Termin zu vereinbaren.<\\/p>\\n<p>\\u200b<\\/p>\\n<p><strong>Achtung vor kostenpflichtigen Angeboten:<\\/strong> Wir warnen Sie ausdr\\u00fccklich vor kostenpflichtigen Terminangeboten von anderen Anbieter*innen. Die Terminvereinbarung ist bei der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung immer kostenlos. Nutzen Sie bitte ausschlie\\u00dflich diese Website, um sicherzustellen, dass Sie den Service kostenfrei und zuverl\\u00e4ssig erhalten. Bitte teilen Sie uns mit, falls Sie auf einen kostenpflichtigen Termin sto\\u00dfen.<\\/p>\\n<p><strong>Asylverfahren<\\/strong><\\/p>\\n<p>Sie sind in einem laufenden oder abgeschlossenen Asylverfahren, asylberechtigt, Fl\\u00fcchtling oder subsidi\\u00e4r schutzberechtigt?<\\/p>\\n<p>Dann k\\u00f6nnen Sie in Notf\\u00e4llen <strong>ohne Termin<\\/strong> zum Servicepoint in der Ruppertstra\\u00dfe 19 (Eingang A) im Bereich 21 im 2. Stock kommen:<\\/p>\\n<p>Montag: 7.30 - 12 Uhr<\\/p>\\n<p>Dienstag: 8.30 - 12 Uhr und 14 -18 Uhr<\\/p>\\n<p>Donnerstag: 8.30 - 15 Uhr<\\/p>\\n<p>Freitag: 7.30 - 12 Uhr<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"abgelaufener Aufenthaltstitel, abgelaufene Aufenthaltserlaubnis, kein Aufenthalt, keine Aufenthaltserlaubnis mehr, abgelaufen, ung\\u00fcltig, ung\\u00fcltiger Aufenthaltstitel, ung\\u00fcltige Aufenthaltserlaubnis, dringende Reise\",\"translated\":true,\"hash\":\"\",\"id\":\"10339027\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10187259\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10339027\\/locations\\/10187259\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10339027\\/locations\\/10187259\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Kontaktformular Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"H\\u00e4ufige Fragen und Antworten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/sze-faq.html\",\"description\":false}],\"forms\":[{\"name\":\"Kontaktformular Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"H\\u00e4ufige Fragen und Antworten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/sze-faq.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[10339027]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10339028','Notfall-Hilfe Aufenthaltstitel – Beschäftigte, Angehörige','https://service.berlin.de/dienstleistung/10339028/','Sonstiges','{\"id\":\"10339028\",\"name\":\"Notfall-Hilfe Aufenthaltstitel \\u2013 Besch\\u00e4ftigte, Angeh\\u00f6rige\",\"description\":\"<p>Es werden nur nachgewiesene Notf\\u00e4lle bearbeitet.<\\/p>\\n<p><strong>Was ist ein Notfall?<\\/strong>\\n <br>\\n Ein Notfall ist eine unvorhersehbare Situation, in der sofort ein Dokument ben\\u00f6tigt wird, da ansonsten ein Schaden droht.\\n <br>\\n Dies gilt in folgenden F\\u00e4llen:<\\/p>\\n<ul>\\n <li>Drohender Verlust des Arbeitsplatzes<\\/li>\\n <li>Drohender Verlust von Leistungen (beispielsweise Arbeitslosengeld)<\\/li>\\n <li>Dringende Reise aus pers\\u00f6nlichen oder beruflichen Gr\\u00fcnden innerhalb der n\\u00e4chsten sieben Tage (etwa Dienstreise, Krankheit, Tod)<\\/li>\\n<\\/ul>\\n<p>Die Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung pr\\u00fcft und entscheidet, ob ein Notfall vorliegt.<\\/p>\\n<p><strong>Bitte kommen Sie nicht ohne <a href=\\\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/terminvereinbarung.html#\\/services\\/10339028\\/locations\\/10461\\\" target=\\\"_blank\\\">Termin<\\/a> !<\\/strong> Vor Ort gibt es keine Terminvergabe oder Wartenummern. Neue Termine werden Montag bis Freitag morgens und mittags jeweils 10 Minuten vor Beginn der \\u00d6ffnungszeiten freigeschaltet. Termine f\\u00fcr die n\\u00e4chste Woche erscheinen \\u00fcber die Woche verteilt im Buchungssystem. Wenn Sie online keinen Termin bekommen, rufen Sie bitte unser <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/auslaenderbehoerde\\/10338844\\/#k-contact\\\" target=\\\"_blank\\\">Servicetelefon<\\/a> an, um einen Termin zu vereinbaren.<\\/p>\\n<p><strong>Asylverfahren<\\/strong><\\/p>\\n<p>Sie sind in einem laufenden oder abgeschlossenen Asylverfahren, asylberechtigt, Fl\\u00fcchtling oder subsidi\\u00e4r schutzberechtigt?<\\/p>\\n<p>Dann k\\u00f6nnen Sie in Notf\\u00e4llen <strong>ohne Termin<\\/strong> zum Servicepoint in der Ruppertstra\\u00dfe 19 (Eingang A) im Bereich 21 im 2. Stock kommen:<\\/p>\\n<p>Montag 7.30 \\u2013 12 Uhr\\n <br>\\n Dienstag 8.30 \\u2013 12 Uhr und 14 \\u2013 18 Uhr\\n <br>\\n Donnerstag 8.30 \\u2013 15 Uhr\\n <br>\\n Freitag 7.30 \\u2013 12 Uhr<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"abgelaufener Aufenthaltstitel, abgelaufene Aufenthaltserlaubnis, kein Aufenthalt, keine Aufenthaltserlaubnis mehr, abgelaufen, ung\\u00fcltig, ung\\u00fcltiger Aufenthaltstitel, ung\\u00fcltige Aufenthaltserlaubnis, dringende Reise\",\"translated\":true,\"hash\":\"\",\"id\":\"10339028\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10461\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10339028\\/locations\\/10461\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10339028\\/locations\\/10461\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Kontaktformular Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"H\\u00e4ufige Fragen und Antworten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/sze-faq.html\",\"description\":false}],\"forms\":[{\"name\":\"Kontaktformular Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"H\\u00e4ufige Fragen und Antworten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/sze-faq.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[10339028]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10350358','Aufenthaltserlaubnis – Jugendliche und junge Volljährige','https://service.berlin.de/dienstleistung/10350358/','Sonstiges','{\"id\":\"10350358\",\"name\":\"Aufenthaltserlaubnis \\u2013 Jugendliche und junge Vollj\\u00e4hrige\",\"description\":\"<p>Am 31. Dezember 2022 ist das sogenannte Chancen-Aufenthaltsrecht in Kraft getreten. Geduldete Personen k\\u00f6nnen unter vereinfachten Voraussetzungen eine Aufenthaltserlaubnis nach erhalten.<\\/p>\\n<p>Die Aufenthaltserlaubnis wird f\\u00fcr maximal drei Jahre erteilt und verl\\u00e4ngert. Bevor Ihre Duldung oder Ihr Aufenthaltstitel abl\\u00e4uft, m\\u00fcssen Sie die Aufenthaltserlaubnis beantragen.<\\/p>\\n<p>Ehepartner*innen, Lebenspartner*innen und den minderj\\u00e4hrigen ledigen Kindern soll eine Aufenthaltserlaubnis auch bei k\\u00fcrzerer Aufenthaltsdauer erteilt werden, soweit eine famili\\u00e4re Lebensgemeinschaft besteht und die Erteilungsvoraussetzungen erf\\u00fcllt werden.<\\/p>\\n<p>F\\u00fcr die Beantragung senden Sie uns bitte Ihr Antragsformular sowie die ben\\u00f6tigten Unterlagen online oder per Post zu. Nach der Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Humanit\\u00e4rer Aufenthalt, Duldung, Asylbewerber*in, Jugendliche\",\"translated\":true,\"hash\":\"\",\"id\":\"10350358\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350358\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350358\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350358\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350358\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei-gmbh.de\\/files\\/dokumente\\/pdf\\/fotomustertafel.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:c38c3e57-d9ed-4917-b2b5-229f7f008e4c\\/Antrag_auf_Aufenthaltstitel_Juli_2021.pdf\",\"description\":false},{\"name\":\"Information zum Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Startseite\\/startseite_node.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Wohnsitz anmelden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei-gmbh.de\\/files\\/dokumente\\/pdf\\/fotomustertafel.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:c38c3e57-d9ed-4917-b2b5-229f7f008e4c\\/Antrag_auf_Aufenthaltstitel_Juli_2021.pdf\",\"description\":false},{\"name\":\"Information zum Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Startseite\\/startseite_node.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10350358],\"fees\":\"<ul><li>Ersterteilung: 100 Euro<\\/li><li>Verl\\u00e4ngerung: 93 Euro<\\/li><li>Ersterteilung Kind: 50 Euro<\\/li><li>Verl\\u00e4ngerung Kind: 46,50 Euro<br><\\/li><\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10350361','Aufenthaltserlaubnis – Nachhaltige Integration','https://service.berlin.de/dienstleistung/10350361/','Sonstiges','{\"id\":\"10350361\",\"name\":\"Aufenthaltserlaubnis \\u2013 Nachhaltige Integration\",\"description\":\"<p>Am 31. Dezember 2022 ist das sogenannte Chancen-Aufenthaltsrecht in Kraft getreten. Geduldete Personen k\\u00f6nnen unter vereinfachten Voraussetzungen eine Aufenthaltserlaubnis nach \\u00a7 25b AufenthG erhalten.<\\/p><p>Bevor Ihre Duldung oder Ihr Aufenthaltstitel abl\\u00e4uft, m\\u00fcssen Sie die Aufenthaltserlaubnis beantragen. <br><\\/p><p>F\\u00fcr die Beantragung senden Sie uns bitte Ihr Antragsformular sowie die ben\\u00f6tigten Unterlagen online oder per Post zu. Nach der Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin.<\\/p><ul><li>Ehepartner*innen, Lebenspartner*innen und den minderj\\u00e4hrigen, ledigen Kindern k\\u00f6nnen eine Aufenthaltserlaubnis auch bei k\\u00fcrzerer Aufenthaltsdauer erhalten, soweit eine famili\\u00e4re Lebensgemeinschaft besteht und die Erteilungsvoraussetzungen erf\\u00fcllt werden.<\\/li><li>Personen, mit Besch\\u00e4ftigungsduldung nach \\u00a7 60d AufenthG k\\u00f6nnen bereits nach 30 Monaten geduldeten Aufenthalts eine Aufenthaltserlaubnis beantragen.<\\/li><li>Die Aufenthaltserlaubnis wird f\\u00fcr maximal zwei Jahre erteilt und verl\\u00e4ngert.<br><br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Fl\\u00fcchtlingIntegration, Duldung, Humanit\\u00e4rer Aufenthalt, Bleiberecht, Asylbewerber*in, Jugendliche\",\"translated\":true,\"hash\":\"\",\"id\":\"10350361\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350361\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350361\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350361\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10350361\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei-gmbh.de\\/files\\/dokumente\\/pdf\\/fotomustertafel.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:c38c3e57-d9ed-4917-b2b5-229f7f008e4c\\/Antrag_auf_Aufenthaltstitel_Juli_2021.pdf\",\"description\":false},{\"name\":\"Information zum Bundesamt f\\u00fcr Migration und Fl\\u00fcchtlinge\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Startseite\\/startseite_node.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\