INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10352187','Fahrrad als Finder*in abholen','https://service.berlin.de/dienstleistung/10352187/','Sonstiges','{\"id\":\"10352187\",\"name\":\"Fahrrad als Finder*in abholen\",\"description\":\"<p>Fundsachen werden sechs Monate vom Fundb\\u00fcro aufbewahrt. Wenn die Fundsache bis zum Ablauf dieser Aufbewahrungsfrist nicht abgeholt wurde, erwerben Sie als Finder*in das Eigentum an der Sache. In diesem Fall werden Sie von uns benachrichtigt.<\\/p>\\n<p>F\\u00fcr die Abholung von Fahrr\\u00e4dern m\\u00fcssen Sie online einen Termin vereinbaren. Die Abholung erfolgt nur Dienstags in der Ruppertstra\\u00dfe 19, Eingang A, Raum U101.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10352187\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10352393\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10352187\\/locations\\/10352393\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10352187\\/locations\\/10352393\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlorenes Fahrrad besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338649\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fundsache abholen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/1063521\\/\",\"description\":false},{\"name\":\"Fundsache abgeben\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fundsache-abgeben\\/1063522\\/n0\\/\",\"description\":false},{\"name\":\"Verlorenes Fahrrad besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338649\\/\",\"description\":false},{\"name\":\"Verlust melden - Fundsachen besichtigen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-iii\\/10338652\\/\",\"description\":false},{\"name\":\"Kostenersatz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Fundbuero\\/Dokumente\\/Kostenersatz-Fundsachen.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,