INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10371948','Reiseausweis für Staatenlose','https://service.berlin.de/dienstleistung/10371948/','Sonstiges','{\"id\":\"10371948\",\"name\":\"Reiseausweis f\\u00fcr Staatenlose\",\"description\":\"<p>Grunds\\u00e4tzlich m\\u00fcssen ausl\\u00e4ndische Personen einen g\\u00fcltigen Nationalpass vorlegen. Ob eine Person staatenlos ist, muss im Einzelfall von der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung gepr\\u00fcft werden. Der Reiseausweis kann nur f\\u00fcr die Dauer ausgestellt werden, f\\u00fcr die der Aufenthaltstitel g\\u00fcltig ist. Der Reiseausweis ist maximal drei Jahre g\\u00fcltig.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Staatenlos, Reisepass, Pal\\u00e4stinenser, Passersatzpaper\",\"translated\":true,\"hash\":\"\",\"id\":\"10371948\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10371948\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10371948\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\