INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10387810','Widerspruch gegen die Rente','https://service.berlin.de/dienstleistung/10387810/','Sonstiges','{\"id\":\"10387810\",\"name\":\"Widerspruch gegen die Rente\",\"description\":\"<p>Wir beantworten gerne Ihre Fragen<\\/p><ul><li>zum Rentenbescheid, einschlie\\u00dflich dessen \\u00dcberpr\\u00fcfung<\\/li><li>zu m\\u00f6glichen Rechtsmitteln gegen Bescheide von Rentenversicherungstr\\u00e4gern<\\/li><li>zur Zul\\u00e4ssigkeit und Begr\\u00fcndetheit von Widerspr\\u00fcchen gegen Rentenbescheide, einschlie\\u00dflich der Widerspruchsaufnahme<\\/li><li>zur Beantragung von Akteneinsicht<\\/li><\\/ul><p>Gerne pr\\u00fcfen wir vorab den Bescheid, gegen den Sie Widerspruch einlegen m\\u00f6chten. <br><br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Rente, Widerspruch\",\"translated\":true,\"hash\":\"\",\"id\":\"10387810\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10512\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10387810\\/locations\\/10512\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10387810\\/locations\\/10512\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"de