INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10387813','Widerspruch gegen die Kranken-, Pflege- oder Unfallversicherung','https://service.berlin.de/dienstleistung/10387813/','Sonstiges','{\"id\":\"10387813\",\"name\":\"Widerspruch gegen die Kranken-, Pflege- oder Unfallversicherung\",\"description\":\"<p>Wir beantworten gerne Ihre Fragen<\\/p><ul><li>zum erlassenen Bescheid des jeweiligen Versicherungstr\\u00e4gers, einschlie\\u00dflich dessen \\u00dcberpr\\u00fcfung<\\/li><li>zu weiteren m\\u00f6glichen Rechtsmitteln gegen Bescheide Ihrer Kranken- und Pflegeversicherung, gesetzlichen Unfallversicherung und zum Schwerbehindertenrecht<\\/li><li>zur Zul\\u00e4ssigkeit und Begr\\u00fcndetheit von Widerspr\\u00fcchen, einschlie\\u00dflich der Widerspruchsaufnahme<\\/li><li>zur Beantragung von Akteneinsicht<\\/li><\\/ul><p>Gerne pr\\u00fcfen wir vorab den Bescheid, gegen den Sie Widerspruch einlegen m\\u00f6chten. <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Krankenversicherung, Widerspruch, Schwerbehindertenrecht, Unfallversicherung, Pflegeversicherung\",\"translated\":true,\"hash\":\"\",\"id\":\"10387813\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10512\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10387813\\/locations\\/10512\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10387813\\/locations\\/10512\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsi