INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10389330','Führungen auf den Feuerwachen','https://service.berlin.de/dienstleistung/10389330/','Sonstiges','{\"id\":\"10389330\",\"name\":\"F\\u00fchrungen auf den Feuerwachen\",\"description\":\"<p>F\\u00fchrungen f\\u00fcr Kinder k\\u00f6nnen nur f\\u00fcr M\\u00fcnchner Grundschulklassen in Verbindung mit der Unterrichtseinheit \\u201eBrandschutzerziehung\\u201c durchgef\\u00fchrt werden. Pro Termin kann eine Klasse zu Besuch kommen. W\\u00e4hrend der F\\u00fchrung gibt es auf der Wache keine M\\u00f6glichkeit zum Verzehr von Speisen und Getr\\u00e4nken.<\\/p>\\n<p>Lehrkr\\u00e4ften steht im unteren Bereich eine entsprechende Tabelle zur Verf\\u00fcgung, um die zust\\u00e4ndige Feuerwache zu finden. Bitte buchen Sie eine Wachf\\u00fchrung ausschlie\\u00dflich dort.<\\/p>\\n<p>\\u200bF\\u00fcr alle anderen Gruppen bieten wir F\\u00fchrungen f\\u00fcr Gruppengr\\u00f6\\u00dfen von 15 bis 50 Personen an.\\n <br><\\/p>\\n<p>\\u200bF\\u00fcr Einzelpersonen oder Kleingruppen (weniger als 15 Personen) bieten wir auf verschiedenen, zentral gelegenen Feuerwachen im monatlichen Wechsel F\\u00fchrungen an.<\\/p>\\n<p>Entsprechende Termine, mit der M\\u00f6glichkeit zum Anmelden, finden Sie im unteren Bereich \\u201eEinzelpersonen oder Kleingruppen\\u201c.<\\/p>\\n<p>Die F\\u00fchrungen beginnen auf den Feuerwachen 1 bis 3 und 5 bis 10 montags bis donnerstags um 9.30 Uhr, freitags und samstags um 13.30 Uhr.<\\/p>\\n<p>Auf der Feuerwache 4 beginnen die F\\u00fchrungen montags bis donnerstags um 10 Uhr, freitags und samstags um 14 Uhr.<\\/p>\\n<p>Die F\\u00fchrung ist kostenlos und dauert etwa 90 Minuten.<\\/p>\\n<p>Foto- und Videoaufnahmen innerhalb des Wachgeb\\u00e4udes sind untersagt.\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10389330\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10577\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10577\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10577\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10579\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10579\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10579\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10585\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10585\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10389330\\/locations\\/10585\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10580\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtver