INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10392403','Parkausweis für Beschicker*innen','https://service.berlin.de/dienstleistung/10392403/','Sonstiges','{\"id\":\"10392403\",\"name\":\"Parkausweis f\\u00fcr Beschicker*innen\",\"description\":\"<p>Sie haben eine Zulassung, um als Beschicker*in einen Marktstand auf der Auer Dult er\\u00f6ffnen zu d\\u00fcrfen. Um diesen Marktstand zu beliefern, m\\u00fcssen Sie mit Ihrem Privatfahrzeug im Bereich der Auer Dult parken. Der Bereich der Auer Dult befindet sich in einem bewirtschafteten Bereich f\\u00fcr Bewohner*innen. Zum Dauerparken ben\\u00f6tigen Sie daher einen Parkausweis.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Parkausweis, Auer Dult, Beschicker, Kirchweihdult, Mariahilfplatz, Beschickerin, Maidult, Jakobidult\",\"translated\":true,\"hash\":\"\",\"id\":\"10392403\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10392403\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10392403\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10392403],\"fees\":\"<p>G\\u00fcltigkeit f\\u00fcr das aktuelle Kalenderjahr: 30 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10392406','Kurzzeitkennzeichen mit ausländischen Fahrzeugdokumenten','https://service.berlin.de/dienstleistung/10392406/','Sonstiges','{\"id\":\"10392406\",\"name\":\"Kurzzeitkennzeichen mit ausl\\u00e4ndischen Fahrzeugdokumenten\",\"description\":\"<p>In M\\u00fcnchen erhalten Sie ein Kurzzeitkennzeichen ausschlie\\u00dflich in der Zulassungsbeh\\u00f6rde in der Eichst\\u00e4tter Stra\\u00dfe.<\\/p>\\n<p>Fahrzeuge ohne g\\u00fcltige Hauptuntersuchung oder Sicherheitspr\\u00fcfung d\\u00fcrfen nur zu einer Untersuchungsstelle im Bezirk der Zulassungsbeh\\u00f6rde gefahren werden, die f\\u00fcr den Standort des Fahrzeugs zust\\u00e4ndig ist oder in einem angrenzenden Bezirk.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10392406\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308017\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10392406\\/locations\\/10308017\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10392406\\/locations\\/10308017\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[10392406,1064076,10391604],\"fees\":\"<p>ab 13,10 Euro zuz\\u00fcglich Kennzeichenschilder<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10396802','Anmeldung einer Eheschließung mit Auslandsbezug','https://service.berlin.de/dienstleistung/10396802/','Sonstiges','{\"id\":\"10396802\",\"name\":\"Anmeldung einer Eheschlie\\u00dfung mit Auslandsbezug\",\"description\":\"<p>Nach deutschen Rechtsverst\\u00e4ndnis ist die Ehe eine dauerhafte Lebensgemeinschaft von zwei Personen. Der Entschluss, durch eine Heirat sein Leben mit einem anderen Menschen zu verbinden, beruht auf der freien Entscheidung jedes*r Einzelnen. Beide k\\u00fcnftigen Eheleute m\\u00fcssen vollj\\u00e4hrig und gesch\\u00e4ftsf\\u00e4hig sein. Sie d\\u00fcrfen nicht zu nah verwandt sein oder in einer bestehenden Ehe oder eingetragenen Lebenspartnerschaft leben.<br><br>\\n Wenn keine*r von Ihnen einen sogenannten Auslandsbezug hat, beachten Sie bitte die Informationen auf der Seite \\u201e <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/anmeldung-einer-eheschliessung\\/1063648\\/\\\" target=\\\"\\\">Anmeldung einer Eheschlie\\u00dfung<\\/a> \\u201c.<br><br>\\n \\u201eAuslandsbezug\\u201c bedeutet, dass eine*r oder beide von Ihnen eine ausl\\u00e4ndische Staatsangeh\\u00f6rigkeit hat, im Ausland geboren wurde, eine fr\\u00fchere Ehe\\/Lebenspartnerschaft im Ausland geschlossen hat oder dort geschieden wurde. In diesem Fall m\\u00fcssen zus\\u00e4tzlich Vorschriften des anderen Staates beachtet werden und es wird auch ber\\u00fccksichtigt, welche Dokumente aus dem jeweiligen Land beschafft werden k\\u00f6nnen. Bei jedem Paar ist das deshalb unterschiedlich.<\\/p>\\n<p>Bitte buchen Sie einen Termin, dieser kann bis zu 3 Monate im voraus gebucht werden. Sie m\\u00fcssen gemeinsam mit allen notwendigen Unterlagen beim zust\\u00e4ndigen Standesamt vorsprechen. Sie k\\u00f6nnen nicht gut Deutsch, dann bringen Sie eine*n \\u00f6ffentliche bestellte und vereidigte \\u00dcbersetzer*in mit.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufgebot bestellen, Ich will heiraten, Ehe\\/Eheschlie\\u00dfung\\/ Heirat\\/ Hochzeit anmelden, Ehe\\/Eheschlie\\u00dfung\\/ Heirat\\/ Hochzeit beantragen, Ausl\\u00e4nder*in heiraten, Heirat mit Ausl\\u00e4nder*in\",\"translated\":true,\"hash\":\"\",\"id\":\"10396802\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10470\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10396802\\/locations\\/10470\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10396802\\/locations\\/10470\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10351880\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10396802\\/locations\\/10351880\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10396802\\/locations\\/10351880\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Allgemeine Informationen und Termine\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/heirat-standesamt.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bevollm\\u00e4chtigung zur Anmeldung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/beitritt.pdf\",\"description\":false},{\"name\":\"Bayerisches Staatsministerium f\\u00fcr Familie, Arbeit und Soziales\",\"link\":\"https:\\/\\/www.stmas.bayern.de\\/familie.php\",\"description\":false}],\"forms\":[{\"name\":\"Allgemeine Informationen und Termine\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/heirat-standesamt.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Bevollm\\u00e4chtigung zur Anmeldung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/beitritt.pdf\",\"description\":false},{\"name\":\"Bayerisches Staatsministerium f\\u00fcr Familie, Arbeit und Soziales\",\"link\":\"https:\\/\\/www.stmas.bayern.de\\/familie.php\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":false,\"duration\":60,\"combinable\":[10396802]}',NULL,NULL);
