INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10416410','Anpassung des Geschlechtseintrags und Vornamens (Selbstbestimmungsgesetz)','https://service.berlin.de/dienstleistung/10416410/','Sonstiges','{\"id\":\"10416410\",\"name\":\"Anpassung des Geschlechtseintrags und Vornamens (Selbstbestimmungsgesetz)\",\"description\":\"<p>Das Selbstbestimmungsgesetz erm\\u00f6glicht es ab November 2024, den Eintrag des eigenen Geschlechts und die dazu passenden Vornamen selbst zu bestimmen.<\\/p>\\n<p>Sie m\\u00fcssen Ihre Absicht zun\\u00e4chst schriftlich oder m\\u00fcndlich bei einem deutschen Standesamt anmelden. Wir empfehlen Ihnen, sich an das Standesamt Ihres Wohnsitzes zu wenden.<\\/p>\\n<p>F\\u00fcr die <strong>schriftliche<\\/strong> Anmeldung bei einem der M\\u00fcnchner Standes\\u00e4mter k\\u00f6nnen Sie unsere Formulare verwenden und per Post einreichen. Eine Anmeldung per E-Mail ist nicht m\\u00f6glich.<\\/p>\\n<p>F\\u00fcr die <strong>m\\u00fcndliche<\\/strong> Anmeldung k\\u00f6nnen Sie online einen Vorsprachetermin buchen.<\\/p>\\n<p>Nach der Anmeldung vereinbart das Standesamt mit Ihnen einen Termin f\\u00fcr die Beurkundung Ihrer Erkl\\u00e4rung zur Angabe des Geschlechts und zum Vornamen. Dazu m\\u00fcssen Sie pers\\u00f6nlich beim Standesamt erscheinen. Anmeldung und Erkl\\u00e4rung m\\u00fcssen beim selben Standesamt abgegeben werden.<br>\\n Die Erkl\\u00e4rung wird mit Entgegennahme durch das zust\\u00e4ndige Standesamt wirksam. Zust\\u00e4ndig ist<\\/p>\\n<ol>\\n <li>wenn Ihre Geburt in einem deutschen Geburtenregister beurkundet ist, das Standesamt, das Ihr Geburtenregister f\\u00fchrt<\\/li>\\n <li>wenn 1. nicht zutrifft, das Standesamt, das Ihr Ehe- oder Lebenspartnerschaftsregister f\\u00fchrt<\\/li>\\n <li>wenn auch 2. nicht zutrifft, das Standesamt, in dessen Amtsbezirk Sie wohnen<\\/li>\\n <li>wenn Sie im Ausland wohnen, das Standesamt, in dessen Amtsbezirk Sie zuletzt gewohnt haben<\\/li>\\n <li>wenn nichts davon zutrifft, das Standesamt I in Berlin.<\\/li>\\n<\\/ol>\\n<p>Nachdem die Erkl\\u00e4rung wirksam entgegengenommen wurde, stellt Ihnen das zust\\u00e4ndige Standesamt auf Antrag eine Bescheinigung \\u00fcber die \\u00c4nderung, und\\/oder eine neue Personenstandsurkunde aus. Es informiert auch die Melde-beh\\u00f6rde.<\\/p>\\n<p>Das Selbstbestimmungsgesetz (SBGG) ersetzt ab dem <strong>1. November 2024<\\/strong> das Transsexuellengesetz sowie die Erkl\\u00e4rungsm\\u00f6glichkeit f\\u00fcr Personen mit Varianten der Geschlechtsentwicklung.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10416410\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10351883\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10416410\\/locations\\/10351883\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10416410\\/locations\\/10351883\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102365\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10416410\\/locations\\/102365\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10416410\\/locations\\/102365\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Informationen zur Erkl\\u00e4rung nach dem Selbstbestimmungsgesetz\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/Selbstbestimmungsgesetz\\/24_07_SBGG_DL_PDF_Informationen.pdf\",\"description\":false},{\"name\":\"Anmeldung f\\u00fcr Vollj\\u00e4hrige\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/Selbstbestimmungsgesetz\\/24_07_DL_SBGG_PDF_Anmeldung_Vollj_Tabellenform_v1.pdf\",\"description\":false},{\"name\":\"Anmeldung f\\u00fcr Minderj\\u00e4hrige ab 14 Jahren\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/Selbstbestimmungsgesetz\\/24_07_DL_SBGG_Anmeldung_Minderj_ab_14_Tabellenform_v1.pdf\",\"description\":false},{\"name\":\"Anmeldung f\\u00fcr Minderj\\u00e4hrige bis 13 Jahre\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/Selbstbestimmungsgesetz\\/24_07_DL_SBGG_PDF_Anmeldung_Minderj_bis_13_Tabellenform_v1.pdf\",\"description\":false},{\"name\":\"Anmeldung f\\u00fcr vollj\\u00e4hrige gesch\\u00e4ftsunf\\u00e4hige Betreute\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Standesamt\\/Dokumente\\/Selbstbestimmungsgesetz\\/24_07_DL_SBGG_PDF_Anmeldung_vollj_Betreute_Tabellenform_v1.pdf\",\"description\":false},{\"name\":\"Erg\\u00e4nzende Informationen f\\u00fcr Minderj\\u00e4hrige\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fac