INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10431909','SB Sorgerechtsaufkleber','https://service.berlin.de/dienstleistung/10431909/','Sonstiges','{\"id\":\"10431909\",\"name\":\"SB Sorgerechtsaufkleber\",\"description\":\"<p>\\u200b<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10431909\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10431909\\/locations\\/10497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10431909\\/locations\\/10497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[10431909]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10432110','Aufenthaltserlaubnis – Humanitärer Aufenthalt ohne Schutzstatus','https://service.berlin.de/dienstleistung/10432110/','Sonstiges','{\"id\":\"10432110\",\"name\":\"Aufenthaltserlaubnis \\u2013 Humanit\\u00e4rer Aufenthalt ohne Schutzstatus\",\"description\":\"<p>In Deutschland geduldeten Personen kann aus humanit\\u00e4ren Gr\\u00fcnden eine Aufenthaltserlaubnis nach Bleiberechts- und Altfallregelungen erteilt werden.<br>\\n Dar\\u00fcber hinaus kann die Bayerische Staatskanzlei aus v\\u00f6lkerrechtlichen oder humanit\\u00e4ren Gr\\u00fcnden oder zur Wahrung politischer Interessen der Bundesrepublik Deutschland anordnen, dass Ausl\\u00e4nder*innen aus bestimmten Staaten oder bestimmten Ausl\\u00e4ndergruppen eine Aufenthaltserlaubnis erteilt wird.<br><br>\\n In Bayern gibt es seit 2006 eine H\\u00e4rtefallkommission. Die H\\u00e4rtefallkommission erm\\u00f6glicht es, ausnahmsweise eine Aufenthaltserlaubnis an Ausl\\u00e4nder*innen zu erteilen, die eigentlich zur Ausreise verpflichtet sind. Dazu m\\u00fcssen dringende pers\\u00f6nliche oder humanit\\u00e4re Gr\\u00fcnde vorliegen, die den weiteren Aufenthalt in Deutschland rechtfertigen. So kann bei besonderen Einzelschicksalen und in humanit\\u00e4ren Ausnahmef\\u00e4llen geholfen werden, f\\u00fcr die das Aufenthaltsgesetz sonst keine angemessene L\\u00f6sung bereith\\u00e4lt. Die Voraussetzungen sind in der Regel ein langj\\u00e4hriger Aufenthalt, gute Integration und die eigenst\\u00e4ndige Sicherung des Lebensunterhalts.<br>\\n Hat die H\\u00e4rtefallkommission ein H\\u00e4rtefallersuchen gestellt, liegt die Entscheidung, ob dem Ersuchen stattgegeben werden kann, beim Staatsministerium des Innern, f\\u00fcr Sport und Integration.<br><br>\\n Bei Vorliegen sonstiger Ausreisehindernisse kann eine Aufenthaltserlaubnis erteilt werden. Voraussetzung ist, dass die Ausreise aus rechtlichen oder tats\\u00e4chlichen Gr\\u00fcnden unm\\u00f6glich ist. Mit dem Wegfall des Ausreisehindernisses darf in absehbarer Zeit nicht zu rechnen sein. Die Aufenthaltserlaubnis darf grunds\\u00e4tzlich nicht erteilt werden, wenn der\\/ die Ausl\\u00e4nder*in das Ausreisehindernis selbst herbeigef\\u00fchrt hat und es beseitigen k\\u00f6nnte. Die Aufenthaltserlaubnis wird in den ersten 18 Monaten f\\u00fcr jeweils l\\u00e4ngstens sechs Monate erteilt. Danach kann die Aufenthaltserlaubnis mit einer G\\u00fcltigkeit von bis zu drei Jahren erteilt werden.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Duldung, Bleiberecht, Altfall, H\\u00e4rtefall, Ausreisehindernis\",\"translated\":true,\"hash\":\"\",\"id\":\"10432110\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059485\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1059485\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432110\\/locations\\/1059485\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"H\\u00e4rtefallkommission\",\"link\":\"https:\\/\\/www.stmi.bayern.de\\/mui\\/aufenthaltsrecht\\/haertefallkommission\\/index.php\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltserlaubnis\",\"link\":\"https:\\/\\/www.muenchen.de\\/rathaus\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"H\\u00e4rtefallkommission\",\"link\":\"https:\\/\\/www.stmi.bayern.de\\/mui\\/aufenthaltsrecht\\/haertefallkommission\\/index.php\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10432110],\"fees\":\"<p>Ersterteilung: 100 Euro<br>\\n Verl\\u00e4ngerung: 93 Euro<br>\\n Ersterteilung Kind: 50 Euro<br>\\n Verl\\u00e4ngerung Kind: 46,50 Euro<br>\\n Abh\\u00e4ngig von der angeordneten Geltungsdauer der Aufenthaltserlaubnis.<br>\\n F\\u00fcr Personen, die f\\u00fcr ihren Lebensunterhalt auf Sozialleistungen angewiesen sind, ist die Beantragung kostenfrei.<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10432431','Arbeitserlaubnis – Änderung der Nebenbestimmungen','https://service.berlin.de/dienstleistung/10432431/','Sonstiges','{\"id\":\"10432431\",\"name\":\"Arbeitserlaubnis \\u2013 \\u00c4nderung der Nebenbestimmungen\",\"description\":\"<p>Nebenbestimmungen sind zus\\u00e4tzliche Bedingungen, die an den Aufenthaltstitel gekn\\u00fcpft werden k\\u00f6nnen. Sie regeln zum Beispiel die Arbeitserlaubnis. Die Entscheidung \\u00fcber die Nebenbestimmungen trifft die zust\\u00e4ndige Ausl\\u00e4nderbeh\\u00f6rde.<\\/p>\\n<p>Wenn Sie diese \\u00e4ndern m\\u00f6chten, k\\u00f6nnen Sie <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aenderung_nebenbestimmungen\\/index\\\">online<\\/a> die \\u00c4nderung oder Aufhebung der Nebenbestimmung beantragen.<\\/p>\\n<p><strong>Arbeitsplatzwechsel<\\/strong><\\/p>\\n<p>Ein Aufenthaltstitel zur Besch\\u00e4ftigung ist in den ersten zwei Jahren an ein Unternehmen gebunden. Wenn Sie das Unternehmen wechseln wollen, ben\\u00f6tigen Sie die Genehmigung der Ausl\\u00e4nderbeh\\u00f6rde und gegebenenfalls der Bundesagentur f\\u00fcr Arbeit.<\\/p>\\n<p>Sie brauchen keine Genehmigung, wenn Sie seit mindestens zwei Jahren mit einem Aufenthaltstitel zur Besch\\u00e4ftigung bei Ihrem Arbeitgeber gearbeitet haben.<\\/p>\\n<p><strong>Kontakt und Antragstellung:<\\/strong><\\/p>\\n<p>Wenn Sie die Nebenbestimmungen \\u00e4ndern wollen, reichen Sie bitte die ben\\u00f6tigten Unterlagen \\u00fcber unseren <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aenderung_nebenbestimmungen\\/index\\\">Online-Antrag<\\/a> ein.<\\/p>\\n<p>Wenn wir den Wechsel des Unternehmens erlauben k\\u00f6nnen, buchen wir Ihnen einen verbindlichen Termin zur Abholung Ihrer Genehmigung. Erst wenn Sie die Genehmigung von uns erhalten haben, d\\u00fcrfen Sie die neue T\\u00e4tigkeit beginnen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Arbeitgeberwechsel, Jobwechsel, Studienwechsel, Wohnsitzauflage\",\"translated\":true,\"hash\":\"\",\"id\":\"10432431\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308685\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432431\\/locations\\/10308685\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10432431\\/locations\\/10308685\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Online beantragen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aenderung_nebenbestimmungen\\/index\",\"description\":false},{\"name\":\"Arbeitsplatzwechsel mit Blauer Karte EU\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktabhakademischebeschaeftigung\\/index\",\"description\":false},{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Wechsel der Fachrichtung oder Hochschule\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten-auslaenderangelegenheiten\\/1089526\\/\",\"description\":false}],\"forms\":[{\"name\":\"Online beantragen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aenderung_nebenbestimmungen\\/index\",\"description\":false},{\"name\":\"Arbeitsplatzwechsel mit Blauer Karte EU\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktabhakademischebeschaeftigung\\/index\",\"description\":false},{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Wechsel der Fachrichtung oder Hochschule\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-buergerangelegenheiten-auslaenderangelegenheiten\\/1089526\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":6,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10432431],\"fees\":\"<p>\\u200b <span>50 Euro<\\/span><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10435223','Planeinsicht Grundstücksentwässerung – Kleinkunden','https://service.berlin.de/dienstleistung/10435223/','Sonstiges','{\"id\":\"10435223\",\"name\":\"Planeinsicht Grundst\\u00fccksentw\\u00e4sserung \\u2013 Kleinkunden\",\"description\":\"<p>Sie k\\u00f6nnen den Termin online buchen.<\\/p>\\n<p>Bei dem Termin k\\u00f6nnen Sie sich als Eigent\\u00fcmerin und Eigent\\u00fcmer die in der Vergangenheit genehmigten Entw\\u00e4sserungspl\\u00e4ne der Grundst\\u00fccksentw\\u00e4sserungsanlage Ihres Ein- und Mehrfamilienhauses ansehen. Diese Pl\\u00e4ne nennt man Bestandspl\\u00e4ne.<\\/p>\\n<p>Sie k\\u00f6nnen sich bei dem Termin von einer anderen Person vertreten lassen. Sie m\\u00fcssen dieser Person eine Vollmacht mitgeben.<\\/p>\\n<p>W\\u00e4hrend des Termins k\\u00f6nnen Sie, Ihre Vertreterin oder Ihr Vertreter Fotos von den Bestandspl\\u00e4nen machen. Sie k\\u00f6nnen auch DIN A3-Kopien von den Bestandspl\\u00e4nen machen oder vollst\\u00e4ndige digitale Plankopien im PDF-Format in Auftrag geben. Die DIN A3-Kopien und die digitalen Plankopien kosten etwas.<\\/p>\\n<p><strong>Die hier angebotenen Termine sind ausschlie\\u00dflich f\\u00fcr Eigent\\u00fcmerinnen und Eigent\\u00fcmer von Ein- oder Mehrfamilienh\\u00e4usern.<\\/strong><\\/p>\\n<p>Wenn Sie die Entw\\u00e4sserungspl\\u00e4ne der Grundst\\u00fccksentw\\u00e4sserungsanlage eines Gewerbegrundst\\u00fccks oder von mehreren <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/anwesensentwaesserung\\/10441369\\/\\\">Ein- oder Mehrfamilienh\\u00e4usern<\\/a> in einer Stra\\u00dfe ansehen m\\u00f6chten, stehen separate, l\\u00e4ngere Terminbl\\u00f6cke zur Verf\\u00fcgung.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10435223\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10222269\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435223\\/locations\\/10222269\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435223\\/locations\\/10222269\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10435223],\"fees\":\"<p>Bei Bestellung einer digitalen Plankopie fallen Geb\\u00fchren zwischen 5 und 7,50 Euro je Plan an.<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10435446','Aushändigung/Abgabe Originalunterlagen','https://service.berlin.de/dienstleistung/10435446/','Sonstiges','{\"id\":\"10435446\",\"name\":\"Aush\\u00e4ndigung\\/Abgabe Originalunterlagen\",\"description\":\"<p>Vom Bundesamt werden einbehaltene Originalunterlagen \\u00fcbersandt. Kund*innen reichen zur Identit\\u00e4tskl\\u00e4rung Unterlagen ein. Diese m\\u00fcssen nach Abschluss des Verfahrens wieder an die\\/den Kund*in ausgeh\\u00e4ndigt werden.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10435446\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1062496\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1062496\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435446\\/locations\\/1062496\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":6,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10435446]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10435450','Änderung der Nebenbestimmungen','https://service.berlin.de/dienstleistung/10435450/','Sonstiges','{\"id\":\"10435450\",\"name\":\"\\u00c4nderung der Nebenbestimmungen\",\"description\":\"<p>Nebenbestimmungen zu Besch\\u00e4ftigung oder&nbsp; Wohnsitzbeschr\\u00e4nkung\\/-auflage k\\u00f6nnen auf Antrag gestrichen werden, wenn die Voraussetzungen erf\\u00fcllt sind. Die Aufenthaltsgestattung, die Duldung oder das Zusatzblatt m\\u00fcssen hierzu ge\\u00e4ndert werden.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10435450\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1062496\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1062496\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435450\\/locations\\/1062496\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":6,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10435450]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10435454','Geburt im Bundesgebiet','https://service.berlin.de/dienstleistung/10435454/','Sonstiges','{\"id\":\"10435454\",\"name\":\"Geburt im Bundesgebiet\",\"description\":\"<p>Im Bundesgebiet geborene Kinder, die nicht die deutsche Staatsangeh\\u00f6rigkeit erwerben, ben\\u00f6tigen eine Aufenthaltserlaubnis oder eine Aufenthaltsgestattung, wenn die Eltern Asylantrag stellen oder eine Duldung.&nbsp;<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10435454\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1059487\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1059487\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1059487\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"1062496\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1062496\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435454\\/locations\\/1062496\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":4,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10435454]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10435458','Aufenthaltserlaubnis – Kriegsflüchtlinge aus der Ukraine','https://service.berlin.de/dienstleistung/10435458/','Sonstiges','{\"id\":\"10435458\",\"name\":\"Aufenthaltserlaubnis \\u2013 Kriegsfl\\u00fcchtlinge aus der Ukraine\",\"description\":\"<p><strong>Nach der Einreise<\\/strong><\\/p>\\n<p>Sobald Sie einen festen Wohnsitz in M\\u00fcnchen haben, melden Sie Ihren Wohnsitz im <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\\\">B\\u00fcrgerb\\u00fcro<\\/a> an. Vereinbaren Sie dazu online einen <a href=\\\"http:\\/\\/stadt.muenchen.de\\/terminvereinbarung_\\/terminvereinbarung_bb.html\\\">Termin<\\/a> und erhalten Sie eine Meldebescheinigung.<\\/p>\\n<p><strong>Registrierung als Kriegsfl\\u00fcchtling<\\/strong><\\/p>\\n<p>Um eine Aufenthaltserlaubnis zu erhalten, m\\u00fcssen Sie sich als Kriegsfl\\u00fcchtling registrieren. Sie k\\u00f6nnen von Montag bis Freitag zwischen 8 und 16 Uhr zum Ankunftszentrum in die Dachauer Stra\\u00dfe 122 zur Registrierung kommen.<\\/p>\\n<p><strong>Antrag auf Aufenthaltstitel<\\/strong><\\/p>\\n<p>Sie k\\u00f6nnen bis zu 90 Tage nach Ihrer erstmaligen Einreise ohne Visum in Deutschland bleiben. Danach brauchen Sie eine Aufenthaltserlaubnis. Damit d\\u00fcrfen Sie arbeiten.<\\/p>\\n<p>Sie k\\u00f6nnen den <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\">Antrag<\\/a> und die Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aufenthaltukraine\\/index\\\">online<\\/a> einreichen:<\\/p>\\n<ul>\\n <li>Laden Sie Ihre Unterlagen als PDF hoch.<\\/li>\\n <li>Nach dem Versenden Ihres Antrags erhalten Sie eine Best\\u00e4tigung \\u00fcber die weitere G\\u00fcltigkeit des Aufenthalts. Diese k\\u00f6nnen Sie als PDF speichern.<\\/li>\\n <li>Nach Antragspr\\u00fcfung bekommen Sie einen Termin und weitere Informationen.<\\/li>\\n <li>Bitte \\u00fcbersenden Sie Ihren Antrag nur <strong>einmal<\\/strong>. Familien k\\u00f6nnen den Antrag gemeinsam stellen.<\\/li>\\n<\\/ul>\\n<p><strong>G\\u00fcltigkeitsdauer<\\/strong><\\/p>\\n<p>Der Aufenthaltstitel nach \\u00a7 24 AufenthG ist bis zum <strong>4. M\\u00e4rz 2028<\\/strong> g\\u00fcltig.<\\/p>\\n<p><strong>Verl\\u00e4ngerung der Aufenthaltserlaubnis nach \\u00a7 24 AufenthG<\\/strong><\\/p>\\n<p>Ihre am 1. Februar 2026 noch g\\u00fcltige Aufenthaltserlaubnis nach \\u00a7 24 AufenthG verl\\u00e4ngert sich <strong>automatisch bis zum<\\/strong> <strong>4. M\\u00e4rz 2027<\\/strong>. Eine neue Aufenthaltserlaubnis ist nicht erforderlich und Sie m\\u00fcssen nicht zur Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung kommen. Sie k\\u00f6nnen weiterhin arbeiten. Die Nutzung der Online-Ausweisfunktion (eID) ist jedoch nicht m\\u00f6glich.<\\/p>\\n<p>Sie ben\\u00f6tigen <strong>keine<\\/strong> Neuausstellung des Aufenthaltsdokuments (eAT) in folgenden F\\u00e4llen:<\\/p>\\n<ul>\\n <li>Reisen innerhalb der <a href=\\\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/fragenkatalog-node\\/17-schengenstaaten\\/606502\\\">Schengen-Staaten<\\/a> bis zu 90 Tagen<\\/li>\\n <li>Wiedereinreise aus der Ukraine nach Deutschland<\\/li>\\n <li>Arbeitsaufnahme<\\/li>\\n <li>Beantragung von Leistungen nach SGB II und SGB XII (zum Beispiel Grundsicherung), Bundesausbildungsf\\u00f6rderungsgesetz (BAf\\u00f6G), Kindergeld, Wohngeld, Krankenkassenleistungen<\\/li>\\n<\\/ul>\\n<p>Eine Neuausstellung des eAT nach \\u00a7 24 AufenthG ist nur in Ausnahmef\\u00e4llen m\\u00f6glich, z. B. bei dringenden Reisen au\\u00dferhalb der <a href=\\\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/fragenkatalog-node\\/17-schengenstaaten\\/606502\\\">Schengen-Staaten<\\/a>. Daf\\u00fcr m\\u00fcssen Sie \\u00fcber unser <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/aufenthaltukraine\\/index\\\">Kontaktformular<\\/a> einen neuen Antrag stellen und einen Nachweis \\u00fcber den Ausnahmefall beif\\u00fcgen.<\\/p>\\n<p>Ab dem <strong>4. M\\u00e4rz 2028 gelten die Bestimmungen des Aufenthaltsgesetzes f\\u00fcr die Erteilung eines Aufenthaltstitels zu anderen Zwecken<\\/strong>.<\\/p>\\n<p>Voraussetzungen und Nachweise f\\u00fcr Aufenthaltstitel in den Bereichen Ausbildung, Studium und Arbeit finden Sie in dieser <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:18f99b99-99e3-4b0d-8129-76fda8d97fac\\/ABH_Uebersicht_Aufenthaltstitel_Ausbildung_Studium_Erwerbstaetigkeit_20220901.pdf\\\">Tabelle<\\/a>.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10435458\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1062497\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435458\\/locations\\/1062497\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10435458\\/locations\\/1062497\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Weitere Infos zur Unterst\\u00fctzung von Ukrainer*innen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/ukraine.html\",\"description\":false},{\"name\":\"FAQ Deutsch\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:0485ba8f-d262