INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10440574','Vermessungstermin: Neueinkleidung oder Größenänderung','https://service.berlin.de/dienstleistung/10440574/','Sonstiges','{\"id\":\"10440574\",\"name\":\"Vermessungstermin: Neueinkleidung oder Gr\\u00f6\\u00dfen\\u00e4nderung\",\"description\":\"<p>Dieser Termin richtet sich an alle neuen Mitarbeitenden der Branddirektion und neue Mitglieder der freiwilligen Feuerwehren. Als bestehender Mitarbeitender der Feuerwehr M\\u00fcnchen k\\u00f6nnen Sie den Termin f\\u00fcr umfangreichere Gr\\u00f6\\u00dfen\\u00e4nderungen (mehr als f\\u00fcnf Einzelartikel) nutzen. In einer pers\\u00f6nlichen Vermessung stellen wir sicher, dass die Bekleidung passgenau ausgew\\u00e4hlt wird.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10440574\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10205143\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10440574\\/locations\\/10205143\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10440574\\/locations\\/10205143\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":60,\"combinable\":[10440574]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10440759','Soziale Beratung für ukrainische Flüchtlinge','https://service.berlin.de/dienstleistung/10440759/','Sonstiges','{\"id\":\"10440759\",\"name\":\"Soziale Beratung f\\u00fcr ukrainische Fl\\u00fcchtlinge\",\"description\":\"<p>Die neuangekommenen ukrainischen Gefl\\u00fcchteten (Zielgruppen: M\\u00fctter mit Kindern, \\u00e4ltere Menschen, sowie Vulnerable (Kranke\\/Behinderte), Gefl\\u00fcchtete mit besonderen Bedarfen wie z. B. LGBTI*- Gefl\\u00fcchtete) bekommen neben einer ersten Orientierung auch Unterst\\u00fctzung bei der Vermittlung von mittelfristigem Wohnraum innerhalb M\\u00fcnchen\\/Bayerns oder bei der Weiterreise.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10440759\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10185488\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10440759\\/locations\\/10185488\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10440759\\/locations\\/10185488\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10440759]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10441364','Planeinsicht Grundstücksentwässerung – Gewerbe','https://service.berlin.de/dienstleistung/10441364/','Sonstiges','{\"id\":\"10441364\",\"name\":\"Planeinsicht Grundst\\u00fccksentw\\u00e4sserung \\u2013 Gewerbe\",\"description\":\"<p>Sie k\\u00f6nnen den Termin online buchen oder telefonisch oder per E-Mail vereinbaren.<\\/p>\\n<p>Bei dem Termin k\\u00f6nnen Sie sich als Eigent\\u00fcmerin und Eigent\\u00fcmer in der Vergangenheit genehmigte Entw\\u00e4sserungspl\\u00e4ne der Grundst\\u00fccksentw\\u00e4sserungsanlage Ihres Gewerbegrundst\\u00fccks ansehen. Oder die Entw\\u00e4sserungspl\\u00e4ne der bestehenden Grundst\\u00fccksentw\\u00e4sserungsanlagen Ihrer Ein- oder Mehrfamili-enh\\u00e4user in einer Stra\\u00dfe. Diese Pl\\u00e4ne nennt man Bestandspl\\u00e4ne.<\\/p>\\n<p>Sie k\\u00f6nnen sich bei dem Termin von einer anderen Person vertreten lassen. Sie m\\u00fcssen dieser Person eine Vollmacht mitgeben.<\\/p>\\n<p>W\\u00e4hrend des Termins k\\u00f6nnen Sie, Ihre Vertreterin oder Ihr Vertreter Fotos von den Bestandspl\\u00e4nen machen. Sie k\\u00f6nnen auch DIN A3-Kopien von den Bestandspl\\u00e4nen machen oder vollst\\u00e4ndige digitale Plankopien im PDF-Format in Auftrag geben. Die DIN A3-Kopien und die digitalen Plankopien kosten etwas.<\\/p>\\n<p><strong>Die hier angebotenen Termine sind ausschlie\\u00dflich f\\u00fcr Eigent\\u00fcmerinnen und Eigent\\u00fcmer von Gewerbegrundst\\u00fccken oder von mehreren Ein- oder Mehrfamilienh\\u00e4usern in einer Stra\\u00dfe.<\\/strong> Die Akten sind oft recht umfangreich. Deshalb bieten wir nicht so viele, daf\\u00fcr aber l\\u00e4ngere Termine an. F\\u00fcr Eigent\\u00fcmerinnen und Eigent\\u00fcmer einzelner <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/team-planauskunft-und-planverwaltung-mse-4kp\\/10435225\\/\\\">Ein- oder Mehrfamilienh\\u00e4user<\\/a> bieten wir k\\u00fcrzere, daf\\u00fcr aber zahlreichere Termine an.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10441364\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"101088\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441364\\/locations\\/101088\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441364\\/locations\\/101088\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":210,\"combinable\":[10441364],\"fees\":\"<p>Bei Bestellung einer digitalen Plankopie fallen Geb\\u00fchren zwischen 5,00 und 7,50 Euro je Plan an.<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10441370','Entwässerungsplanvorbesprechung','https://service.berlin.de/dienstleistung/10441370/','Sonstiges','{\"id\":\"10441370\",\"name\":\"Entw\\u00e4sserungsplanvorbesprechung\",\"description\":\"<p>Sie k\\u00f6nnen den Termin online vereinbaren.<br>\\n &nbsp;<br>\\n Bei dem Termin k\\u00f6nnen Sie Ihre Entw\\u00e4sserungspl\\u00e4ne mit uns besprechen, bevor Sie den Entw\\u00e4sserungsantrag stellen. Sie k\\u00f6nnen konkrete Fragen mit uns kl\\u00e4ren, die wir am Telefon oder per E-Mail nicht so einfach beantworten k\\u00f6nnen.<br>\\n &nbsp;<br>\\n Lesen Sie den <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dam\\/jcr:a5fc3522-7edf-4ee3-8c40-638541977833\\/Leitfaden_Grundstuecksentwaesserung_2023.pdf\\\">Leitfaden Grundst\\u00fccksentw\\u00e4sserung<\\/a> \\u2013 Planung und Bau vor dem Termin und beachten Sie ihn bei Ihren Entw\\u00e4sserungspl\\u00e4nen.<br>\\n &nbsp;<br>\\n Alle wichtigen Informationen zum Thema Plangenehmigung finden Sie hier: <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/genehmigung-grundstuecksentwaesserung\\/10435232\\/\\\">Genehmigung Grundst\\u00fccksentw\\u00e4sserung<\\/a><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10441370\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"101135\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441370\\/locations\\/101135\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441370\\/locations\\/101135\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Genehmigung Grundst\\u00fccksentw\\u00e4sserung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/genehmigung-grundstuecksentwaesserung\\/10435232\\/\",\"description\":false}],\"forms\":[{\"name\":\"Genehmigung Grundst\\u00fccksentw\\u00e4sserung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/genehmigung-grundstuecksentwaesserung\\/10435232\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10441370]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10441961','Führungen durch die Feuerwehrausstellung','https://service.berlin.de/dienstleistung/10441961/','Sonstiges','{\"id\":\"10441961\",\"name\":\"F\\u00fchrungen durch die Feuerwehrausstellung\",\"description\":\"<p><strong>Feuerwehrausstellung M\\u00fcnchen \\u2013 Ein Blick hinter die Kulissen<\\/strong>\\n <br>\\n Die M\\u00fcnchner Feuerwehrausstellung wurde 1979 er\\u00f6ffnet und ist seitdem eine zentrale Anlaufstelle f\\u00fcr Feuerwehrinteressierte. Der Bau wurde ma\\u00dfgeblich von Feuerwehrleuten selbst durchgef\\u00fchrt. 1984 wurde das Museum um eine besonders eindrucksvolle Attraktion erweitert: eine ausgebrannte U-Bahn, die an den verheerenden Brand von 1983 erinnert. Nach 5-j\\u00e4hriger Umzugspause er\\u00f6ffnete die Feuerwehrausstellung im Oktober 2024 in neuen R\\u00e4umlichkeiten.<\\/p>\\n<p><strong>Historische Exponate und moderne Technik<\\/strong>\\n <br>\\n Die Besucher*innen erwartet eine spannende Kombination aus modernen Technologien und historischen H\\u00f6hepunkten. Alarmmonitore und Videoclips bieten Einblicke in die Arbeit der Feuerwachen und dokumentieren wichtige Eins\\u00e4tze. F\\u00fcr die j\\u00fcngeren G\\u00e4ste gibt es ein spezielles Programm: ein Film zur Brandschutzerziehung und ein Quiz, das spielerisch Wissen vermittelt.<\\/p>\\n<p><strong>Erlebnis f\\u00fcr die ganze Familie<\\/strong>\\n <br>\\n Mit interaktiven Angeboten, historischen Exponaten und einem modernen Konzept erm\\u00f6glicht die Ausstellung ein einzigartiges Erlebnis. Sie zeigt auf eindrucksvolle Weise die Bedeutung und Tradition der Feuerwehr.<\\/p>\\n<p><strong>F\\u00fchrungen buchen<\\/strong>\\n <br>\\n F\\u00fchrungen sind ab einer Gruppengr\\u00f6\\u00dfe von 15 bis maximal 50 Personen m\\u00f6glich. Die F\\u00fchrung dauert etwa 90 Minuten.<\\/p>\\n<p><strong>Barrierefreie F\\u00fchrungen mit Geb\\u00e4rdensprachdolmetscher*in<\\/strong>\\n <br>\\n F\\u00fcr geh\\u00f6rlose B\\u00fcrger*innen bieten wir regelm\\u00e4\\u00dfig barrierefreie F\\u00fchrungen durch die Feuerwehrausstellung mit Geb\\u00e4rdensprachdolmetscher*in an. Diese speziellen F\\u00fchrungen erm\\u00f6glichen einen gleichberechtigten Zugang zu allen Inhalten der Ausstellung. Geh\\u00f6rlose Kinder d\\u00fcrfen selbstverst\\u00e4ndlich von ihren Eltern begleitet werden. <strong>Wichtig:<\\/strong> Diese F\\u00fchrungen k\\u00f6nnen nicht \\u00fcber diese Seite, sondern ausschlie\\u00dflich \\u00fcber folgenden Link gebucht werden: <a href=\\\"https:\\/\\/veranstaltungen.muenchen.de\\/branddirektion\\/veranstaltungen\\/\\\" target=\\\"\\\">F\\u00fchrung mit Geb\\u00e4rdensprachdolmetscher*in<\\/a> \\u200b<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10441961\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"1080708\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441961\\/locations\\/1080708\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10441961\\/locations\\/1080708\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"M\\u00fcnchner Feuerwehrausstellung \\u2013 Informationen und Fotos\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/feuerwehrausstellung-muenchen.html\",\"description\":false},{\"name\":\"F\\u00fchrung mit Geb\\u00e4rdensprachdolmetscher*in\",\"link\":\"https:\\/\\/veranstaltungen.muenchen.de\\/branddirektion\\/veranstaltungen\\/\",\"description\":false},{\"name\":\"F\\u00fchrungen auf den Feuerwachen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fuehrungen-auf-den-feuerwachen\\/10389330\\/n0\\/\",\"description\":false}],\"forms\":[{\"name\":\"M\\u00fcnchner Feuerwehrausstellung \\u2013 Informationen und Fotos\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/feuerwehrausstellung-muenchen.html\",\"description\":false},{\"name\":\"F\\u00fchrung mit Geb\\u00e4rdensprachdolmetscher*in\",\"link\":\"https:\\/\\/veranstaltungen.muenchen.de\\/branddirektion\\/veranstaltungen\\/\",\"description\":false},{\"name\":\"F\\u00fchrungen auf den Feuerwachen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/fuehrungen-auf-den-feuerwachen\\/10389330\\/n0\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":90,\"combinable\":[10441961],\"fees\":\"<p>Die Ausstellung kann kostenlos besucht werden.<\\/p>\"}',NULL,NULL);
