INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10460108','Parkausweis','https://service.berlin.de/dienstleistung/10460108/','Sonstiges','{\"id\":\"10460108\",\"name\":\"Parkausweis\",\"description\":\"<p>Das ist eine Fake Dienstleistung um den E-Kiosk mit nur einer Dienstleistung zu versorgen. Unsere Kund*innen tun sich leichter, wenn keine Wahlm\\u00f6glichkeit besteht. Es kommt geh\\u00e4uft vor, dass Kund*innen mehrere Nummern ziehen, nicht wissen f\\u00fcr welche Dienstleistung sie eine Nummer ziehen m\\u00fcssen oder auch gelegentlich Nummern im Automaten zur\\u00fccklassen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10460108\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10460108\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10460108\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[10460108]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10460313','Einzelbetriebserlaubnis für zulassungsfreie Fahrzeuge','https://service.berlin.de/dienstleistung/10460313/','Sonstiges','{\"id\":\"10460313\",\"name\":\"Einzelbetriebserlaubnis f\\u00fcr zulassungsfreie Fahrzeuge\",\"description\":\"<p>\\u200bBestimmte Fahrzeuge oder Anh\\u00e4nger sind zulassungsfrei und unterliegen nicht der Kennzeichenpflicht. Das sind zum Beispiel Kleinkraftr\\u00e4der, Elektrokleinstfahrzeuge, selbstfahrende Arbeitsmaschinen, Spezialanh\\u00e4nger f\\u00fcr Sportzwecke oder Anh\\u00e4nger f\\u00fcr land- und forstwirtschaftliche Arbeitsger\\u00e4te. Sie ben\\u00f6tigen jedoch eine g\\u00fcltige Betriebserlaubnis, bevor Sie diese Fahrzeuge oder Anh\\u00e4nger auf \\u00f6ffentlichen Stra\\u00dfen nutzen d\\u00fcrfen.<\\/p>\\n<p>In den meisten F\\u00e4llen erteilt der Hersteller die Betriebserlaubnis in Form einer Allgemeinen Betriebserlaubnis oder EU-Betriebserlaubnis.\\n <br>\\n Liegt diese vor, m\\u00fcssen Sie nichts weiter veranlassen.\\n <br>\\n Liegt keine Betriebserlaubnis vor oder ist diese aufgrund einer technischen \\u00c4nderung ung\\u00fcltig geworden, erteilt Ihnen die Kfz-Zulassungsstelle eine Einzelbetriebserlaubnis.<\\/p>\\n<p>Sie ben\\u00f6tigen hierf\\u00fcr einen Termin bei der Kfz-Zulassungsstelle. Sie k\\u00f6nnen den Termin online buchen oder per E-Mail oder telefonisch vereinbaren. Das Servicetelefon hat die Telefonnummer 089\\/233-96090.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10460313\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10416\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10460313\\/locations\\/10416\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10460313\\/locations\\/10416\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktformularzulassungsstelle\\/index\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktformularzulassungsstelle\\/index\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10460313],\"fees\":\"<p>Ab 39,50 Euro (wenn Ausnahmegenehmigungen erforderlich sind, k\\u00f6nnen diese deutlich h\\u00f6her ausfallen)<\\/p>\"}',NULL,NULL);
