INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10473494','Einschalten der eID-Funktion oder Änderung der PIN – Elektronischer Aufenthaltstitel','https://service.berlin.de/dienstleistung/10473494/','Sonstiges','{\"id\":\"10473494\",\"name\":\"Einschalten der eID-Funktion oder \\u00c4nderung der PIN \\u2013 Elektronischer Aufenthaltstitel\",\"description\":\"<p>Mit der Online- Ausweisfunktion k\\u00f6nnen Sie sich im Internet und an Automaten ausweisen. Dadurch k\\u00f6nnen Sie einfacher mit Online-Shops, Banken, Versicherungen, Beh\\u00f6rden, sozialen Netzwerken und Unternehmen kommunizieren und m\\u00fcssen sich nicht mehr so viele Passw\\u00f6rter und Benutzernamen merken. Um sich online ausweisen zu k\\u00f6nnen, ist eine aktivierte Online-Ausweisfunktion PIN notwendig.<\\/p>\\n<p>Sollte Ihre Online-Ausweisfunktion noch nicht aktiviert sein und\\/oder Sie finden Ihren PIN-Brief nicht mehr beziehungsweise haben Ihre PIN vergessen, k\\u00f6nnen Sie sich an die Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung wenden.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"eAT, Pin, eID, Onlineausweisfunktion, Ausl\\u00e4nder, Ausl\\u00e4nderinnen, \\u00c4nderung Pin\",\"translated\":true,\"hash\":\"\",\"id\":\"10473494\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308621\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10473494\\/locations\\/10308621\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10473494\\/locations\\/10308621\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Personalausweisportal\",\"link\":\"https:\\/\\/www.bmi.bund.de\\/DE\\/themen\\/moderne-verwaltung\\/ausweise-und-paesse\\/online-ausweisfunktion\\/online-ausweisfunktion-node.html\",\"description\":false},{\"name\":\"Elektronischer Aufenthaltstitel (eAT)\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/MigrationAufenthalt\\/ZuwandererDrittstaaten\\/Migrathek\\/eAufenthaltstitel\\/eaufenthaltstitel-node.html\",\"description\":false}],\"forms\":[{\"name\":\"Kontaktformular\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/abhkontakt\\/index\",\"description\":false},{\"name\":\"Personalausweisportal\",\"link\":\"https:\\/\\/www.bmi.bund.de\\/DE\\/themen\\/moderne-verwaltung\\/ausweise-und-paesse\\/online-ausweisfunktion\\/online-ausweisfunktion-node.html\",\"description\":false},{\"name\":\"Elektronischer Aufenthaltstitel (eAT)\",\"link\":\"https:\\/\\/www.bamf.de\\/DE\\/Themen\\/MigrationAufenthalt\\/ZuwandererDrittstaaten\\/Migrathek\\/eAufenthaltstitel\\/eaufenthaltstitel-node.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[10473494],\"fees\":\"<p>\\u200bgeb\\u00fchrenfrei<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10477438','Ausgabe Taxigenehmigung aus Warteliste','https://service.berlin.de/dienstleistung/10477438/','Sonstiges','{\"id\":\"10477438\",\"name\":\"Ausgabe Taxigenehmigung aus Warteliste\",\"description\":\"<p><strong>Bei der Erteilung von Taxigenehmigungen \\u00fcber eine Warteliste werden Neubewerber*innen und Personen, die bereits eine oder mehrere Taxigenehmigungen besitzen angemessen ber\\u00fccksichtigt. Innerhalb der Gruppen werden die Bewerber*innen nach der zeitlichen Reihenfolge des Eingangs des Antrags auf Aufnahme in die Warteliste ber\\u00fccksichtigt. Nachdem sie eine Mitteilung \\u00fcber die Ausgabe aus der Warteliste erhalten haben, k\\u00f6nnen die Bewerber*innen einen Termin zur Antragstellung bzw. Beratung vereinbaren.<\\/strong><\\/p>\\n<p>Das Kreisverwaltungsreferat pr\\u00fcft bei dem Termin, ob die Genehmigungsvoraussetzungen des Art. 13 Personenbef\\u00f6rderungsgesetz (PBefG) erf\\u00fcllt sind und ob die Voraussetzungen f\\u00fcr die Ausgabe aus der Warteliste noch vorliegen.\\n <br>\\n Antragstellende werden unabh\\u00e4ngig vom Zeitpunkt der Antragstellung nachrangig behandelt, wenn sie<\\/p>\\n<p>1. das Taxengewerbe nicht als Hauptbesch\\u00e4ftigung zu betreiben beabsichtigen,<\\/p>\\n<p>2. ihr Unternehmen nicht als Hauptbesch\\u00e4ftigung betrieben haben oder innerhalb der letzten acht Jahre ganz oder teilweise ver\\u00e4u\\u00dfert oder verpachtet haben oder<\\/p>\\n<p>3. ihrer Betriebspflicht nicht ordnungsgem\\u00e4\\u00df nachgekommen sind.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10477438\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10238880\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10477438\\/locations\\/10238880\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10477438\\/locations\\/10238880\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":45,\"combinable\":[10477438],\"fees\":\"<p>\\u200b In der Regel 120 \\u20ac<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10478703','Fahrzeug abmelden ohne Zulassungsbescheinigung I oder Fahrzeugschein','https://service.berlin.de/dienstleistung/10478703/','Sonstiges','{\"id\":\"10478703\",\"name\":\"Fahrzeug abmelden ohne Zulassungsbescheinigung I oder Fahrzeugschein\",\"description\":\"<p>Wenn Sie Ihr Fahrzeug abmelden m\\u00f6chten, aber die Zulassungsbescheinigung Teil I (fr\\u00fcher: Fahrzeugschein) verloren haben, m\\u00fcssen Sie ein neues Dokument bei der Zulassungsbeh\\u00f6rde beantragen, bei der das Fahrzeug gemeldet ist.<\\/p>\\n<p>In der Zulassungsstelle in der Eichst\\u00e4tter Stra\\u00dfe k\\u00f6nnen alle Kennzeichen mit \\u201eM\\u201c (f\\u00fcr M\\u00fcnchen Stadt), alle \\u201eMUC\\u201c-Kennzeichen und alle ausw\\u00e4rtigen Kennzeichen, die nach M\\u00fcnchen (Stadt) umgemeldet wurden, mit einem Zulassungsbescheid Teil I oder Fahrzeugscheinverlust abgemeldet werden.<\\/p>\\n<p>F\\u00fcr Fahrzeuge aus dem Landkreis M\\u00fcnchen wenden Sie sich bitte an das Landratsamt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10478703\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102101\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10478703\\/locations\\/102101\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10478703\\/locations\\/102101\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true}