INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10490860','Reparatur und Verschleiß','https://service.berlin.de/dienstleistung/10490860/','Sonstiges','{\"id\":\"10490860\",\"name\":\"Reparatur und Verschlei\\u00df\",\"description\":\"<p>Bei defekten oder stark abgenutzten Artikeln vereinbaren Sie bitte diesen Termin. Wir pr\\u00fcfen, ob eine Reparatur m\\u00f6glich ist oder ein Austausch erfolgt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10490860\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10205143\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10490860\\/locations\\/10205143\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10490860\\/locations\\/10205143\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[10490860]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10492627','Medizinproduktunterweisung – Teil A','https://service.berlin.de/dienstleistung/10492627/','Sonstiges','{\"id\":\"10492627\",\"name\":\"Medizinproduktunterweisung \\u2013 Teil A\",\"description\":\"<p>In insgesamt 240 Minuten bieten wir Ihnen eine umfassende Einweisung in die Nutzung der Medizinger\\u00e4te der Feuerwehr M\\u00fcnchen f\\u00fcr den gemeinsamen Notarztdienst.<\\/p>\\n<p>Nach Abschluss der Schulung sind Sie in der Lage, die Medizinger\\u00e4te rechtssicher und kompetent einzusetzen.\\n <br>\\n <br>\\n Die Einweisungen finden regelm\\u00e4\\u00dfig in der Mitte eines Quartals an zwei aufeinanderfolgenden Abenden statt und bestehen aus Teil A und Teil B. In Teil A werden folgende Ger\\u00e4te geschult:<\\/p>\\n<ul>\\n <li>Monitor- und Defibrillationseinheit (corpuls3T SLIM)\\n  <br><\\/li>\\n <li>Thoraxkompressionsger\\u00e4t (corpuls cpr)\\n  <br><\\/li>\\n<\\/ul>\\n<p>Die Veranstaltung ist nicht barrierefrei.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10492627\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10433938\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10492627\\/locations\\/10433938\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10492627\\/locations\\/10433938\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Medizinproduktunterweisung - Teil B\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/medizingeratemanagement\\/10492632\\/\",\"description\":false}],\"forms\":[{\"name\":\"Medizinproduktunterweisung - Teil B\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/medizingeratemanagement\\/10492632\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":240,\"combinable\":[10492627],\"fees\":\"<p>kostenlos<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10492628','Medizinproduktunterweisung – Teil B','https://service.berlin.de/dienstleistung/10492628/','Sonstiges','{\"id\":\"10492628\",\"name\":\"Medizinproduktunterweisung \\u2013 Teil B\",\"description\":\"<p>In insgesamt 240 Minuten bieten wir Ihnen eine umfassende Einweisung in die Nutzung der Medizinger\\u00e4te der Feuerwehr M\\u00fcnchen f\\u00fcr den gemeinsamen Notarztdienst.<\\/p>\\n<p>Nach Abschluss der Schulung sind Sie in der Lage, die Medizinger\\u00e4te rechtssicher und kompetent einzusetzen.\\n <br>\\n <br>\\n Die Einweisungen finden regelm\\u00e4\\u00dfig in der Mitte eines Quartals an zwei aufeinanderfolgenden Abenden statt und bestehen aus Teil A und Teil B. In Teil B werden folgende Ger\\u00e4te geschult:<\\/p>\\n<ul>\\n <li>Thoraxkompressionssystem (LUCAS II &amp; III)<\\/li>\\n <li>Notfall- und Transportbeatmungsger\\u00e4t (WEINMANN Medumat Standard2)<\\/li>\\n <li>Notfallbeatmungsger\\u00e4t (OXYLATOR EMX)<\\/li>\\n <li>Spritzenpumpe (FRESENIUS KABI agilia)<\\/li>\\n <li>Spritzenpumpe (B.BRAUN Perfusor Space)\\n  <br><\\/li>\\n <li>Videolaryngoskop (McGrath)<\\/li>\\n <li>Absaugpumpe (WEINMANN Accuvac Pro)<\\/li>\\n <li>IO-Zugang-System (Arrow EZ-IO)<\\/li>\\n <li>Blutzuckermessger\\u00e4t (contour XT)<\\/li>\\n <li>Blutzuckermessger\\u00e4t (CareSens N NFC)<\\/li>\\n <li>Ohrthermometer (Braun ThermoScan PRO 6000)\\n  <br><\\/li>\\n<\\/ul>\\n<p>Die Veranstaltung ist nicht barrierefrei.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10492628\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10433958\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10492628\\/locations\\/10433958\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10492628\\/locations\\/10433958\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Medizinproduktunterweisung - Teil A\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/medizingeratemanagement\\/10492630\\/\",\"description\":false}],\"forms\":[{\"name\":\"Medizinproduktunterweisung - Teil A\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/medizingeratemanagement\\/10492630\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":240,\"combinable\":[10492628],\"fees\":\"<p>kostenlos\\n <br><\\/p>\"}',NULL,NULL);
