INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','10502137','Abholung elektronischer Aufenthaltstitel, elektronischer Reiseausweis','https://service.berlin.de/dienstleistung/10502137/','Sonstiges','{\"id\":\"10502137\",\"name\":\"Abholung elektronischer Aufenthaltstitel, elektronischer Reiseausweis\",\"description\":\"<p>Sofern Sie bei der Beantragung Ihres Dokuments keinen Direktversand \\u00fcber die Bundesdruckerei gebucht haben, k\\u00f6nnen Sie einen Termin zur Abholung Ihres elektronischen Aufenthaltstitels oder Reiseausweises buchen. Jeden Morgen werden Termine zur Abholung freigeschaltet: Montag, Mittwoch und Freitag um 7.30 Uhr sowie Dienstag und Donnerstag um 8.30 Uhr.\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\",\"translated\":true,\"hash\":\"\",\"id\":\"10502137\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10456\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10502137\\/locations\\/10456\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/10502137\\/locations\\/10456\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Vollmacht zur Abholung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/Vollmacht_Abholung_eAT.pdf\",\"descr