INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063422','Gewerbe-Ummeldung','https://service.berlin.de/dienstleistung/1063422/','Sonstiges','{\"id\":\"1063422\",\"name\":\"Gewerbe-Ummeldung\",\"description\":\"<p>\\u200bVerlegen Sie den Standort Ihres Gewerbes innerhalb M\\u00fcnchens, wechseln oder dehnen Sie den Gegenstand des Gewerbes aus oder soll eine Namens\\u00e4nderung vorgenommen werden, melden Sie dies in Form einer Ummeldung.<\\/p>\\n<p>Bitte beachten Sie die Besonderheiten bei Rechtsformwechsel und Verschmelzung, die wir in unseren Fragen und Antworten f\\u00fcr Sie zusammengestellt haben.<\\/p>\\n<p><strong>So funktioniert die Online-Ummeldung:<\\/strong><\\/p>\\n<ol>\\n <li><strong>Ummeldung starten<\\/strong><\\/li>\\n <li><strong>Mit BayernID anmelden<\\/strong>\\n  <br>\\n  Wenn Sie noch keine BayernID haben, k\\u00f6nnen Sie sich in wenigen Minuten mit Benutzername und Passwort registrieren. Eine Identifizierung mit Online-Ausweis (eID) ist nicht erforderlich.<\\/li>\\n <li><strong>Unterlagen hochladen<\\/strong><\\/li>\\n <li><strong>Online zahlen<\\/strong><\\/li>\\n <li><strong>Gewerbeschein per Post erhalten<\\/strong><\\/li>\\n<\\/ol>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Gewerbebeh\\u00f6rde, Gewerbe anzeigen, Verlegung Gewerbe, Gewerbe, Gewerbe ummelden, Gewerbeanmeldung, Gewerbliche T\\u00e4tigkeit, Ummeldung, \\u00c4nderung anzeigen, Standort\\u00e4nderung Gewerbe, \\u00c4nderung Standort, Ausweitung Angebot Gewerbe, Gewerbeumschreibung, Gewerbeummeldung verloren, Verlust Gewerbeummeldung, Erweiterung Gewerbe, Gewerbescheinerweiterung, Gewerbemeldung, Gewerbebescheinigung, Gewerbeumeldung, Gewerbeerweiterung\",\"translated\":true,\"hash\":\"\",\"id\":\"1063422\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10546\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063422\\/locations\\/10546\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063422\\/locations\\/10546\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99050012071000\",\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[1063422],\"fees\":\"<p>40 Euro<br><br><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063423','Gewerbe-Anmeldung','https://service.berlin.de/dienstleistung/1063423/','Sonstiges','{\"id\":\"1063423\",\"name\":\"Gewerbe-Anmeldung\",\"description\":\"<p>\\u200bSie haben eine gewerbliche Niederlassung als Haupt- oder Filialbetrieb in M\\u00fcnchen. Ihre T\\u00e4tigkeit kann entweder im Haupt- oder Nebenberuf ausge\\u00fcbt werden. Ma\\u00dfgeblich ist lediglich die Absicht, Gewinn zu erzielen und nicht die tats\\u00e4chliche Erwirtschaftung eines Gewinns.<\\/p>\\n<p>Reichen Sie Ihre Gewerbeanmeldung rechtzeitig <strong>vor oder sp\\u00e4testens mit Aufnahme der T\\u00e4tigkeit<\\/strong> ein.<\\/p>\\n<p><strong>So funktioniert die Online-Anmeldung:<\\/strong><\\/p>\\n<ol>\\n <li><strong>Anmeldung starten<\\/strong><\\/li>\\n <li><strong>Mit BayernID anmelden<\\/strong>\\n  <br>\\n  Wenn Sie noch keine BayernID haben, k\\u00f6nnen Sie sich in wenigen Minuten mit Benutzername und Passwort registrieren. Eine Identifizierung mit Online-Ausweis (eID) ist nicht erforderlich.<\\/li>\\n <li><strong>Unterlagen hochladen<\\/strong><\\/li>\\n <li><strong>Online zahlen<\\/strong><\\/li>\\n <li><strong>Gewerbeschein per Post erhalten<\\/strong><\\/li>\\n<\\/ol>\\n<p>Falls Sie noch weitere Informationen zu allen Themen rund um die Existenzgr\\u00fcndung ben\\u00f6tigen, bietet Ihnen das M\\u00fcnchner Gr\\u00fcndungsb\\u00fcro ein breites <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/referat-fur-arbeit-und-wirtschaft-munchner-grundungsburo\\/10208157\\/\\\">Beratungs- und Informationsangebot<\\/a>.\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Gewerbebeh\\u00f6rde, Gewerbe anzeigen, Anmeldung Gewerbe, Gewerbe, Gewerbe anmelden, Gewerbeanmeldung, Gewerbliche T\\u00e4tigkeit, Gewerbeschein verloren, Verlust der Gewerbeanmeldung, Zweitschrift Gewerbeanmeldung, Gewerbebescheinigung, Gewerbemeldung\",\"translated\":true,\"hash\":\"\",\"id\":\"1063423\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10546\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063423\\/locations\\/10546\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063423\\/locations\\/10546\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99050012104000\",\"public\":true,\"links\":[],\"forms\":[],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[1063423],\"fees\":\"<p>50 bis 60 Euro (abh\\u00e4ngig von der Rechtsform)<br><br><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063424','Umschreibung Fahrzeug – innerhalb Münchens','https://service.berlin.de/dienstleistung/1063424/','Sonstiges','{\"id\":\"1063424\",\"name\":\"Umschreibung Fahrzeug \\u2013 innerhalb M\\u00fcnchens\",\"description\":\"<p>Mit Ihrer Online-Ausweis-Funktion k\\u00f6nnen Sie ganz bequem von zu Hause aus Ihr Fahrzeug Online ummelden.<\\/p>\\n<ul>\\n <li>Wenn das Fahrzeug in M\\u00fcnchen noch zugelassen ist, k\\u00f6nnen Sie das Kennzeichen behalten. Sie k\\u00f6nnen auch ein neues Kennzeichen verwenden.<\\/li>\\n <li>Wenn das Fahrzeug derzeit nicht in Betrieb (stillgelegt) ist, ben\\u00f6tigen Sie ein neues Kennzeichen.<\\/li>\\n <li>Sie haben die M\\u00f6glichkeit, ein Wunschkennzeichen zu beantragen.<\\/li>\\n <li>Wenn Sie innerhalb M\\u00fcnchens umziehen, m\\u00fcssen Sie Ihr Fahrzeug nicht umschreiben, aber die Adress\\u00e4nderung in die Zulassungsbescheinigung Teil I eintragen lassen.<\\/li>\\n<\\/ul>\\n<p>Haben Sie Ihre PIN f\\u00fcr Ihre Online-Ausweis-Funktion nicht mehr, so k\\u00f6nnen Sie sich in <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/nachtraegliches-einschalten-eid-funktion-oder-aenderung-der-pin\\/10225119\\/n0\\/\\\">jedem B\\u00fcrgerb\\u00fcro eine neue PIN<\\/a> vergeben lassen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ummeldung, Umschreibung, Besitzerwechsel, Umschreibung eines Fahrzeugs, Umschreibung mit Halterwechsel, Umschreiben Anh\\u00e4nger, Wohnanh\\u00e4nger\",\"translated\":true,\"hash\":\"\",\"id\":\"1063424\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063424\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063424\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036008003000\",\"public\":true,\"links\":[{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Wunschkennzeichen reservieren\",\"link\":\"https:\\/\\/www.buergerservice-portal.de\\/bayern\\/muenchen\\/igvwkz\\/#\\/\",\"description\":false}],\"forms\":[{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Wunschkennzeichen reservieren\",\"link\":\"https:\\/\\/www.buergerservice-portal.de\\/bayern\\/muenchen\\/igvwkz\\/#\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1063424,1064121,1064354,1064308,10387573,1064275,1064314,1064130,1064333,1063425,10391602,1064271,1080502,1064323,1064342,1071959,1064311,10387564],\"fees\":\"<p><strong>Online-Geb\\u00fchr: Online-Zahlung \\/ Kreditkarte \\/ EC-Karte m\\u00f6glich<\\/strong> \\u200b<br>\\n mit Beibehalt des Kennzeichens: ab 17,80 Euro<br>\\n mit Zuteilung eines neuen Kennzeichens: ab 20,50 Euro<\\/p>\\n<p><strong>vor-Ort-Geb\\u00fchr: nur mit EC-Karte \\/ Barzahlung<\\/strong> <br>\\n mit Beibehalt des Kennzeichens: ab 24,20 Euro<br>\\n mit Zuteilung eines neuen Kennzeichens: ab 27,10 Euro<\\/p>\\n<p>Wunschkennzeichen: 12,80 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063425','Anmeldung fabrikneues Fahrzeug oder Tageszulassung','https://service.berlin.de/dienstleistung/1063425/','Sonstiges','{\"id\":\"1063425\",\"name\":\"Anmeldung fabrikneues Fahrzeug oder Tageszulassung\",\"description\":\"<p>Mit Ihrer Online-Ausweis-Funktion k\\u00f6nnen Sie ganz bequem von zu Hause aus Ihr Fahrzeug online Anmelden.<\\/p>\\n<p>Haben Sie Ihre PIN f\\u00fcr Ihre Online-Ausweis-Funktion nicht mehr, so k\\u00f6nnen Sie sich in <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/nachtraegliches-einschalten-eid-funktion-oder-aenderung-der-pin\\/10225119\\/n0\\/\\\">jedem B\\u00fcrgerb\\u00fcro eine neue PIN<\\/a> vergeben lassen.<\\/p>\\n<p>F\\u00fcr Elektrofahrzeuge kann optional ein <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/hauptabteilung-ii-fahrzeugzulassungs-und-fahrerlaubnisbehorde\\/10193516\\/\\\"><strong>E-Kennzeichen<\\/strong><\\/a> beantragt werden. Nur mit einem E-Kennzeichen k\\u00f6nnen Parkerleichterungen im Stadtgebiet M\\u00fcnchen automatisch erkannt werden.\\n <br><\\/p>\\n<p>Wichtige Informationen f\\u00fcr die <strong>Online-Zulassung eines Motorrades<\\/strong> finden Sie unter \\u201eFragen &amp; Antworten\\u201c.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Neuwagen anmelden, Fahrzeug erstmalig anmelden, Anh\\u00e4nger anmelden, Autoanh\\u00e4nger zulassen, Wohnanh\\u00e4nger anmelden, Wohnmobil anmelden, erstmalig Zulassungsbescheinigung Teil II ausstellen, Motorrad anmelden, Motorrad zulassen, kfzzulassung\",\"translated\":true,\"hash\":\"\",\"id\":\"1063425\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"aut