INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063475','Wohnsitzanmeldung','https://service.berlin.de/dienstleistung/1063475/','Sonstiges','{\"id\":\"1063475\",\"name\":\"Wohnsitzanmeldung\",\"description\":\"<p>Die An- oder Ummeldung Ihres Wohnsitzes k\\u00f6nnen Sie entweder online oder pers\\u00f6nlich in einem der B\\u00fcrgerb\\u00fcros vornehmen. Bei der pers\\u00f6nlichen Anmeldung m\\u00fcssen Sie selbst erscheinen \\u2013 Sie k\\u00f6nnen aber auch eine bevollm\\u00e4chtigte Person mit der Anmeldung beauftragen.<\\/p>\\n<p><strong>Der Online-Service ist nur f\\u00fcr Hauptwohnsitze m\\u00f6glich. Eine An- oder Ummeldung von Nebenwohnsitzen ist online nicht m\\u00f6glich.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ummelden, Anmelden, Umzug, Ummeldung, Einwohnermeldeamt, Zweitwohnsitz, Nebenwohnsitz, mehrere Wohnungen anmelden, Adressaufkleber f\\u00fcr Personalausweis, Anmeldebest\\u00e4tigung, Meldeschein\",\"translated\":true,\"hash\":\"\",\"id\":\"1063475\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063475\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063475\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102523\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtve