INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063486','Wohnsitz abmelden','https://service.berlin.de/dienstleistung/1063486/','Sonstiges','{\"id\":\"1063486\",\"name\":\"Wohnsitz abmelden\",\"description\":\"<p><strong>Bei einem Umzug innerhalb Deutschlands m\\u00fcssen Sie sich nicht abmelden.<\\/strong><\\/p><p><strong>Aufgabe einer Nebenwohnung:<br><\\/strong>Die Abmeldung einer Nebenwohnung kann bei der Meldebeh\\u00f6rde des Haupt- oder Nebenwohnsitzes erfolgen.<br>Wenn Sie Ihre Zweitwohnung in M\\u00fcnchen abmelden, wird das Kassen-und Steueramt automatisch dar\\u00fcber informiert.<\\/p><p><strong>Wegzug ins Ausland:<br><\\/strong>Wenn Sie ins Ausland wegziehen, k\\u00f6nnen Sie bei der Abmeldung Ihre Anschrift im Ausland hinterlassen. Die Auslandsanschrift wird im Melderegister gespeichert. In diesem Fall k\\u00f6nnen wir zum Beispiel im Zusammenhang mit Wahlen mit Ihnen Kontakt aufnehmen.<\\/p><p><strong>Bitte beachten Sie, dass Sie m\\u00f6glicherweise die Pflicht haben, Ihren Wohnungswechsel auch anderen Beh\\u00f6rden zu melden (zum Beispiel der Gewerbebeh\\u00f6rde oder Kfz-Zulassungsbeh\\u00f6rde).<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Abmeldung, Umzug, Wegziehen, Auswandern, Wohnsitzabmeldung, Zeitwohnsitz abmelden, Nebenwohnsitz abmelden, Zweitwohnung abmelden, Nebenwohnung abmelden\",\"translated\":true,\"hash\":\"\",\"id\":\"1063486\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\