INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063505','Melderegisterauskunft','https://service.berlin.de/dienstleistung/1063505/','Sonstiges','{\"id\":\"1063505\",\"name\":\"Melderegisterauskunft\",\"description\":\"<p>Im Melderegister der Landeshauptstadt M\\u00fcnchen sind alle Personen registriert, die in M\\u00fcnchen einen Wohnsitz angemeldet haben. Unter bestimmten rechtlichen Voraussetzungen k\\u00f6nnen Sie Auskunft \\u00fcber einzelne der gespeicherten Daten zu einer anderen Person erhalten.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Personensuche, Meldeauskunft, Erweiterte Melderegisterauskunft, Adressauskunft, Adressermittlung, Einwohnerauskunft, Melderegisteranfrage, Personenauskunft, Adressenauskunft, Einwohnermeldeauskunft, Ledigennachweis\",\"translated\":true,\"hash\":\"\",\"id\":\"1063505\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[],\"leika\":\"99115004000000\",\"public\":false,\"links\":[{\"name\":\"Stadtarchiv\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/stadtarchivmuenchen.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"\\u00dcbermittlungssperre von Daten\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063553\\/n0\\/\",\"description\":false},{\"name\":\"Auskunftssperre\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063534\\/n0\\/\",\"description\":false},{\"name\":\"Einfache Melderegisterauskunft\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Buergerbuero\\/Dokum