INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1063565','Führungszeugnis','https://service.berlin.de/dienstleistung/1063565/','Sonstiges','{\"id\":\"1063565\",\"name\":\"F\\u00fchrungszeugnis\",\"description\":\"<p>Das F\\u00fchrungszeugnis k\\u00f6nnen Sie online beim Bundesamt f\\u00fcr Justiz oder schriftlich (per Post) und pers\\u00f6nlich bei der Meldebeh\\u00f6rde Ihrer Haupt- oder Nebenwohnung beantragen. Bei schriftlicher oder pers\\u00f6nlicher Antragstellung leiten wir den Antrag an das Bundesamt f\\u00fcr Justiz zur Pr\\u00fcfung und Erledigung weiter. Hier wird das F\\u00fchrungszeugnis ausgestellt und entweder an Sie oder an die benannte Beh\\u00f6rde geschickt.<\\/p>\\n<p>Die Auskunft aus dem Bundeszentralregister wird im allgemeinen Sprachgebrauch auch \\u201epolizeiliches F\\u00fchrungszeugnis\\u201c genannt. Es gibt folgende Arten von F\\u00fchrungszeugnissen:<\\/p>\\n<p><strong>F\\u00fchrungszeugnis f\\u00fcr private Zwecke<\\/strong>\\n <br>\\n Sie bekommen das F\\u00fchrungszeugnis mit der Post zugeschickt und k\\u00f6nnen es an die Stelle (zum Beispiel Verein, Personalb\\u00fcro) weiterleiten, die das F\\u00fchrungszeugnis von Ihnen angefordert hat.<\\/p>\\n<p><strong>F\\u00fchrungszeugnis f\\u00fcr eine Beh\\u00f6rde<\\/strong>\\n <br>\\n Wenn Sie das F\\u00fchrungszeugnis zur Vorlage bei einer Beh\\u00f6rde ben\\u00f6tigen, wird der genaue Verwendungszweck im Antrag vermerkt und das F\\u00fchrungszeugnis direkt dorthin gesandt. Wenn Sie vorher erfahren wollen, was in Ihrem F\\u00fchrungszeugnis steht, k\\u00f6nnen Sie bei einem Amtsgericht Ihrer Wahl Einsicht nehmen.<\\/p>\\n<p><strong>Erweitertes F\\u00fchrungszeugnis<\\/strong>\\n <br>\\n Ein erweitertes F\\u00fchrungszeugnis ben\\u00f6tigen vor allem Personen, die hauptberuflich oder ehrenamtlich im Kinder- und Jugendbereich t\\u00e4tig sind oder t\\u00e4tig werden wollen (zum Beispiel Schule, Sportverein). Dieses enth\\u00e4lt auch Eintragungen, die f\\u00fcr die Pr\\u00fcfung der Eignung f\\u00fcr den Umgang mit Kindern und Jugendlichen von besonderer Bedeutung sind. Aufgrund gesetzlicher Regelungen kann die Vorlage eines erweiterten F\\u00fchrungszeugnisses auch f\\u00fcr T\\u00e4tigkeiten im Erwachsenenbereich verlangt werden (zum Beispiel in bestimmten Einrichtungen f\\u00fcr Menschen mit Behinderung oder Pflegebed\\u00fcrftige). In diesem Fall werden Sie von Ihrer Arbeitsstelle informiert.<\\/p>\\n<p><strong>Europ\\u00e4isches F\\u00fchrungszeugnis<\\/strong>\\n <br>\\n Ein Europ\\u00e4isches F\\u00fchrungszeugnis erhalten Personen, die \\u2013 neben oder anstatt der deutschen \\u2013 die Staatsangeh\\u00f6rigkeit eines oder mehrerer anderer Mitgliedstaaten der Europ\\u00e4ischen Union besitzen. In dieses F\\u00fchrungszeugnis werden auch die Eintragungen aufgenommen, die im Strafregister des Herkunftslandes gespeichert sind.<\\/p>\\n<p><strong>F\\u00fchrungszeugnis f\\u00fcr Ehrenamtliche<\\/strong>\\n <br>\\n Wenn Sie f\\u00fcr Ihre ehrenamtliche T\\u00e4tigkeit bei einer gemeinn\\u00fctzigen oder vergleichbaren Einrichtung ein F\\u00fchrungszeugnis brauchen, dann bekommen Sie dieses grunds\\u00e4tzlich geb\\u00fchrenfrei.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Polizeiliches F\\u00fchrungszeugnis, Erweitertes F\\u00fchrungszeugnis, Europ\\u00e4isches F\\u00fchrungszeugnis, F\\u00fchrungszeugnis f\\u00fcr private Zwecke, F\\u00fchrungszeugnis zur Vorlage bei Beh\\u00f6rden\",\"translated\":true,\"hash\":\"\",\"id\":\"1063565\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102523\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102523\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102523\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102524\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102524\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102524\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"102526\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102526\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1063565\\/locations\\/102526\",\"slots\":\"0\",\"external