INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064115','Niederlassungserlaubnis für Familienangehörige von Deutschen','https://service.berlin.de/dienstleistung/1064115/','Sonstiges','{\"id\":\"1064115\",\"name\":\"Niederlassungserlaubnis f\\u00fcr Familienangeh\\u00f6rige von Deutschen\",\"description\":\"<p>Die Niederlassungserlaubnis ist ein unbefristeter Aufenthaltstitel, mit dem Sie ohne zeitliche oder \\u00f6rtliche Einschr\\u00e4nkung in Deutschland leben und arbeiten k\\u00f6nnen.<\\/p>\\n<p><span>Ehegatt*innen und eingetragene Lebenspartner*innen, Kinder und Elternteile von Deutschen k\\u00f6nnen nach drei Jahren Aufenthalt eine Niederlassungserlaubnis erhalten, wenn die famili\\u00e4re Lebensgemeinschaft mit der deutschen Person fortbesteht.<\\/span><\\/p>\\n<p><strong>Antragstellung und Termin<\\/strong><\\/p>\\n<p>Bitte reichen Sie das <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\" target=\\\"_blank\\\">Antragsformular<\\/a> sowie die ben\\u00f6tigten Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/niederlassungserlaubnis\\/index\\\" target=\\\"_blank\\\">online<\\/a> oder per Post ein. Nach Absenden Ihres Online-Antrags k\\u00f6nnen Sie ein ausgef\\u00fclltes Dokument als PDF f\\u00fcr Ihre Unterlagen herunterladen. In dem Dokument wird Ihnen die Antragstellung und die Erlaubnis\\/ Fortgeltung Ihres bisherigen Aufenthalts best\\u00e4tigt. Nach Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin zur pers\\u00f6nlichen Vorsprache.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufenthaltsberechtigung, Daueraufenthalt, Visumsverl\\u00e