INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064121','Änderung der Adresse in Fahrzeugpapieren','https://service.berlin.de/dienstleistung/1064121/','Sonstiges','{\"id\":\"1064121\",\"name\":\"\\u00c4nderung der Adresse in Fahrzeugpapieren\",\"description\":\"<p>Wenn Sie umziehen, m\\u00fcssen Sie sich so schnell wie m\\u00f6glich anmelden \\/ ummelden. Der Gesetzgeber sieht 14 Tage vor.<br><br>\\n Haben Sie Ihre Wohnadresse bereits umgemeldet, Ihre Fahrzeugpapiere jedoch noch nicht, dann k\\u00f6nnen Sie das jetzt ganz bequem von zu Hause aus erledigen.<\\/p>\\n<p>Wenn Sie Ihren neuen Wohnsitz in einem der B\\u00fcrgerb\\u00fcros anmelden, k\\u00f6nnen Sie auch <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmeldung-mit-aenderung-der-fahrzeugpapiere\\/10224132\\/n0\\/\\\" target=\\\"_blank\\\">gleichzeitig Ihre Fahrzeugpapiere berichtigen<\\/a> lassen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Fahrzeugschein\",\"translated\":true,\"hash\":\"\",\"id\":\"1064121\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064121\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064121\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036011011000\",\"public\":true,\"links\"