INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064278','Ersatz der Zulassungsbescheinigung Teil II nach Verlust','https://service.berlin.de/dienstleistung/1064278/','Sonstiges','{\"id\":\"1064278\",\"name\":\"Ersatz der Zulassungsbescheinigung Teil II nach Verlust\",\"description\":\"<p>Die neue Zulassungsbescheinigung Teil II (Fahrzeugbrief) darf erst nach Ablauf der sogenannten Aufbietung beim Kraftfahrt-Bundesamt in Flensburg ausgestellt und ausgeh\\u00e4ndigt oder per Einschreiben zugesandt werden. Die Freigabe durch das Kraftfahrt-Bundesamt dauert in der Regel drei bis vier Wochen.<\\/p>\\n<p>F\\u00fcr die <strong>Beantragung<\\/strong> und pers\\u00f6nliche <strong>Abholung<\\/strong> vereinbaren Sie bitte einen <a href=\\\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/terminvereinbarung.html#\\/services\\/1064278\\/locations\\/10412449\\\" target=\\\"\\\">Termin<\\/a>.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Verlust Zulassungsbescheinigung Teil II, Verlust Fahrzeugbrief, Verlust Fahrzeugpapiere, Diebstahl Zulassungsbescheinigung Teil II, Diebstahl Fahrzeugbrief, Diebstahl Fahrzeugpapiere, Fahrzeugpapiere verloren\\/gestohlen, Ersatzfahrzeugbrief, Kraftfahrzeugbrief, KfZ, Zulassung\",\"translated\":true,\"hash\":\"\",\"id\":\"1064278\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10412449\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064278\\/locations\\/10412449\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/termin