INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064305','Fahrzeug abmelden','https://service.berlin.de/dienstleistung/1064305/','Sonstiges','{\"id\":\"1064305\",\"name\":\"Fahrzeug abmelden\",\"description\":\"<ul><li>Sie k\\u00f6nnen auch ein Fahrzeug mit einem ausw\\u00e4rtigen Kennzeichen abmelden (Eine Reservierung eines ausw\\u00e4rtigen Kennzeichens ist nicht m\\u00f6glich). Dazu m\\u00fcssen Sie die gleichen Unterlagen wie bei der Abmeldung eines M\\u00fcnchner Fahrzeugs mitbringen.<\\/li><li>Es besteht die M\\u00f6glichkeit, das bestehende Kennzeichen f\\u00fcr eine sp\\u00e4tere Wiederinbetriebnahme (das selbe Fahrzeug auf den selben Halter), als \\u201cVerbleibskennzeichen\\u201c f\\u00fcr 12 Monate zu reservieren. Die Geb\\u00fchr von 2,60 Euro f\\u00fcr die Reservierung wird bei der Au\\u00dferbetriebsetzung mit verrechnet.<br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Fahrzeug abmelden, Au\\u00dferbetriebsetzung, Fahrzeug stilllegen, Abmeldung Fahrzeug, Stilllegung, Auto, Fahrzeugabmeldung, Entstempelung, KFZ\",\"translated\":true,\"hash\":\"\",\"id\":\"1064305\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102101\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064305\\/locations\\/102101\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064305\\/locations\\/102101\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036008003000\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fahrzeug online au\\u00dfer Betrieb setzen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/10173178\\/n0\\/\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Fahrzeug online au\\u00dfer Betrieb setzen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/10173178\\/n0\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[1064305],\"fees\":\"<ul>\\n <li>bei M\\u00fcnchner und ausw\\u00e4rtigen Kennzeichen: 17,40 Euro<\\/li>\\n <li>Reservierung der Kennzeichen: 2,60 Euro\\n  <br><\\/li>\\n<\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064308','Erneute Anmeldung eines Fahrzeugs','https://service.berlin.de/dienstleistung/1064308/','Sonstiges','{\"id\":\"1064308\",\"name\":\"Erneute Anmeldung eines Fahrzeugs\",\"description\":\"<p>Mit Ihrer Online-Ausweis-Funktion k\\u00f6nnen Sie ganz bequem von zu Hause aus Ihr Fahrzeug wiederzulassen.\\u200b<\\/p>\\n<ul>\\n <li>Wenn Sie bereits ein Euro-Kennzeichen haben (blaues Band am linken Rand des Kennzeichens), k\\u00f6nnen Sie das \\u201ealte Kennzeichen\\u201c wieder verwenden.<\\/li>\\n <li><strong>Fahrzeuge mit einer Betriebserlaubnis<\\/strong>(beispielsweise Leichtkraftr\\u00e4der, Anh\\u00e4nger f\\u00fcr Sportzwecke, Anh\\u00e4nger f\\u00fcr Arbeitsmaschinen) <strong>k\\u00f6nnen ausschlie\\u00dflich in der KFZ-Zulassungsbeh\\u00f6rde zugelassen oder umgeschrieben werden<\\/strong>. Daf\\u00fcr brauchen Sie einen Termin.<\\/li>\\n<\\/ul>\\n<p>Haben Sie Ihre PIN f\\u00fcr Ihre Online-Ausweis-Funktion nicht mehr, so k\\u00f6nnen Sie sich in <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/nachtraegliches-einschalten-eid-funktion-oder-aenderung-der-pin\\/10225119\\/n0\\/\\\">jedem B\\u00fcrgerb\\u00fcro eine neue PIN<\\/a> vergeben lassen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Wiederinbetriebnahme eines Fahrzeugs, Stillgelegtes Fahrzeug anmelden, Fahrzeug wieder in Betrieb nehmen, Wiederzulassung, Wiederanmeldung, Wiederanmeldung Anh\\u00e4nger, Wohnanh\\u00e4nger wieder anmelden, Wohnmobil wieder anmelden, Motorrad wieder anmelden, Wiederanmeldung Motorrad, Kfzzulassung\",\"translated\":true,\"hash\":\"\",\"id\":\"1064308\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"l