INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064323','Kurzzeitkennzeichen','https://service.berlin.de/dienstleistung/1064323/','Sonstiges','{\"id\":\"1064323\",\"name\":\"Kurzzeitkennzeichen\",\"description\":\"<p>In M\\u00fcnchen erhalten Sie das Kurzzeitkennzeichen ausschlie\\u00dflich an der Eichst\\u00e4tter Stra\\u00dfe 2.<\\/p>\\n<p>\\u200b <span>Hat das Fahrzeug keine g\\u00fcltige HU oder Sicherheitspr\\u00fcfung, darf nur zu einer Untersuchungsstelle im Bezirk der Zulassungsbeh\\u00f6rde, die f\\u00fcr den Standort des Fahrzeuges zust\\u00e4ndig ist oder in einem angrenzenden Bezirk gefahren werden. Bei bestandener HU ist eine Fahrt im gesamten Bundesgebiet m\\u00f6glich.<\\/span><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"\\u00dcberf\\u00fchrungskennzeichen, Fahrzeug \\u00fcberf\\u00fchren, \\u00dcberf\\u00fchrungsfahrt, Kurzkennzeichen, Fahrzeug\\u00fcberf\\u00fchrung\",\"translated\":true,\"hash\":\"\",\"id\":\"1064323\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064323\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064323\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036036000000\",\"public\":true,\"links\":[{\"name\":\"Vollmacht mit SEPA Mandat\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Vollmacht mit SEPA Mandat\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1064323,1064121,1064354,1064308,10387573,1064275,1080502,1063425,10387564,1064342,1071959,1064311,1064130,1064333,1063424,1064314,1064271,10391602],\"fees\":\"<p>ab 13,10 Euro zuz\\u00fcglich Kennzeichenschilder<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064333','Saisonkennzeichen','https://service.berlin.de/dienstleistung/1064333/','Sonstiges','{\"id\":\"1064333\",\"name\":\"Saisonkennzeichen\",\"description\":\"<p>\\u200b Das Fahrzeug darf nur innerhalb der auf dem Kennzeichen angegebenen Zeit betrieben oder auf \\u00f6ffentlichen Stra\\u00dfen und Pl\\u00e4tzen abgestellt werden. Dieser Zeitraum kann zwischen zwei und elf Monaten betragen.<\\/p>\\n<p>Der gew\\u00fcnschte Zeitraum wird auf das Kennzeichen gepr\\u00e4gt und in die Zulassungsbescheinigung Teil I (Fahrzeugschein) sowie Zulassungsbescheinigung Teil II (Fahrzeugbrief) eingetragen. Die Zulassung gilt jeweils f\\u00fcr volle Monate und beginnt ab dem ersten Tag eines Monats und endet am letzten Tag eines Monats.<\\/p>\\n<p>\\u200b Sie haben die M\\u00f6glichkeit, ein Wunschkennzeichen zu reservieren. Sie haben auch die M\\u00f6glichkeit, ein Oldtimer- mit einem Saisonkennzeichen zu kombinieren. Das Kennzeichen darf maximal zwei Buchstaben und drei Zahlen beziehungsweise einen Buchstaben und vier Zahlen enthalten, welche Sie \\u00fcber das Internet reservieren k\\u00f6nnen. Eventuell vorhandene l\\u00e4ngere Kombinationen m\\u00fcssen geb\\u00fchrenpflichtig umgekennzeichnet werden.<\\/p>\\n<p>Mit Ihrer Online-Ausweis-Funktion k\\u00f6nnen Sie ganz bequem von zu Hause aus bei der Online - Zulassung Ihr Saisonkennzeichen gleich mit beantragen.<\\/p>\\n<p>Haben Sie Ihre PIN f\\u00fcr Ihre Online-Ausweis-Funktion nicht mehr, so k\\u00f6nnen Sie sich in <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/nachtraegliches-einschalten-eid-funktion-oder-aenderung-der-pin\\/10225119\\/n0\\/\\\">jedem B\\u00fcrgerb\\u00fcro eine neue PIN<\\/a> vergeben lassen, oder <a href=\\\"https:\\/\\/www.personalausweisportal.de\\/SharedDocs\\/faqs\\/Webs\\/PA\\/DE\\/Haeufige-Fragen\\/6_online-Ausweisfunktion\\/online-ausweisfunktion-liste.html\\\">Online beantragen<\\/a>.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Saisonzulassung, Saisonzulassung f\\u00fcr Motorrad, Saisonzulassung f\\u00fcr PKW, LKW, Bus, Wohnmobil, Saisonzulassung f\\u00fcr Anh\\u00e4nger, Wohnanh\\u00e4nger, Kurzkennzeichen, Saisonschilder\",\"translated\":true,\"hash\":\"\",\"id\":\"1064333\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064333\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064333\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036030069000\",\"public\":true,\"links\":[{\"name\":\"Termin vereinbaren\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/terminvereinbarung.html#\\/services\\/1064333\\/locations\\/10308013\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Leasingfahrzeug anmelden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1091603\\/n0\\/\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Ko