INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064345','Rotes Dauerkennzeichen für Oldtimer beantragen/ändern','https://service.berlin.de/dienstleistung/1064345/','Sonstiges','{\"id\":\"1064345\",\"name\":\"Rotes Dauerkennzeichen f\\u00fcr Oldtimer beantragen\\/\\u00e4ndern\",\"description\":\"<p>Damit d\\u00fcrfen (bei begr\\u00fcndetem Bedarf) folgende Fahrten durchgef\\u00fchrt werden:<\\/p>\\n<ul>\\n <li>Teilnahme an Oldtimerveranstaltungen, die der Pflege des kraftfahrzeugtechnischen Kulturgutes dienen<\\/li>\\n <li>An- und Abfahrten zu den Oldtimerveranstaltungen<\\/li>\\n <li>Probe- und \\u00dcberf\\u00fchrungsfahrten<\\/li>\\n <li>Fahrten zum Zwecke der Reparatur oder Wartung<\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Rotes Oldtimerkennzeichen, Wechselkennzeichen f\\u00fcr Oldtimer\",\"translated\":true,\"hash\":\"\",\"id\":\"1064345\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10416\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064345\\/locations\\/10416\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064345\\/locations\\/10416\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036035000000\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"descriptio