INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064354','Eintrag technischer Änderungen in Fahrzeugpapiere','https://service.berlin.de/dienstleistung/1064354/','Sonstiges','{\"id\":\"1064354\",\"name\":\"Eintrag technischer \\u00c4nderungen in Fahrzeugpapiere\",\"description\":\"<p>Einige Beispiele f\\u00fcr technische \\u00c4nderungen sind:<\\/p>\\n<ul>\\n <li>Einbau Katalysator oder Partikelminderungssystem<\\/li>\\n <li>\\u00c4nderungen der Fahrzeugklasse<\\/li>\\n <li>\\u00c4nderung von Hubraum oder Leistung<\\/li>\\n <li>Erh\\u00f6hung\\/Verringerung der durch die Bauart bestimmten H\\u00f6chstgeschwindigkeit<\\/li>\\n <li>\\u00c4nderung der zul\\u00e4ssigen Achslasten, des Gesamtgewichts, der Nutzlast, der Sattellast, der Aufliegelast, der Anh\\u00e4ngelast<\\/li>\\n<\\/ul>\\n<p><strong>Der Einbau eines Partikelminderungssystem hat Einfluss auf die Schadstoffklasse und auf die Berechtigung in sogenannte Umweltzonen einzufahren.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Nachr\\u00fcstung Partikelminderungssystem, Ru\\u00dfpartikelfilter, Einbau Abgasaufr\\u00fcstsystem, Partikelfilter, Einbau Abgasreinigunssystem, Kfz\",\"translated\":true,\"hash\":\"\",\"id\":\"1064354\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064354\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064354\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036008014002\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1064354,1064121,1064308,10387573,1064275,1064314,1063424,1064333,1064323,1064130,1064271,1064342,10391602,1063425,10387564,1071959,1064311,1080502],\"fees\":\"<p>ab 11,70 Euro<br>\\n bei gleichzeitigem Umtausch der Fahrzeugpapiere in die neue Zulassungsbescheinigung Teil I und Teil II: 25,80 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064361','Verlängerung befristeter Führerschein-Klassen','https://service.berlin.de/dienstleistung/1064361/','Sonstiges','{\"id\":\"1064361\",\"name\":\"Verl\\u00e4ngerung befristeter F\\u00fchrerschein-Klassen\",\"description\":\"<p>Die Fahrerlaubnisklassen f\\u00fcr Lkw und Bus werden seit Einf\\u00fchrung der neuen Fahrerlaubnisklassen zum 1.1.1999 nur noch befristet erteilt. Die Verl\\u00e4ngerung der Geltungsdauer m\\u00fcssen Sie bei der \\u00f6rtlich zust\\u00e4ndigen Fahrerlaubnisbeh\\u00f6rde oder der Gemeinde beantragen. F\\u00fcr die Verl\\u00e4ngerung ist keine Fahrerlaubnispr\\u00fcfung erforderlich. Die Fahrerlaubnisbeh\\u00f6rde pr\\u00fcft aber Ihre k\\u00f6rperliche Eignung. Mit der Verl\\u00e4ngerung der Fahrerlaubnis wird ein neuer F\\u00fchrerschein ausgestellt.<\\/p><p>Die Fahrerlaubnis der Klassen C1, C1E, C, CE, D1, D1E, D und DE wird jeweils l\\u00e4ngstens f\\u00fcr f\\u00fcnf Jahre erteilt oder verl\\u00e4ngert. <br><\\/p><p><br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Verl\\u00e4ngerung befristeter Fahrerlaubnis-Klassen, Verl\\u00e4ngerung C-Klasse, Lastwagenf\\u00fchrerschein, Verl\\u00e4ngerung der Fahrerlaubnis f\\u00fcr Busse und LKW, Verl\\u00e4ngerung D-Klasse, Busf\\u00fchrerschein, Busf\\u00fchrerschein verl\\u00e4ngern, LKW-F\\u00fchrerschein verl\\u00e4ngern\",\"translated\":true,\"hash\":\"\",\"id\":\"1064361\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308175\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064361\\/locations\\/10308175\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064361\\/locations\\/10308175\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108048020000\",\"public\":true,\"links\":[{\"name\":\"Bescheinigung augen\\u00e4rztliche Untersuchung 2.2\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-augenaerztliche-Untersuchung\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Informationen zum biometrischen Passfoto\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Fotomustertafel-300dpi-1.pdf\",\"description\":false},{\"name\":\"Bescheinigung \\u00fcber gesundheitliche Eignung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung--ber--rztliche-Untersuchungpdf.pdf\",\"description\":false},{\"name\":\"Bescheinigung augen\\u00e4rztliche Untersuchung 2.1\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-aerztliche-Untersuchung-Augen-Nr.-2.1.pdf\",\"description\":false},{\"name\":\"Auskunft aus dem Berufskraftfahrerqualifikationsregister (BQR)\",\"link\":\"https:\\/\\/www.kba.de\\/DE\\/Themen\\/ZentraleRegister\\/BQR\\/Auskunft\\/bqr_auskunft_node.html\",\"description\":false}],\"forms\":[{\"name\":\"Bescheinigung augen\\u00e4rztliche Untersuchung 2