INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064371','Parkausweis – Hauptbahnhofviertel','https://service.berlin.de/dienstleistung/1064371/','Sonstiges','{\"id\":\"1064371\",\"name\":\"Parkausweis \\u2013 Hauptbahnhofviertel\",\"description\":\"<p><strong><span>Neuantrag<\\/span><\\/strong><\\/p>\\n<p><span>Sie sind in das Parklizenzgebiet \\u201eHauptbahnhof\\u201c gezogen oder haben ein neues Fahrzeug bekommen? Dann k\\u00f6nnen Sie einen Bewohnerparkausweis neu beantragen. Selbst wenn mehrere Fahrzeuge auf Sie zugelassen sind, kann nur ein Parkausweis pro Bewohner*in erteilt werden. In den Ausweis k\\u00f6nnen aber bis zu drei Fahrzeuge eingetragen werden.<\\/span><\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong><\\/p>\\n<p>In der Regel erhalten Sie etwa 6 Wochen bevor der Parkausweis abl\\u00e4uft ein Erinnerungsschreiben. Wenn Sie den Parkausweis zu unver\\u00e4nderten Bedingungen (selbes Kennzeichen und Adresse) haben m\\u00f6chten, brauchen in diesem Fall keinen neuen Antrag zu stellen. Sie m\\u00fcssen nur die Geb\\u00fchr \\u00fcberweisen, die im Erinnerungsschreiben angegeben ist. Falls Sie kein Erinnerungsschreiben erhalten haben, bitten wir Sie rechtzeitig einen neuen Antrag zu stellen.<\\/p>\\n<p>\\u200b <span>Bitte beachten Sie, dass wir Ihnen auch bei einer pers\\u00f6nlichen Vorsprache den Parkausweis nicht mitgeben k\\u00f6nnen<\\/span><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Bewohnerparken, Parkwapperl, Parkausweis, Parkausweis verloren, Verlust Parkausweis, Parkausweis verl\\u00e4ngern, Parkausweis umschreiben, Kennzeichen\\u00e4nderung Parkausweis, Parklizenz\",\"translated\":true,\"hash\":\"\",\"id\":\"1064371\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064371\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064371\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108010000000\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Haltererkl\\u00e4rung Fahrzeug\\u00fcberlassung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Haltererkl\\u00e4rung Fahrzeug\\u00fcberlassung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1064371],\"fees\":\"<p>12 Monate g\\u00fcltig: 30 Euro<br>24 Monate g\\u00fcltig: 60 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1064374','Rotes Dauerkennzeichen für Handel, Werkstätten und Hersteller','https://service.berlin.de/dienstleistung/1064374/','Sonstiges','{\"id\":\"1064374\",\"name\":\"Rotes Dauerkennzeichen f\\u00fcr Handel, Werkst\\u00e4tten und Hersteller\",\"description\":\"<p>Damit d\\u00fcrfen folgende Fahrten durchgef\\u00fchrt werden:<\\/p>\\n<ul>\\n <li>Probefahrten, um die Gebrauchsf\\u00e4higkeit des Fahrzeugs festzustellen<\\/li>\\n <li>Fahrten, die zur technischen Pr\\u00fcfung durch amtlich anerkannte Sachverst\\u00e4ndige oder Pr\\u00fcfingenieure notwendig sind<\\/li>\\n <li>\\u00dcberf\\u00fchrungsfahrten (nur innerhalb Deutschland)<\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Rotes Kennzeichen\",\"translated\":true,\"hash\":\"\",\"id\":\"1064374\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10416\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064374\\/locations\\/10416\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1064374\\/locations\\/10416\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036009069010\",\"public\":true,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalte