INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1071907','Einbürgerung','https://service.berlin.de/dienstleistung/1071907/','Sonstiges','{\"id\":\"1071907\",\"name\":\"Einb\\u00fcrgerung\",\"description\":\"<p>Am 27. Juni 2024 ist das Gesetz zur Modernisierung des Staatsangeh\\u00f6rigkeitsrechts in Kraft getreten. Mit der Gesetzes\\u00e4nderung wird die generelle Hinnahme von Mehrstaatigkeit erm\\u00f6glicht und die Aufenthaltszeit auf f\\u00fcnf Jahre verk\\u00fcrzt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Einb\\u00fcrgerungsanspruch, Einb\\u00fcrgerung, Anspruchseinb\\u00fcrgerung, Deutsche Staatsangeh\\u00f6rigkeit\",\"translated\":true,\"hash\":\"\",\"id\":\"1071907\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10471\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1071907\\/locations\\/10471\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1071907\\/locations\\/10471\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99099002000000\",\"public\":true,\"links\":[{\"name\":\"Antrag einreichen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/einbuergerung_kontakt\\/index\",\"description\":false},{\"name\":\"Unterlagen zu meinem Antrag nachreichen\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/einbuergerung_kontakt_n