INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1071944','Umschreibung EU/EWR-Führerschein','https://service.berlin.de/dienstleistung/1071944/','Sonstiges','{\"id\":\"1071944\",\"name\":\"Umschreibung EU\\/EWR-F\\u00fchrerschein\",\"description\":\"<p><strong>Umzuschreiben sind:<\\/strong><\\/p>\\n<ul>\\n <li>befristete F\\u00fchrerscheine ohne die Klassen C, C1, C1E, CE, D, D1, D1E und DE, wenn die Befristung abl\\u00e4uft oder bereits abgelaufen ist.<\\/li>\\n <li>befristete F\\u00fchrerscheine mit den Klassen C, C1, C1E, CE, D, D1, D1E und DE, wenn die befristete G\\u00fcltigkeit einer dieser Klassen abl\\u00e4uft.<\\/li>\\n<\\/ul>\\n<p>\\n <br>\\n <strong>Hinweise zur Aush\\u00e4ndigung\\/ Abholung:<\\/strong>\\n<\\/p>\\n<ul>\\n <li>Der ausl\\u00e4ndische F\\u00fchrerschein muss m\\u00f6glicherweise polizeilich auf Echtheit \\u00fcberpr\\u00fcft werden. Diese \\u00dcberpr\\u00fcfung dauert zwei bis drei Wochen. W\\u00e4hrend dieser Zeit m\\u00fcssen Sie Ihren F\\u00fchrerschein abgeben. Ob die Abgabe erforderlich ist, wird w\\u00e4hrend der Antragsbearbeitung gepr\\u00fcft.\\n  <br><\\/li>\\n <li>Der deutsche Kartenf\\u00fchrerschein wird zentral durch die Bundesdruckerei in Berlin hergestellt. Sobald er uns vorliegt, werden Sie schriftlich benachrichtigt. Dann k\\u00f6nnen Sie den F\\u00fchrerschein pers\\u00f6nlich mit Personalausweis oder Reisepass abholen.<\\/li>\\n <li>Ihren ausl\\u00e4ndischen F\\u00fchrerschein m\\u00fcssen Sie abgeben, wenn Sie den deutschen Kartenf\\u00fchrerschein bekommen.<\\/li>\\n<\\/ul>\\n<p>\\n <br>\\n Zum 19. Januar 2013 wurde ein neuer EU-F\\u00fchrerschein eingef\\u00fchrt. Einen Link zu den wichtigsten \\u00c4nderungen und zu einer \\u00dcbersicht der neuen Fahrerlaubnisklassen finden Sie im Feld \\u201eWeitere Informationen\\u201c.\\n<\\/p>\\n<p><strong>Sie k\\u00f6nnen die Umschreibung pers\\u00f6nlich oder <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/umschreibung_ausl_fuehrerschein\\/index\\\" target=\\\"_blank\\\">online<\\/a> beantragen.<\\/strong>\\n <br>\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"F\\u00fchrerschein, Umschreibung EU F\\u00fchrerschein, Ausl\\u00e4ndischer F\\u00fchrerschein, F\\u00fchrerschein umschreiben\",\"translated\":true,\"hash\":\"\",\"id\":\"1071944\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308174\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1071944\\/locations\\/10308174\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1071944\\/locations\\/10308174\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108047050001\",\"public\":true,\"links\":[{\"name\":\"Bescheinigung \\u00e4rztliche Untersuchung des Sehverm\\u00f6gens (Anlage 6 Nr. 2.2)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-augenaerztliche-Untersuchung\",\"description\":false},{\"name\":\"Bescheinigung \\u00fcber gesundheitliche Eignung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung--ber--rztliche-Untersuchungpdf.pdf\",\"description\":false},{\"name\":\"Bescheinigung \\u00e4rztliche Untersuchung des Sehverm\\u00f6gens (Anlage 6 Nr. 2.1)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-aerztliche-Untersuchung-Augen-Nr.-2.1.pdf\",\"description\":false},{\"name\":\"F\\u00fchrerscheinklassen\",\"link\":\"https:\\/\\/www.kba.de\\/DE\\/Themen\\/ZentraleRegister\\/ZFER\\/FE_Klassen\\/fe_klassen_node.html\",\"description\":false},{\"name\":\"Notfallmedizin\",\"link\":\"https:\\/\\/www.notfallmedizin.de\\/\",\"description\":false}],\"forms\":[{\"name\":\"Bescheinigung \\u00e4rztliche Untersuchung des Sehverm\\u00f6gens (Anlage 6 Nr. 2.2)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-augenaerztliche-Untersuchung\",\"description\":false},{\"name\":\"Bescheinigung \\u00fcber gesundheitliche Eignung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung--ber--rztliche-Untersuchungpdf.pdf\",\"description\":false},{\"name\":\"Bescheinigung \\u00e4rztliche Untersuchung des Sehverm\\u00f6gens (Anlage 6 Nr. 2.1)\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Fuehrerschein\\/Bescheinigung-aerztliche-Untersuchung-Augen-Nr.-2.1.pdf\",\"description\":false},{\"name\":\"F\\u00fchrerscheinklassen\",\"link\":\"https:\\/\\/www.kba.de\\/DE\\/Themen\\/ZentraleRegister\\/ZFER\\/FE_Klassen\\/fe_klassen_node.html\",\"description\":false},{\"name\":\"Notfallmedizin\",\"link\":\"https:\\/\\/www.notfallmedizin.de\\/\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[1071944],\"fees\":\"<ul>\\n <li>ohne Festsetzung einer Probezeit: 37,50 Euro<\\/li>\\n <li>mit Festsetzung einer Probezeit: 38,30 Euro<\\/li>\\n <li>bei Umschreibung befristeter Klassen: 45,10 Euro<\\/li>\\n<\\/ul>\"}',NULL,NULL);
