INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072009','Bundesweiter Parkausweis für Behinderte','https://service.berlin.de/dienstleistung/1072009/','Sonstiges','{\"id\":\"1072009\",\"name\":\"Bundesweiter Parkausweis f\\u00fcr Behinderte\",\"description\":\"<p><strong><span>Neuantrag<\\/span><\\/strong><\\/p>\\n<p><span>Beeintr\\u00e4chtigte mit einem bestimmten Grad der Behinderung k\\u00f6nnen einen orangenen Parkausweis beantragen, mit welchem deutschlandweit verschiedene Parkerleichterungen verbunden sind. Der Parkausweis gilt allerdings nicht auf Schwerbehindertenparkpl\\u00e4tzen.<\\/span><\\/p>\\n<p><strong><span>Verl\\u00e4ngerung<\\/span><\\/strong><\\/p>\\n<p><span>Der Parkausweis gilt maximal 5 Jahre. Danach muss dieser neu beantragt werden.<\\/span><\\/p>\\n<p><span>Bitte beachten Sie, dass wir Ihnen auch bei einer pers\\u00f6nlichen Vorsprache den Parkausweis nicht mitgeben k\\u00f6nnen.<\\/span><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Parkausweis Deutschland, Behindertenparkausweis f\\u00fcr ganz Deutschland, Behindertenparken, oranger Parkausweis, Bundesweiter Parkausweis, Schwerbehindertenparkausweis\",\"translated\":true,\"hash\":\"\",\"id\":\"1072009\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072009\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072009\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108009000000\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Behindertenparkpl\\u00e4tze in M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063832\\/n0\\/\",\"description\":false},{\"name\":\"ZBFS Bayern\",\"link\":\"https:\\/\\/www.zbfs.bayern.de\\/\",\"description\":false},{\"name\":\"Internationales Transportforum\",\"link\":\"https:\\/\\/www.itf-oecd.org\\/member-countries\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Behindertenparkpl\\u00e4tze in M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063832\\/n0\\/\",\"description\":false},{\"name\":\"ZBFS Bayern\",\"link\":\"https:\\/\\/www.zbfs.bayern.de\\/\",\"description\":false},{\"name\":\"Internationales Transportforum\",\"link\":\"https:\\/\\/www.itf-oecd.org\\/member-countries\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072009],\"fees\":\"<p><span>Geb\\u00fchrenfrei<\\/span><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072012','EU-Parkausweis für Behinderte','https://service.berlin.de/dienstleistung/1072012/','Sonstiges','{\"id\":\"1072012\",\"name\":\"EU-Parkausweis f\\u00fcr Behinderte\",\"description\":\"<ul>\\n <li>Legen Sie den Parkausweis gut lesbar an der Windschutzscheibe im Fahrzeug aus.<\\/li>\\n <li>Der EU-einheitliche Parkausweis gilt in Deutschland, der EU und vielen weiteren L\\u00e4ndern. Eine Liste aller 52 Mitgliedsl\\u00e4nder erhalten Sie online beim Internationalen Transportforum (ITF).<\\/li>\\n <li>Der Parkausweis gilt maximal f\\u00fcnf Jahre. Danach m\\u00fcssen Sie ihn neu beantragen.<\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Internationaler Parkausweis, Behindertenparkausweis, Behindertenparken, Hellblau, Blaue Karte, EU-einheitlicher Parkausweis, Europaweiter Parkausweis, Schwerbehindertenparkausweis\",\"translated\":true,\"hash\":\"\",\"id\":\"1072012\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072012\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072012\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108009020000\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Behindertenparkpl\\u00e4tze in M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063832\\/n0\\/\",\"description\":false},{\"name\":\"ZBFS Bayern\",\"link\":\"https:\\/\\/www.zbfs.bayern.de\\/\",\"description\":false},{\"name\":\"Internationales Transportforum\",\"link\":\"https:\\/\\/www.itf-oecd.org\\/member-countries\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Behindertenparkpl\\u00e4tze in M\\u00fcnchen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/1063832\\/n0\\/\",\"description\":false},{\"name\":\"ZBFS Bayern\",\"link\":\"https:\\/\\/www.zbfs.bayern.de\\/\",\"description\":false},{\"name\":\"Internationales Transportforum\",\"link\":\"https:\\/\\/www.itf-oecd.org\\/member-countries\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":10,\"combinable\":[1072012],\"fees\":\"<p>\\nkostenfrei<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072015','Parkausweis für Handelsvertretungen','https://service.berlin.de/dienstleistung/1072015/','Sonstiges','{\"id\":\"1072015\",\"name\":\"Parkausweis f\\u00fcr Handelsvertretungen\",\"description\":\"<p><strong>Neuantrag<\\/strong><\\/p>\\n<p>Wenn Sie f\\u00fcr Ihre T\\u00e4tigkeit als Handelsvertreter*in ein Fahrzeug zum Transport schwerer Gegenst\\u00e4nde ben\\u00f6tigen, dann k\\u00f6nnen Sie eine Ausnahmegenehmigung beantragen. In den Parkausweis k\\u00f6nnen bis zu drei Fahrzeuge eingetragen werden.<\\/p>\\n<p>Bei Verwendung des Parkausweises muss ein <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Arbeitstaettennachweis.pdf\\\">Arbeitsst\\u00e4ttennachweis<\\/a> gut lesbar im Fahrzeug ausgelegt werden.<\\/p>\\n<p><strong>Umschreibung<\\/strong><\\/p>\\n<p>Sofern sich ein Fahrzeug, beziehungsweise Kennzeichen, \\u00e4ndert, kann eine Umschreibung des Parkausweises f\\u00fcr die Restlaufzeit beantragt werden.<\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong><\\/p>\\n<p>In der Regel erhalten Sie circa sechs Wochen vor Ablauf der Parklizenz ein Erinnerungsschreiben. Wenn Sie den Parkausweis f\\u00fcr die gleichen Kennzeichen verl\\u00e4ngern m\\u00f6chten, m\\u00fcssen Sie keinen neuen Antrag stellen. Sie m\\u00fcssen lediglich die Geb\\u00fchr \\u00fcberweisen, die in dem Erinnerungsschreiben angegeben ist.<\\/p>\\n<p>\\u00c4ndern sich die Kennzeichen f\\u00fcr den Parkausweis, bitten wir Sie, rechtzeitig einen neuen, vollst\\u00e4ndigen Antrag zu stellen. Eine automatische Verl\\u00e4ngerung ist in diesem Fall leider nicht m\\u00f6glich.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ausnahmegenehmigung f\\u00fcr Handelsvertreter, Parkerleichterung f\\u00fcr Handelsvertreter, Parkausweis f\\u00fcr Vertreter im Au\\u00dfendienst, Verlust Parkausweis, Parkausweis verloren, Parkausweis verl\\u00e4ngern\",\"translated\":true,\"hash\":\"\",\"id\":\"1072015\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072015\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072015\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108010000000\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Online Terminvereinbarung\",\"link\":\"https:\\/\\/www22.muenchen.de\\/kvue\\/termin\\/?cts=1072018\",\"description\":false},{\"name\":\"Muster Arbeitsst\\u00e4ttennachweis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Arbeitstaettennachweis.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Online Terminvereinbarung\",\"link\":\"https:\\/\\/www22.muenchen.de\\/kvue\\/termin\\/?cts=1072018\",\"description\":false},{\"name\":\"Muster Arbeitsst\\u00e4ttennachweis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Arbeitstaettennachweis.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072015],\"fees\":\"<ul><li><span>3 Monate g\\u00fcltig: 90 Euro<\\/span><\\/li><li><span>6 Monate g\\u00fcltig: 180 Euro<\\/span><\\/li><li><span>12 Monate g\\u00fcltig: 360 Euro<\\/span><\\/li><li><span>24 Monate g\\u00fcltig: 720 Euro<\\/span><\\/li><\\/ul><p>Bei Eintragung eines festen Kennzeichens f\\u00fcr rein batterieelektrische Fahrzeuge (Geb\\u00fchrenreduzierung):<\\/p><ul><li>12 Monate g\\u00fcltig: 30 Euro<br><\\/li><\\/ul><p><span>Wenn Sie <u>gleichzeitig<\\/u> mehrere Parkausweise beantragen, verringert sich die Geb\\u00fchr des zweiten Ausweises bzw. weiterer Ausweise um jeweils 15 Euro.<br> <br> Parkausweis f\\u00fcr die Restlaufzeit umschreiben: 10 Euro<\\/span><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072019','Parkausweis für Handwerksbetriebe','https://service.berlin.de/dienstleistung/1072019/','Sonstiges','{\"id\":\"1072019\",\"name\":\"Parkausweis f\\u00fcr Handwerksbetriebe\",\"description\":\"<p><strong>Neuantrag<\\/strong><\\/p>\\n<p>Wenn Sie als Handwerksbetrieb f\\u00fcr Ihre T\\u00e4tigkeit ein Transport- oder Werkstattfahrzeug ben\\u00f6tigen, k\\u00f6nnen Sie eine Ausnahmegenehmigung beantragen. In diese k\\u00f6nnen wir bis zu drei Fahrzeuge eintragen. Dasselbe Fahrzeug kann in mehrere Parkausweise eingetragen werden. Der Ausweis gilt immer nur f\\u00fcr das Fahrzeug, in welchem dieser beim Parken ausgelegt wird.<\\/p>\\n<p>Bei Verwendung des Parkausweises muss ein Arbeitsst\\u00e4ttennachweis gut lesbar im Fahrzeug ausgelegt werden (\\u201eMuster Arbeitsst\\u00e4ttennachweis\\u201c, siehe Links &amp; Downloads).<\\/p>\\n<p><strong>Umschreibung<\\/strong><\\/p>\\n<p>Wenn sich Ihre Fahrzeuge bzw. Kennzeichen \\u00e4ndern, kann eine Umschreibung des Parkausweises f\\u00fcr die Restlaufzeit beantragt werden<\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong><\\/p>\\n<p>In der Regel erhalten Sie circa sechs Wochen vor Ablauf der Parklizenz ein Erinnerungsschreiben. Wenn Sie den Parkausweis f\\u00fcr die gleichen Kennzeichen verl\\u00e4ngern m\\u00f6chten, m\\u00fcssen Sie keinen neuen Antrag stellen. Sie m\\u00fcssen lediglich die Geb\\u00fchr \\u00fcberweisen, die in dem Erinnerungsschreiben angegeben ist.<\\/p>\\n<p>\\u00c4ndern sich die Kennzeichen f\\u00fcr den Parkausweis, bitten wir Sie, rechtzeitig einen neuen, vollst\\u00e4ndigen Antrag zu stellen. Eine automatische Verl\\u00e4ngerung ist in diesem Fall leider nicht m\\u00f6glich.\\u200b\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ausnahmegenehmigung f\\u00fcr Handwerker, Parkerleichterung f\\u00fcr Handwerker, Parkerlaubnis, Ausnahme vom Haltverbot, Parklizenz, Verlust Parkausweis, Parkausweis verloren, Parkausweis verl\\u00e4ngern, Handwerkerausweis, Handwerkerparkausweis, Handwerkerparklizenz\",\"translated\":true,\"hash\":\"\",\"id\":\"1072019\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072019\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072019\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108010000000\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Muster Arbeitsst\\u00e4ttennachweis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Arbeitstaettennachweis.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Muster Arbeitsst\\u00e4ttennachweis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Arbeitstaettennachweis.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072019],\"fees\":\"<ul><li>3 Monate g\\u00fcltig: 90 Euro<\\/li><li>6 Monate g\\u00fcltig: 180 Euro<\\/li><li>12 Monate g\\u00fcltig: 360 Euro<\\/li><li>24 Monate g\\u00fcltig: 720 Euro<\\/li><\\/ul><p>Bei Eintragung eines festen Kennzeichens f\\u00fcr rein batterieelektrische Fahrzeuge (Geb\\u00fchrenreduzierung):<\\/p><ul><li>12 Monate g\\u00fcltig: 30 Euro<br><\\/li><\\/ul><p>Wenn Sie gleichzeitig mehrere Parkausweise beantragen, verringert sich die Geb\\u00fchr des zweiten Ausweises beziehungsweise weiterer Ausweise um jeweils 15 Euro.<\\/p><p>Parkausweis f\\u00fcr die Restlaufzeit umschreiben: 10 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072022','Parkausweis für gewerbliche Anlieger','https://service.berlin.de/dienstleistung/1072022/','Sonstiges','{\"id\":\"1072022\",\"name\":\"Parkausweis f\\u00fcr gewerbliche Anlieger\",\"description\":\"<p><strong>Neuantrag<\\/strong><\\/p>\\n<p>Wenn Sie mit einem Gesch\\u00e4ft, Gewerbe oder als Freiberufler*in einem Parklizenzgebiet ans\\u00e4ssig sind, k\\u00f6nnen Sie einen Parkausweis f\\u00fcr gewerbliche Anlieger*innen beantragen. Pro Gewerbe, bzw. Gesch\\u00e4ft, wird ein Gewerbeparkausweis ausgestellt. Dieser enth\\u00e4lt im Regelfall kein Kennzeichen und kann somit von verschiedenen Personen genutzt werden. Selbst\\u00e4ndige Freiberufler*innen (zum Beispiel \\u00c4rzt*innen oder Rechtsanw\\u00e4lt*innen) k\\u00f6nnen jeweils einen eigenen Parkausweis beantragen.\\n <br>\\n <br>\\n Bitte beachten Sie:\\n <br>\\n F\\u00fcr die Parklizenzgebiete \\u201eAltstadt\\u201c und \\u201eHauptbahnhof\\u201c k\\u00f6nnen generell keine Parkausweise f\\u00fcr gewerbliche Anlieger*innen ausgestellt werden.\\n <br>\\n <br><\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong><\\/p>\\n<p>Gewerbliche Anlieger*innen erhalten circa sechs Wochen, bevor der Parkausweis abl\\u00e4uft, ein Erinnerungsschreiben. Wenn Sie den Parkausweis zu unver\\u00e4nderten Bedingungen verl\\u00e4ngern m\\u00f6chten, m\\u00fcssen Sie keinen neuen Antrag stellen. Sie m\\u00fcssen lediglich die Geb\\u00fchr \\u00fcberweisen, die in dem Erinnerungsschreiben angegeben ist.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ausnahmegenehmigungen f\\u00fcr Gesch\\u00e4ft, Firma, Praxis oder Einrichtung im Lizenzgebiet, Parkausweis f\\u00fcr ans\\u00e4ssige Gesch\\u00e4fte und Betriebe, Verlust Parkausweis, Parkausweis verloren, Parkausweis verl\\u00e4ngern\",\"translated\":true,\"hash\":\"\",\"id\":\"1072022\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072022\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072022\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108003001001\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/verkehr-mobilitaet\\/parken.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/verkehr-mobilitaet\\/parken.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072022],\"fees\":\"<ul><li>12 Monate\\/ 360 Euro<\\/li><li>24 Monate\\/ 720 Euro<br><br><\\/li><\\/ul><p>Nachweislich gemeinn\\u00fctzige K\\u00f6rperschaften:<\\/p><ul><li>12 Monate\\/ 120 Euro<\\/li><\\/ul><p><br><\\/p><p>Eintragung eines festen Kennzeichens f\\u00fcr rein batterieelektrische Fahrzeuge (Geb\\u00fchrenreduzierung):<\\/p><ul><li>12 Monate\\/ 30 Euro<br><\\/li><\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072025','Parkausweis für Soziale Dienste','https://service.berlin.de/dienstleistung/1072025/','Sonstiges','{\"id\":\"1072025\",\"name\":\"Parkausweis f\\u00fcr Soziale Dienste\",\"description\":\"<p><strong>Neuantrag<\\/strong><\\/p>\\n<p>Wenn Sie f\\u00fcr Ihre T\\u00e4tigkeit in der Pflege hilfsbed\\u00fcrftiger Personen auf Parkerleichterungen angewiesen sind, um Ihr Fahrzeug am Einsatzort abzustellen, k\\u00f6nnen Sie eine Ausnahmegenehmigung beantragen. In diese k\\u00f6nnen wir bis zu drei Fahrzeuge eintragen. Dasselbe Fahrzeug kann in mehrere Parkausweise eingetragen werden. Der Ausweis gilt immer nur f\\u00fcr das Fahrzeug, in welchem dieser beim Parken ausgelegt wird.<\\/p>\\n<p><strong>Umschreibung<\\/strong><\\/p>\\n<p>Sofern sich Ihre Fahrzeuge bzw. Kennzeichen \\u00e4ndern, kann eine Umschreibung des Parkausweises f\\u00fcr die Restlaufzeit beantragt werden<\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong><\\/p>\\n<p>In der Regel erhalten Sie circa sechs Wochen vor Ablauf der Parklizenz ein Erinnerungsschreiben. Wenn Sie den Parkausweis f\\u00fcr die gleichen Kennzeichen verl\\u00e4ngern m\\u00f6chten, m\\u00fcssen Sie keinen neuen Antrag stellen. Sie m\\u00fcssen lediglich die Geb\\u00fchr \\u00fcberweisen, die in dem Erinnerungsschreiben angegeben ist.<\\/p>\\n<p>\\u00c4ndern sich die Kennzeichen f\\u00fcr den Parkausweis, bitten wir Sie, rechtzeitig einen neuen, vollst\\u00e4ndigen Antrag zu stellen. Eine automatische Verl\\u00e4ngerung ist in diesem Fall leider nicht m\\u00f6glich.\\u200b\\n <br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ausnahmegenehmigung f\\u00fcr soziale Dienste, Parkerleichterung f\\u00fcr im sozialen Dienst T\\u00e4tige, Parkerlaubnis f\\u00fcr Hilfs- und Pflegedienste, Verlust Parkausweis, Parkausweis verloren, Parkausweis verl\\u00e4ngern, Parklizenz, Geburtshelfer, Hebammen, Sonderparkerlaubnis, Sonderparkgenehmigung\",\"translated\":true,\"hash\":\"\",\"id\":\"1072025\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072025\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072025\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108010056002\",\"public\":true,\"links\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Verlust des Parkausweises\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072025],\"fees\":\"<ul>\\n <li>12 Monate g\\u00fcltig: 30 Euro<\\/li>\\n <li>24 Monate g\\u00fcltig: 60 Euro<\\/li>\\n <li>36 Monate g\\u00fcltig: 90 Euro<\\/li>\\n<\\/ul>\\n<p>Parkausweis f\\u00fcr die Restlaufzeit umschreiben: 10 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072037','Bewohnerparkausweis – Umschreibung','https://service.berlin.de/dienstleistung/1072037/','Sonstiges','{\"id\":\"1072037\",\"name\":\"Bewohnerparkausweis \\u2013 Umschreibung\",\"description\":\"<p><strong><span>Kennzeichenwechsel<\\/span><\\/strong><\\/p>\\n<p><span>Wenn Sie bereits eine Anwohnerparklizenz besitzen, sich aber das\\/ ein Fahrzeug bzw. Kennzeichen ge\\u00e4ndert hat, k\\u00f6nnen Sie die Umschreibung f\\u00fcr die Restlaufzeit der Lizenz beantragen.<\\/span><\\/p>\\n<p><span><span>Bitte beachten Sie, dass wir Ihnen auch bei einer pers\\u00f6nlichen Vorsprache den Parkausweis nicht direkt mitgeben k\\u00f6nnen.<\\/span><\\/span><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Parkausweis, Sonderparkgenehmigung, Sonderparkerlaubnis, Parklizenz, Anwohnerparklizenz, Kennzeichen\\u00e4nderung im Parkausweis, Parkwapperl, Parkraumlizenz\",\"translated\":true,\"hash\":\"\",\"id\":\"1072037\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072037\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072037\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108001000000\",\"public\":true,\"links\":[{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Nutzungserkl\\u00e4rung des Fahrzeughalters\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Nutzungserkl\\u00e4rung des Fahrzeughalters\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072037],\"fees\":\"<p><span>Bei Umschreibung f\\u00fcr die Restlaufzeit:<\\/span><\\/p><ul><li><span>10 Euro<\\/span><\\/li><\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072040','Bewohnerparkausweis – Neuantrag nach Verlust','https://service.berlin.de/dienstleistung/1072040/','Sonstiges','{\"id\":\"1072040\",\"name\":\"Bewohnerparkausweis \\u2013 Neuantrag nach Verlust\",\"description\":\"<p><span>Wenn Sie den Parkausweis verloren haben oder dieser gestohlen wurde, k\\u00f6nnen Sie einen Nachdruck f\\u00fcr die Restlaufzeit beantragen.<\\/span><br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Verlust Bewohnerparkausweis, Sonderparkgenehmigung, Sonderparkerlaubnis, Parklizenz verloren, Anwohnerparklizenz, Parkwapperl, Parkraumlizenz\",\"translated\":true,\"hash\":\"\",\"id\":\"1072040\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072040\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072040\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108001036001\",\"public\":true,\"links\":[{\"name\":\"Verlustanzeige Parkausweis online melden\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Verlustanzeige Parkausweis online melden\",\"link\":\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/verlustmeldung_parkausweis\\/index\",\"description\":false},{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1072040],\"fees\":\"<p>Nachdruck:<\\/p><ul><li>10 Euro<br><\\/li><\\/ul>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072043','Bewohnerparkausweis','https://service.berlin.de/dienstleistung/1072043/','Sonstiges','{\"id\":\"1072043\",\"name\":\"Bewohnerparkausweis\",\"description\":\"<p><strong>Neuantrag<\\/strong>\\n <br>\\n Sie sind in ein Parklizenzgebiet gezogen oder haben ein neues Fahrzeug bekommen? Dann k\\u00f6nnen Sie einen Bewohnerparkausweis neu beantragen. Sie k\\u00f6nnen nur einen Parkausweis pro Bewohner*in erhalten, auch wenn mehrere Fahrzeuge auf Sie zugelassen sind. In den Ausweis k\\u00f6nnen aber bis zu drei Fahrzeuge eingetragen werden.<\\/p>\\n<p><strong>Verl\\u00e4ngerung<\\/strong>\\n <br>\\n In der Regel erhalten Sie ungef\\u00e4hr sechs Wochen bevor der Parkausweis abl\\u00e4uft ein Erinnerungsschreiben. Wenn Sie den Parkausweis zu unver\\u00e4nderten Bedingungen (selbes Kennzeichen und Adresse) haben m\\u00f6chten, m\\u00fcssen Sie keinen neuen Antrag stellen. Sie m\\u00fcssen nur die Geb\\u00fchr \\u00fcberweisen, die im Erinnerungsschreiben angegeben ist. Wenn Sie kein Erinnerungsschreiben erhalten haben, bitten wir Sie rechtzeitig einen neuen Antrag zu stellen.<\\/p>\\n<p><strong>Ausnahmengenehmigung<\\/strong>\\n <br>\\n Sie wollen in einem Parklizenzgebiet parken, sind aber kein*e Anwohner*in? Dann k\\u00f6nnen Sie in bestimmten H\\u00e4rtef\\u00e4llen eine <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/kommunale-verkehrsuberwachung\\/10483725\\/\\\">Ausnahmegenehmigung zum Parken<\\/a> erhalten.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Parkausweis, Sonderparkgenehmigung, Sonderparkerlaubnis, Parklizenz, Anwohnerparklizenz, Parkwapperl, Parkraumlizenz, Umzug neues Parklizenzgebiet, Wechsel Parklizenzgebiet, Umzug anderes Parklizengebiet\",\"translated\":true,\"hash\":\"\",\"id\":\"1072043\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10427\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072043\\/locations\\/10427\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072043\\/locations\\/10427\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99108001000000\",\"public\":true,\"links\":[{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Haltererkl\\u00e4rung Fahrzeug\\u00fcberlassung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Parklizenzgebiet finden\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/parklizenzgebiete.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Haltererkl\\u00e4rung Fahrzeug\\u00fcberlassung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Parken\\/Haltererklaerung-Fahrzeugueberlassung.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\