INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072587','Europäischer Feuerwaffenpass','https://service.berlin.de/dienstleistung/1072587/','Sonstiges','{\"id\":\"1072587\",\"name\":\"Europ\\u00e4ischer Feuerwaffenpass\",\"description\":\"<p>F\\u00fcr Reisen in und durch Staaten der Europ\\u00e4ischen Union, bei denen Sie Waffen mitnehmen wollen, zum Beispiel bei Jagdreisen und zur Teilnahme an Schie\\u00dfwettbewerben, ben\\u00f6tigen Sie einen europ\\u00e4ischen Feuerwaffenpass. Dieser dient der Legitimation der Waffen innerhalb der EU. In verschiedenen EU-Staaten ist vor der Einreise die Eintragung der Zustimmung zu der Waffeneinfuhr in den Feuerwaffenpass einzuholen. In Zweifelsf\\u00e4llen erkundigen Sie sich bei der jeweiligen Botschaft oder dem jeweiligen Konsulat.<\\/p>\\n<p><strong>Der Feuerwaffenpass ersetzt im Bundesgebiet nicht die Waffenbesitzkarte. Wenn Sie eine oder mehrere Waffen von einem Staat in einen anderen dauerhaft bringen, ben\\u00f6tigen Sie eine Einfuhr- beziehungsweise Ausfuhrgenehmigung.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Jagdreisen, Schie\\u00dfwettbewerb, Pistole, Revolver, Schu\\u00dfwaffe, Schusswaffe, Kanone\",\"translated\":true,\"hash\":\"\",\"id\":\"1072587\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072587\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072587\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99089010000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antrag Feuerwaffenpass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-feuerwaffenpass.pdf\",\"description\":false},{\"name\":\"Hinweisblatt Feuerwaffenpass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Hinweisblatt_Europaeischer_Feuerwaffenpass.pdf\",\"description\":false},{\"name\":\"Antrag Mitnahmeerlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Antrag-Mitnahmeerlaubnis.pdf\",\"description\":false},{\"name\":\"Antrag Verbringungserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Antrag-Verbringungserlaubnis.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antrag Feuerwaffenpass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-feuerwaffenpass.pdf\",\"description\":false},{\"name\":\"Hinweisblatt Feuerwaffenpass\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Hinweisblatt_Europaeischer_Feuerwaffenpass.pdf\",\"description\":false},{\"name\":\"Antrag Mitnahmeerlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Antrag-Mitnahmeerlaubnis.pdf\",\"description\":false},{\"name\":\"Antrag Verbringungserlaubnis\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Antrag-Verbringungserlaubnis.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[1072587]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072617','Kleiner Waffenschein','https://service.berlin.de/dienstleistung/1072617/','Sonstiges','{\"id\":\"1072617\",\"name\":\"Kleiner Waffenschein\",\"description\":\"<p>\\nBei \\u00f6ffentlichen Veranstaltungen ist das F\\u00fchren von Waffen jeder Art generell verboten.<\\/p>\\n<p>\\nDer <strong>Kleine Waffenschein<\\/strong> wird auf Antrag nach \\u00dcberpr\\u00fcfung der waffenrechtlichen Zuverl\\u00e4ssigkeit - ohne Sachkunde und Bed\\u00fcrfnispr\\u00fcfung - unbefristet ausgestellt. Diese Erlaubnis berechtigt nicht zum F\\u00fchren von Waffen bei \\u00f6ffentlichen Veranstaltungen oder Versammlungen. Ebenso wenig beinhaltet er die Erlaubnis zum Schie\\u00dfen mit derartigen Waffen au\\u00dferhalb von Schie\\u00dfst\\u00e4tten oder des eigenen, befriedeten Hausrechtsbereiches, was sich auch auf das Schie\\u00dfen an Silvester bezieht. Beim F\\u00fchren einer Schusswaffe ist generell neben dem Waffenschein beziehungsweise Kleinen Waffenschein ein g\\u00fcltiger Personalausweis oder Reisepass mitzuf\\u00fchren.\\u00a0<br \\/>\\n<br \\/>\\n<strong>Hinweis:<\\/strong><br \\/>\\n<strong>Der Kleine Waffenschein ist nicht erforderlich zum F\\u00fchren eines Reizgas- oder Pfeffersprays.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Waffenschein, Signalwaffen, Gaswaffen, Schreckschusswaffen, Pistole, Revolver, Schu\\u00dfwaffe, Schusswaffe, Kanone, Waffen\",\"translated\":true,\"hash\":\"\",\"id\":\"1072617\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072617\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072617\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99089034001001\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antragsformular\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-kleiner-waffenschein.pdf\",\"description\":false},{\"name\":\"Hinweisblatt Kleiner Waffenschein\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Hinweisblatt_Kleiner_Waffenschein.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antragsformular\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-kleiner-waffenschein.pdf\",\"description\":false},{\"name\":\"Hinweisblatt Kleiner Waffenschein\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/Hinweisblatt_Kleiner_Waffenschein.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[1072617],\"fees\":\"<p>Aufgrund des hohen Bearbeitungsaufwandes, auch w\\u00e4hrend der Laufzeit des Kleinen Waffenscheines (Zuverl\\u00e4ssigkeits\\u00fcberpr\\u00fcfung alle drei Jahre), werden 150 Euro Bearbeitungsgeb\\u00fchr erhoben.<\\/p><p>Bei Ablehnung des Antrags wird eine Geb\\u00fchr von 100 Euro erhoben. <br><\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072627','Munition besitzen und erwerben','https://service.berlin.de/dienstleistung/1072627/','Sonstiges','{\"id\":\"1072627\",\"name\":\"Munition besitzen und erwerben\",\"description\":\"<p>F\\u00fcr den Erwerb und den Besitz von Munition brauchen Sie eine Erlaubnis. Eine Erwerbserlaubnis gilt gleichzeitig auch als Erlaubnis zum Besitz. <br><\\/p><p>Alle relevanten Unterlagen, die bei Antragstellung beizubringen sind, sind jeweils im Original und in einer gefertigten Kopie vorzulegen. M\\u00fcssen die Kopien durch die Beh\\u00f6rde angefertigt werden, wird pro Kopie eine Geb\\u00fchr von 0,50 Euro erhoben.<br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Munitionsbesitz, Munitionserwerb, Munitionserwerbschein, Waffen, Pistole, Revolver, Schu\\u00dfwaffe, Schusswaffe, Kanone\",\"translated\":true,\"hash\":\"\",\"id\":\"1072627\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072627\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072627\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99089018000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antragsformular\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-waffenbesitzkarte.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Antragsformular\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Jagen-Fisch-Waffen\\/Dokumente\\/antrag-waffenbesitzkarte.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":3,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[1072627]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072637','Sprengstoffrechtliche Erlaubnis beantragen und verlängern','https://service.berlin.de/dienstleistung/1072637/','Sonstiges','{\"id\":\"1072637\",\"name\":\"Sprengstoffrechtliche Erlaubnis beantragen und verl\\u00e4ngern\",\"description\":\"<p>Die Sprengstoffrechtliche Erlaubnis ist unter anderem notwendig zum Erwerb, Aufbewahren, Verwenden, \\u00dcberlassen, Verbringen, Transportieren und Vernichten von explosionsgef\\u00e4hrlichen Stoffen. Das sind in der Regel Schwarzpulver zum Vorderladerschie\\u00dfen, B\\u00f6llerpulver zum B\\u00f6llerschie\\u00dfen und Nitrozellulosepulver zum Wiederladen von Patronenh\\u00fclsen. Die Erlaubnis ist maximal auf f\\u00fcnf Jahre befristet und wird f\\u00fcr eine bestimmte H\\u00f6chstmenge an explosionsgef\\u00e4hrlichen Stoffen erteilt.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Sprengstoffbescheinigung, Waffen\",\"translated\":true,\"hash\":\"\",\"id\":\"1072637\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072637\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072637\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99089004000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnun