INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1072647','Waffenbesitzkarte beantragen','https://service.berlin.de/dienstleistung/1072647/','Sonstiges','{\"id\":\"1072647\",\"name\":\"Waffenbesitzkarte beantragen\",\"description\":\"<p>Sie m\\u00fcssen den Verlust einer Waffenbesitzkarte oder einer Waffe umgehend der zust\\u00e4ndigen Waffenbeh\\u00f6rde mitteilen. Die Waffenbesitzkarte berechtigt Sie, die darin eingetragene Waffe zu benutzen, sie innerhalb Ihres befriedeten Besitztums zu f\\u00fchren und sie beispielsweise zum Schie\\u00dfstand oder zur Reparatur zu einem B\\u00fcchsenmacher zu transportieren. Beim Transport darf die Waffe nicht zugriffsbereit und nicht geladen sein. Waffe und Munition sind getrennt in verschlossenen Beh\\u00e4ltnissen zu transportieren.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Waffenbesitz, Waffen\",\"translated\":true,\"hash\":\"\",\"id\":\"1072647\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10521\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072647\\/locations\\/10521\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1072647\\/locations\\/10521\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99089018000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzg