INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1078464','Sozialdienst für Gehörlose','https://service.berlin.de/dienstleistung/1078464/','Sonstiges','{\"id\":\"1078464\",\"name\":\"Sozialdienst f\\u00fcr Geh\\u00f6rlose\",\"description\":\"<p>Der Sozialdienst f\\u00fcr Geh\\u00f6rlose ist ein kostenfreies Angebot der Landeshauptstadt M\\u00fcnchen. Er ist Ansprechpartner f\\u00fcr geh\\u00f6rlose und h\\u00f6rbehinderte Menschen, die in Deutscher Geb\\u00e4rdensprache kommunizieren. Auch Angeh\\u00f6rige und Personen aus dem beruflichen und sozialen Umfeld sowie Fachleute im Sozialwesen k\\u00f6nnen sich an den Sozialdienst wenden. Die Fachstelle h\\u00e4usliche Versorgung ber\\u00e4t zudem schwerh\\u00f6rige Menschen, Menschen mit Cochlearimplantat und taubblinde Menschen.<\\/p>\\n<p>Erfahrene Sozialp\\u00e4dagog*innen beraten und unterst\\u00fctzen bei verschiedenen Angelegenheiten. Dazu geh\\u00f6ren zum Beispiel<\\/p>\\n<ul>\\n <li>pers\\u00f6nliche oder wirtschaftliche Notsituationen<\\/li>\\n <li>Familien- und Partnerkonflikte<\\/li>\\n <li>Probleme mit der Versorgung und Erziehung von Kindern<\\/li>\\n <li>Trennung, Ehescheidung und Sorgerecht<\\/li>\\n <li>Wohnprobleme und drohende Obdachlosigkeit<\\/li>\\n <li>Lebenskrisen und psychische Belastungen<\\/li>\\n <li>soziale Probleme in Folge von Alter oder Krankheit<\\/li>\\n <li>Umgang und Kommunikation mit Beh\\u00f6rden<\\/li>\\n <li>Gewalt, Gef\\u00e4hrdung und Vernachl\\u00e4ssigung von Kindern und Jugendlichen, Einleitung von Schutzma\\u00dfnahmen<\\/li>\\n <li>Pflege, h\\u00e4usliche Versorgung und Finanzierung von Leistungen<\\/li>\\n<\\/ul>\\n<p>Sie erreichen uns \\u00fcber E-Mail, Telefax, SMS und Telefon. Gespr\\u00e4chstermine oder einen Hausbesuch vereinbaren Sie bitte vorab.<br><br>\\n Weitere Informationen entnehmen Sie dem Flyer <a href=\\\"http:\\/\\/www.muenchen.info\\/soz\\/pub\\/pdf\\/389_Beratung_Unterstuetzung_fuer_gehoerlose_Menschen.pdf\\\" target=\\\"\\\">\\\"Beratung und Unterst\\u00fctzung f\\u00fcr geh\\u00f6rlose Menschen\\\"<\\/a>.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"H\\u00f6rbehinderung, Geh\\u00f6rlosenberatung, Cochleaimplantat, taub, taubstumm\",\"translated\":true,\"hash\":\"\",\"id\":\"1078464\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[],\"leika\":null,\"public\":false,\"links\":[{\"name\":\"YouTube-Kanal: Informationen in Geb\\u00e4rdensprache\",\"link\":\"https:\\/\\/www.youtube.com\\/playlist?list=PL7MjJ-8l7kFGtpQBvaqa0fNKLIFQrkyDH\",\"description\":false},{\"name\":\"Video mit Geb\\u00e4rdensprache\",\"link\":\"https:\\/\\/www.youtube.com\\/watch?v=zxqwZjXymr8\",\"description\":false},{\"name\":\"Beratung und Unterst\\u00fctzung f\\u00fcr geh\\u00f6rlose Menschen (PDF)\",\"link\":\"http:\\/\\/www.muenchen.info\\/soz\\/pub\\/pdf\\/389_Beratung_Unterstuetzung_fuer_gehoerlose_Menschen.pdf\",\"description\":false}],\"forms\":[{\"name\":\"YouTube-Kanal: Informationen in Geb\\u00e4rdensprache\",\"link\":\"https:\\/\\/www.youtube.com\\/playlist?list=PL7MjJ-8l7kFGtpQBvaqa0fNKLIFQrkyDH\",\"description\":false},{\"name\":\"Video mit Geb\\u00e4rdensprache\",\"link\":\"https:\\/\\/www.youtube.com\\/watch?v=zxqwZjXymr8\",\"description\":false},{\"name\":\"Beratung und Unterst\\u00fctzung f\\u00fcr geh\\u00f6rlose Menschen (PDF)\",\"link\":\"http:\\/\\/www.muenchen.info\\/soz\\/pub\\/pdf\\/389_Beratung_Unterstuetzung_fuer_gehoerlose_Menschen.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":20,\"combinable\":[1078464]}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080455','Auskunft zur Rente','https://service.berlin.de/dienstleistung/1080455/','Sonstiges','{\"id\":\"1080455\",\"name\":\"Auskunft zur Rente\",\"description\":\"<p>Wir beantworten gerne Ihre Fragen<\\/p><ul><li>zur Rentenart (zum Beispiel Altersrente, Rente wegen Erwerbsminderung)<\\/li><li>zum Rentenbeginn<\\/li><li>zur Rentenh\\u00f6he und Rentenzahlung <br><\\/li><li>zu den Auswirkungen des Hinzuverdienstes neben der Rente<\\/li><li>zu Rentenabschl\\u00e4gen und Ausgleichszahlung<\\/li><li>zur Rentenberechnung<\\/li><li>zur Zul\\u00e4ssigkeit und Begr\\u00fcndetheit von Widerspr\\u00fcchen gegen Rentenbescheide<\\/li><li>zu Versicherungsverl\\u00e4ufen und Rentenausk\\u00fcnften, einschlie\\u00dflich der Anforderung beim Rententr\\u00e4ger<\\/li><li>zum Rentenbeitrag und Nachzahlung von freiwilligen Beitr\\u00e4gen<\\/li><li>zur Beitragserstattung<\\/li><\\/ul><p>Gerne pr\\u00fcfen wir auch erlassene Rentenbescheide und informieren Sie \\u00fcber weitere M\\u00f6glichkeiten, die das Rentenrecht bietet.<br><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Rentenberatung, Renteninformation, Rentenverlauf, Wartezeitauskunft, Versicherungsverlauf\",\"translated\":true,\"hash\":\"\",\"id\":\"1080455\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10512\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080455\\/locations\\/10512\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080455\\/locations\\/10512\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99114028000000\",\"public\":true,\"links\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Videoberatung: Ablauf und Voraussetzungen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/videoberatung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Videoberatung: Ablauf und Voraussetzungen\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/videoberatung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":45,\"combinable\":[1080455],\"fees\":\"<p>\\nGeb\\u00fchrenfrei<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080479','Altersrente (Vor-Ort-Termin)','https://service.berlin.de/dienstleistung/1080479/','Sonstiges','{\"id\":\"1080479\",\"name\":\"Altersrente (Vor-Ort-Termin)\",\"description\":\"<ul><li>Stellen Sie den Antrag innerhalb der gesetzten Frist bei uns, haben Sie den gesetzlichen Termin eingehalten.<br>Die Sachbearbeiter*innen f\\u00fcllen alle Antragsformulare online aus und leiten diese unmittelbar an den zust\\u00e4ndigen Rententr\\u00e4ger weiter. Dadurch ist eine rasche, zeitnahe und vollst\\u00e4ndige Bearbeitung durch den Rententr\\u00e4ger gew\\u00e4hrleistet.<br><\\/li><\\/ul><p><strong>Es gibt folgende Altersrenten:<\\/strong><\\/p><ul><li>Regelaltersrente<\\/li><li>Altersrente f\\u00fcr langj\\u00e4hrig Versicherte<\\/li><li>Altersrente f\\u00fcr schwerbehinderte Menschen<\\/li><li>Altersrente f\\u00fcr besonders langj\\u00e4hrig Versicherte<br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Rente eingeben, Regelaltersrente, Rente f\\u00fcr Frauen, Rente f\\u00fcr schwerbehinderte Menschen, Rente f\\u00fcr langj\\u00e4hrig Versicherte, Rente f\\u00fcr besonders langj\\u00e4hrig Versicherte, Rente wegen Arbeitslosigkeit, Rente nach Arbeitsteilzeit, Formular \\u201eR 100\\u201c\",\"translated\":true,\"hash\":\"\",\"id\":\"1080479\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10515\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080479\\/locations\\/10515\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muen