INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080483','Auskunft zur gesetzlichen Kranken-, Pflege- und Unfallversicherung','https://service.berlin.de/dienstleistung/1080483/','Sonstiges','{\"id\":\"1080483\",\"name\":\"Auskunft zur gesetzlichen Kranken-, Pflege- und Unfallversicherung\",\"description\":\"<p>Wir beantworten gerne Ihre Fragen<\\/p><ul><li>zur Krankenversicherung der Rentner (\\u201eKVdR\\u201c)<\\/li><li>zu anderen Formen der Mitgliedschaft in der gesetzlichen Kranken- und Pflegeversicherung (zum Beispiel Familienversicherung, freiwillige Versicherung, Krankenversicherung f\\u00fcr Student*innen) und zum Beitragsrecht<\\/li><li>zum Thema \\u201ePersonen ohne Krankenversicherung\\u201c<\\/li><li>zum Status der Kranken- und Pflegeversicherung bei Weggang ins Ausland<\\/li><li>zum Krankengeld und Pflegegeld<\\/li><li>zur sozialen Absicherung von Pflegepersonen<\\/li><li>zu sonstigen Themen rund um die gesetzliche Kranken- und soziale Pflegeversicherung<\\/li><li>zum Antragsverfahren bei Arbeitsunf\\u00e4llen einschlie\\u00dflich der Hilfestellung beim Ausf\\u00fcllen von Frageb\\u00f6gen<\\/li><li>zum Schwerbehindertenausweis einschlie\\u00dflich der Aufnahme und Weiterleitung von Feststellungsantr\\u00e4gen<\\/li><li>zur Zul\\u00e4ssigkeit und Begr\\u00fcndetheit von Widerspr\\u00fcchen gegen Bescheide aus den einzelnen Bereichen (zum Beispiel bei Ablehnung einer Schwerbehinderung)<br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Schwerbehinderung, Schwerbehindertenausweis, Schwerbehindertenrecht, Gesetzliche Krankenversicherung, Krankenkassenwechsel, Krankengeld, Krankenversicherung der Rentner (KVdR), gesetzliche Pflegeversicherung, Pflegezeit, Pflegegeld, Unfallversicherung, Sozialversicherungen\",\"translated\":true,\"hash\":\"\",\"id\":\"1080483\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10512\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080483\\/locations\\/10512\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080483\\/locations\\/10512\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99114034000000\",\"public\":true,\"links\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/terminvereinbarung_\\/terminvereinbarung_va.html?cts=10216080\",\"description\":false}],\"forms\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/terminvereinbarung_\\/terminvereinbarung_va.html?cts=10216080\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":45,\"combinable\":[1080483],\"fees\":\"<p>\\nGeb\\u00fchren