INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080494','Hinterbliebenenrente (Vor-Ort-Termin)','https://service.berlin.de/dienstleistung/1080494/','Sonstiges','{\"id\":\"1080494\",\"name\":\"Hinterbliebenenrente (Vor-Ort-Termin)\",\"description\":\"<ul><li>Wollen Sie eine Hinterbliebenenrente beantragen, dann empfehlen wir Ihnen, einen individuellen Termin mit uns zu vereinbaren.<\\/li><li>Stellen Sie den Antrag innerhalb der gesetzten Frist bei uns, haben Sie den gesetzlichen Termin eingehalten.<\\/li><li>Die Sachbearbeiter*innen f\\u00fcllen alle Antragsformulare online aus und leiten diese an die zust\\u00e4ndigen Rententr\\u00e4ger weiter. Dadurch ist eine rasche, zeitnahe und vollst\\u00e4ndige Bearbeitung durch die Tr\\u00e4gerschaft gew\\u00e4hrleistet.<\\/li><\\/ul><p><strong>Es gibt folgende Hinterbliebenenrenten:<\\/strong><\\/p><ul><li>Witwen-\\/Witwerrenten<\\/li><li>Halbwaisen-\\/Vollwaisenrenten<\\/li><li>Hinterbliebenenrenten an den eingetragenen gleichgeschlechtlichen Lebenspartner<\\/li><li>Erziehungsrenten (Renten wegen Todes)<br><\\/li><\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Kleine Witwenrente, Witwerrente, Gro\\u00dfe Witwenrente Witwerrente, Waisenrente, Halbwaisenrente, Vollwaisenrente, Witwen-\\/Witwerrente nach dem vorletzten Ehegatten, Witwen-\\/Witwerrente an vor dem 1.7.1977 geschiedene Ehegatten, Erziehungsrente, Formular \\u201eR 500\\u201c\",\"translated\":true,\"hash\":\"\",\"id\":\"1080494\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10515\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080494\\/locations\\/10515\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080494\\/locations\\/10515\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99114020131000\",\"public\":true,\"links\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Merkblatt Hinterbliebenenrente\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Merkblatt_Hinterbliebenrente\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Merkblatt Hinterbliebenenrente\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Merkblatt_Hinterbliebenrente\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":45,\"combinable\":[1080494],\"fees\":\"<p>\\nGeb\\u00fchrenfrei<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080498','Kontenklärung','https://service.berlin.de/dienstleistung/1080498/','Sonstiges','{\"id\":\"1080498\",\"name\":\"Kontenkl\\u00e4rung\",\"description\":\"<p>Bei einer Kontenkl\\u00e4rung \\u00fcberpr\\u00fcfen wir, ob <strong>alle Informationen des Versicherten<\\/strong> zu seinen rentenrechtlich anrechenbaren Zeiten auch <strong>tats\\u00e4chlich bei seinem Rentenversicherungstr\\u00e4ger vorliegen<\\/strong>. Viele Zeiten werden dem Rentenversicherungstr\\u00e4ger maschinell \\u00fcbermittelt.<\\/p><p>Dennoch gibt es oft einige L\\u00fccken in der Versicherungsbiografie. So m\\u00fcssen Sie zum Beispiel extra beantragen, dass Schul- oder Kindererziehungszeiten anerkannt werden.<\\/p><p>Es kann auch passieren, dass Fehler bei der Daten\\u00fcbermittlung aufgetreten und die Daten deshalb nicht im Konto gespeichert sind. Es ist auch nicht auszuschlie\\u00dfen, dass Zeiten vor 1972 noch nicht gespeichert sind, denn damals gab es noch keine maschinelle Daten\\u00fcbermittlung.<\\/p><p><strong>Eine Kontenkl\\u00e4rung dient dazu, dass der Rentenversicherungstr\\u00e4ger Ihre Versicherungsbiografie vollst\\u00e4ndig erh\\u00e4lt.<\\/strong> Nur aus gekl\\u00e4rten Konten erfahren Versicherte durch den Rentenversicherungstr\\u00e4ger, was sie k\\u00fcnftig einmal als Rente zu erwarten haben.<\\/p><p>Wegen Rechts\\u00e4nderungen kann es sinnvoll sein, das Konto erneut kl\\u00e4ren zu lassen, auch wenn Sie dies erst vor ein paar Jahren haben pr\\u00fcfen lassen.<\\/p><p><strong>Eine Kontenkl\\u00e4rung ist nur nach Terminvereinbarung m\\u00f6glich!<\\/strong><\\/p><p>Bei Ihrem Termin f\\u00fcllen wir die Antragsformulare online aus und leiten diese unmittelbar an den zust\\u00e4ndigen Rententr\\u00e4ger weiter. Dadurch ist eine rasche, zeitnahe und vollst\\u00e4ndige Bearbeitung durch den Rententr\\u00e4ger gew\\u00e4hrleistet.<\\/p><p>\\u00a0<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Versicherungskonto, Versicherungsverlauf, Versicherungszeiten kl\\u00e4ren, Rentenversicherung, L\\u00fccken in der Rentenversicherung, Kindererziehungszeiten anrechnen, Formular \\u201eV 100\\u201c, Formular \\u201eV 300\\u201c, Versorgungsausgleich\",\"translated\":true,\"hash\":\"\",\"id\":\"1080498\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10515\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080498\\/locations\\/10515\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080498\\/locations\\/10515\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":null,\"public\":true,\"links\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false},{\"name\":\"Merkblatt Kontenkl\\u00e4rung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Merkblatt-Kontenklaerung.pdf\",\"description\":false}],\"forms\":[{\"name\":\"Versicherungsamt\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/buergerservice\\/gesundheit-soziales\\/versicherung-rente.html\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Vollmacht.pdf\",\"description\":false},{\"name\":\"Merkblatt Kontenkl\\u00e4rung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-I\\/Versicherungsamt\\/Dokumente\\/Merkblatt-Kontenklaerung.pdf\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":60,\"combinable\":[1080498],\"fees\":\"<p>\\nGeb\\u00fchrenfrei<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080502','Wechselkennzeichen','https://service.berlin.de/dienstleistung/1080502/','Sonstiges','{\"id\":\"1080502\",\"name\":\"Wechselkennzeichen\",\"description\":\"<p>Das Wechselkennzeichen besteht aus zwei Teilen - aus dem <strong>gemeinsamen Kennzeichenteil<\\/strong> und dem fest an jedem Fahrzeug angebrachten <strong>fahrzeugbezogenen Kennzeichenteil<\\/strong>.<\\/p>\\n<p>Der gemeinsame Kennzeichenteil ist auswechselbar und wird an dem jeweiligen Fahrzeug angebracht, das gerade bewegt werden soll.<br><br>\\n Die Erkennungsnummern eines Wechselkennzeichens sind bis auf die letzte Ziffer gleich. Die letzte Ziffer der Erkennungsnummer des Fahrzeugs ist auf dem fahrzeugbezogenen Teil des Kennzeichens aufgebracht. Der \\u00fcbrige Teil der Erkennungsnummer des Wechselkennzeichens ist auf dem auswechselbaren Teil aufgebracht.<\\/p>\\n<p>Die Zuteilung eines Wechselkennzeichens ist f\\u00fcr beide Fahrzeuge nur innerhalb eines Zehnerblocks (0 bis 9) bei den letzten Ziffern der Erkennungsnummer m\\u00f6glich. Beide Fahrzeuge besitzen somit jeweils ihr eigenes Kennzeichen, das sich nur in der <strong>letzten Ziffer<\\/strong> unterscheidet. Zum Beispiel M \\u2013 MM 1311 und M \\u2013 MM 1315.<\\/p>\\n<p>Fahrzeuge unterschiedlicher Klassen (zum Beispiel ein PKW und ein Motorrad) d\\u00fcrfen nicht kombiniert werden. Auch f\\u00fcr Lastkraftwagen oder Zugmaschinen ist das Wechselkennzeichen nicht genehmigt.<br>\\n Wechselkennzeichen k\\u00f6nnen nicht als Saisonkennzeichen, rote Kennzeichen, Kurzzeitkennzeichen gr\\u00fcne Kennzeichen oder Ausfuhrkennzeichen zugeteilt werden. Ein Fahrzeug oder beide Fahrzeuge jedoch k\\u00f6nnen Oldtimer sein.<\\/p>\\n<p><strong>Das Wechselkennzeichen darf jedoch zur gleichen Zeit nur an einem von den beiden Fahrzeugen gef\\u00fchrt werden.<\\/strong><\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Wechselkennzeichen, Kennzeichenzuteilung, Kennzeichen, Umschreibung\",\"translated\":true,\"hash\":\"\",\"id\":\"1080502\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10308013\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080502\\/locations\\/10308013\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080502\\/locations\\/10308013\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99036027069001\",\"public\":true,\"links\":[{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Bundesministerium f\\u00fcr Verkehr\",\"link\":\"https:\\/\\/www.bmvi.de\\/DE\\/Home\\/home.html\",\"description\":false}],\"forms\":[{\"name\":\"Vollmacht\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/Zulassungsvollmacht\",\"description\":false},{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"SEPA Mandat des Fahrzeughalters\\/ Kontoinhabers\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-III\\/Dokumente\\/Kfz-Zulassung\\/SEPA_Mandat_V_1_2_weiden.pdf\",\"description\":false},{\"name\":\"Bundesministerium f\\u00fcr Verkehr\",\"link\":\"https:\\/\\/www.bmvi.de\\/DE\\/Home\\/home.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":2,\"showOnStartPage\":true,\"duration\":30,\"combinable\":[1080502,1064121,1064354,1064308,10387573,1064275,10387564,1063425,1064342,1071959,1064311,1064323,1064130,1064333,1063424,1064314,1064271,10391602],\"fees\":\"<p>Die \\u00fcblichen Zulassungsgeb\\u00fchren erh\\u00f6hen sich bei Zuteilung eines Wechselkennzeichens um 6 Euro pro Fahrzeug.<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080582','Vorläufiger Reisepass','https://service.berlin.de/dienstleistung/1080582/','Sonstiges','{\"id\":\"1080582\",\"name\":\"Vorl\\u00e4ufiger Reisepass\",\"description\":\"<ul>\\n <li>Beim \\u00dcberschreiten von Staatsgrenzen ist grunds\\u00e4tzlich das Mitf\\u00fchren eines Ausweisdokuments erforderlich. Ob eine Passpflicht besteht, ist in den jeweiligen Staaten unterschiedlich gesetzlich geregelt.<\\/li>\\n <li>Bei Reisen innerhalb der Europ\\u00e4ischen Union und in die meisten Urlaubsl\\u00e4nder reicht es f\\u00fcr Deutsche jedoch aus, den Personalausweis vorzulegen.<\\/li>\\n <li>Einzelheiten zu den jeweiligen Reisemodalit\\u00e4ten einzelner L\\u00e4nder k\\u00f6nnen Sie beim Ausw\\u00e4rtigen Amt, im Reiseb\\u00fcro oder bei der Botschaft des jeweiligen Landes erfragen. Dort bekommen Sie eine aktuelle Information, ob ein vorl\\u00e4ufiger Reisepass f\\u00fcr die Einreise akzeptiert wird.<\\/li>\\n<\\/ul>\\n<p>Dieser maschinenlesbare Reisepass (ohne den Chip mit biometrischen Daten) ist ein Jahr g\\u00fcltig.<\\/p>\\n<p>Einen vorl\\u00e4ufigen Reisepass k\\u00f6nnen Sie in jedem B\\u00fcrgerb\\u00fcro im Stadtgebiet beantragen. Sie k\\u00f6nnen das Ausweisdokument sofort mitnehmen.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Ausweis, Reisen, Sofort-Pass, Personaldokument, vor\\u00fcbergehender Reisepass, Pass, Sofortpass\",\"translated\":true,\"hash\":\"\",\"id\":\"1080582\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\