INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1080843','Haushaltsbescheinigung','https://service.berlin.de/dienstleistung/1080843/','Sonstiges','{\"id\":\"1080843\",\"name\":\"Haushaltsbescheinigung\",\"description\":\"<p>Sie k\\u00f6nnen die Haushaltsbescheinigung schriftlich (Per Post, Fax, E-Mail) oder pers\\u00f6nlich beantragen. F\\u00fcr die pers\\u00f6nliche Vorsprache ben\\u00f6tigen Sie einen Termin. Sie k\\u00f6nnen eine andere Person mit Vollmacht beantragen, die Haushaltsbescheinigung f\\u00fcr Sie abzuholen.<br><br>\\n Diese Bescheinigung wird f\\u00fcr andere Beh\\u00f6rden ben\\u00f6tigt, zum Beispiel wenn Sie Kindergeld, Arbeitslosengeld oder die Befreiung von Studiengeb\\u00fchren beantragen. Die Formulare erhalten Sie in der Regel von den zust\\u00e4ndigen Beh\\u00f6rden.<br><br>\\n Die Antr\\u00e4ge k\\u00f6nnen nur bearbeitet werden, wenn Sie in M\\u00fcnchen gemeldet sind.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Haushaltbescheinigung, Haushaltsbest\\u00e4tigung\",\"translated\":true,\"hash\":\"\",\"id\":\"1080843\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"102522\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080843\\/locations\\/102522\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1080843\\/locations\\/102522\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"locatio