INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1081224','Erlöschen des Aufenthaltstitels, § 51 AufenthG','https://service.berlin.de/dienstleistung/1081224/','Sonstiges','{\"id\":\"1081224\",\"name\":\"Erl\\u00f6schen des Aufenthaltstitels, \\u00a7 51 AufenthG\",\"description\":\"<p><strong>Ihr Aufenthaltstitel erlischt in der Regel, wenn:<\\/strong><\\/p>\\n<ul>\\n <li>Sie aus einem nicht nur vor\\u00fcbergehenden Grund ausreisen, zum Beispiel:\\n  <ul>\\n   <li>Schulbesuch im Ausland<\\/li>\\n   <li>Arbeiten im Ausland<\\/li>\\n   <li>Pflege eines Familienangeh\\u00f6rigen im Ausland<\\/li>\\n   <li>Heirat im Ausland<\\/li>\\n   <li>Niederlassen im Ausland<\\/li>\\n  <\\/ul><\\/li>\\n <li>Sie ausreisen und nicht innerhalb von sechs Monaten oder einer von der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung bestimmten l\\u00e4ngeren Frist wieder einreisen (Ausnahme: Sie erf\\u00fcllen einen vorgeschriebenen Wehrdienst in Ihrem Heimatland und reisen innerhalb von drei Monaten nach dessen Beendigung wieder nach Deutschland ein).<\\/li>\\n<\\/ul>\\n<p>Ausnahme:<\\/p>\\n<ul>\\n <li>Sie erf\\u00fcllen einen vorgeschriebenen Wehrdienst in Ihrem Heimatland und reisen innerhalb von drei Monaten nach dessen Beendigung wieder nach Deutschland ein.<\\/li>\\n<\\/ul>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufenthalt, Aufenthaltstitel, Aufenthaltserlaubnis, Auslandsaufenthalt, Ausland, Niederlassungserlaubnis, Blaue Karte, Daueraufenthaltserlaubnis-EG, Unbefristete Aufenthaltserlaubnis\",\"translated\":true,\"hash\":\"\",\"id\":\"1081224\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10446\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10446\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10446\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10462\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10462\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10462\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10459\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10459\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10459\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10460\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10460\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/10460\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"54284\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/54284\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1081224\\/locations\\/54284\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99010001000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1081224],\"fees\":\"<p>18 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1082963','Aufenthaltserlaubnis – Au-pair','https://service.berlin.de/dienstleistung/1082963/','Sonstiges','{\"id\":\"1082963\",\"name\":\"Aufenthaltserlaubnis \\u2013 Au-pair\",\"description\":\"<p>Mit einem Visum beziehungsweise der Aufenthaltserlaubnis f\\u00fcr Au-pair, k\\u00f6nnen Sie sich bis zu einem Jahr in Deutschland in Ihrer Gastfamilie aufhalten und dort bei der Kinderbetreuung helfen.<\\/p>\\n<p><strong>Vor der Einreise<\\/strong><\\/p>\\n<p>F\\u00fcr die Einreise nach Deutschland brauchen Sie in der Regel ein <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/servicestelle-fur-zuwanderung-und-einburgerung\\/10508085\\/\\\">Visum<\\/a>.<\\/p>\\n<p><strong>Nach der Einreise<\\/strong><\\/p>\\n<p>Sie m\\u00fcssen zuerst Ihren Wohnsitz im <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\\\">B\\u00fcrgerb\\u00fcro<\\/a> anmelden.<\\/p>\\n<p><strong>Antrag auf Erteilung oder Verl\\u00e4ngerung eines Aufenthaltstitels<\\/strong><\\/p>\\n<p>Bevor Ihr nationales D-Visum oder bisheriger Aufenthaltstitel abl\\u00e4uft, m\\u00fcssen Sie einen Aufenthaltstitel beantragen. Sie k\\u00f6nnen Ihren <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\">Antrag<\\/a> und die ben\\u00f6tigten Unterlagen <strong>online<\\/strong> einreichen:<\\/p>\\n<ul>\\n <li>Bitte laden Sie Ihre Unterlagen m\\u00f6glichst als PDF-Dokument hoch.<\\/li>\\n <li>Nachdem Sie Ihren Antrag versendet haben, wird Ihnen eine Best\\u00e4tigung angezeigt. Diese k\\u00f6nnen Sie als PDF-Datei f\\u00fcr Ihre Unterlagen speichern.<\\/li>\\n <li>In dieser Best\\u00e4tigung steht, dass Ihr aktueller Aufenthalt \\u00fcber das bisherige G\\u00fcltigkeitsdatum hinaus in Deutschland weiterhin g\\u00fcltig ist und Sie im bisherigen Umfang arbeiten k\\u00f6nnen.<\\/li>\\n <li>Die Best\\u00e4tigung k\\u00f6nnen Sie als Nachweis bei Beh\\u00f6rden oder an Ihrem Arbeitsplatz vorlegen.<\\/li>\\n <li>Nach der Pr\\u00fcfung Ihres Antrags bekommen Sie einen Termin.<\\/li>\\n<\\/ul>\\n<p><strong>G\\u00fcltigkeitsdauer<\\/strong><\\/p>\\n<p>Die Aufenthaltserlaubnis gilt maximal ein Jahr.<\\/p>\\n<p><strong>Gastfamilie<\\/strong><\\/p>\\n<p>Als Gastfamilie kommen in der Regel nur Paare und Alleinerziehende mit mindestens einem Kind in Frage. In der Gastfamilie sollte Deutsch als Muttersprache gesprochen werden. Wird Deutsch nur als Familiensprache gesprochen, d\\u00fcrfen Sie nicht mit einem Familienmitglied verwandt sein oder aus dem Heimatland der Gasteltern stammen. Zudem sollte die Gastfamilie Sie gut integrieren, Ihnen ein eigenes Zimmer in der Familienwohnung zur Verf\\u00fcgung stellen und die Teilnahme an gemeinsamen Essen erm\\u00f6glichen.<\\/p>\\n<p><strong>Wechsel der Gastfamilie<\\/strong><\\/p>\\n<p>Wenn Sie Ihre T\\u00e4tigkeit in der Gastfamilie vorzeitig beenden und in eine andere Gastfamilie wechseln wollen, brauchen Sie dazu zuerst die Genehmigung der Servicestelle f\\u00fcr Zuwanderung und Einb\\u00fcrgerung.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufenthalt, Gastfamilien, Sprachkenntnisse, Einreise Au-Pair, Visum, Visumsverfahren, Nicht-EU-B\\u00fcrger, Nicht-EWR-B\\u00fcrger, Aufenthaltserlaubnis, Aupair\",\"translated\":true,\"hash\":\"\",\"id\":\"1082963\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10446\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10446\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10446\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10462\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10462\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10462\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10459\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10459\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10459\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10460\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10460\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1082963\\/locations\\/10460\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false}],\"leika\":\"99011004000000\",\"public\":false,\"links\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Information Ausw\\u00e4rtiges Amt\",\"link\":\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/visa-und-aufenthalt\",\"description\":false},{\"name\":\"Information Arbeitsagentur\",\"link\":\"https:\\/\\/www.arbeitsagentur.de\\/unternehmen\\/arbeitskraefte\\/au-pair\",\"description\":false}],\"forms\":[{\"name\":\"Datenschutzgrundverordnung\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/infos\\/dsgvo-datenschutzgrundverordnung.html\",\"description\":false},{\"name\":\"Information zum biometrischen Passfoto\",\"link\":\"https:\\/\\/www.bundesdruckerei.de\\/system\\/files\\/dokumente\\/pdf\\/Fotomustertafel-72dpi.pdf\",\"description\":false},{\"name\":\"Antrag auf Aufenthaltstitel\",\"link\":\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\",\"description\":false},{\"name\":\"Information Ausw\\u00e4rtiges Amt\",\"link\":\"https:\\/\\/www.auswaertiges-amt.de\\/de\\/service\\/visa-und-aufenthalt\",\"description\":false},{\"name\":\"Information Arbeitsagentur\",\"link\":\"https:\\/\\/www.arbeitsagentur.de\\/unternehmen\\/arbeitskraefte\\/au-pair\",\"description\":false}],\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\"},\"maxQuantity\":1,\"showOnStartPage\":true,\"duration\":15,\"combinable\":[1082963],\"fees\":\"<p>100 Euro<\\/p>\"}',NULL,NULL);
INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1086574','Aufenthalts- und Arbeitserlaubnis – Nicht-EU-Bürger','https://service.berlin.de/dienstleistung/1086574/','Sonstiges','{\"id\":\"1086574\",\"name\":\"Aufenthalts- und Arbeitserlaubnis \\u2013 Nicht-EU-B\\u00fcrger\",\"description\":\"<p><strong>Vor der Einreise<\\/strong><\\/p>\\n<p>F\\u00fcr die Einreise nach Deutschland brauchen Sie in der Regel ein <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/servicestelle-fur-zuwanderung-und-einburgerung\\/10508085\\/\\\">Visum<\\/a>.<\\/p>\\n<p><strong>Nach der Einreise<\\/strong><\\/p>\\n<p>Sie m\\u00fcssen zuerst Ihren Wohnsitz im <a href=\\\"https:\\/\\/stadt.muenchen.de\\/service\\/info\\/wohnsitz-anmelden-oder-ummelden\\/1063475\\/n0\\/\\\">B\\u00fcrgerb\\u00fcro<\\/a> anmelden.<\\/p>\\n<p><strong>Antrag auf Erteilung oder Verl\\u00e4ngerung eines Aufenthaltstitels<\\/strong><\\/p>\\n<p>Bevor Ihr nationales D-Visum oder bisheriger Aufenthaltstitel abl\\u00e4uft, m\\u00fcssen Sie einen Aufenthaltstitel beantragen. Sie k\\u00f6nnen Ihren <a href=\\\"https:\\/\\/stadt.muenchen.de\\/dms\\/Home\\/Stadtverwaltung\\/Kreisverwaltungsreferat\\/fachspezifisch\\/HA-II\\/Auslaenderbehoerde\\/Dokumente\\/antragaufenthaltstitel.pdf\\\">Antrag<\\/a> und die ben\\u00f6tigten Unterlagen <strong>online<\\/strong> einreichen:<\\/p>\\n<ul>\\n <li>Bitte laden Sie Ihre Unterlagen m\\u00f6glichst als PDF-Dokument hoch.<\\/li>\\n <li>Nachdem Sie Ihren Antrag versendet haben, wird Ihnen eine Best\\u00e4tigung angezeigt. Diese k\\u00f6nnen Sie als PDF-Datei f\\u00fcr Ihre Unterlagen speichern.<\\/li>\\n <li>In dieser Best\\u00e4tigung steht, dass Ihr aktueller Aufenthalt \\u00fcber das bisherige G\\u00fcltigkeitsdatum hinaus in Deutschland weiterhin g\\u00fcltig ist und Sie im bisherigen Umfang arbeiten k\\u00f6nnen.<\\/li>\\n <li>Die Best\\u00e4tigung k\\u00f6nnen Sie als Nachweis bei Beh\\u00f6rden oder an Ih