INSERT INTO `request` (`source`, `id`, `name`, `link`, `group`, `data`, `parent_id`, `variant_id`) VALUES ('dldb','1087850','Aufenthaltserlaubnis – Freiwilligendienst','https://service.berlin.de/dienstleistung/1087850/','Sonstiges','{\"id\":\"1087850\",\"name\":\"Aufenthaltserlaubnis \\u2013 Freiwilligendienst\",\"description\":\"<p>Einzelnen Freiwilligendienste gelten verschiedene Voraussetzungen.<\\/p>\\n<p><strong>Freiwilliges Soziales Jahr (FSJ) und Freiwilliges \\u00d6kologisches Jahr (F\\u00d6J)<\\/strong><\\/p>\\n<ul>\\n <li>Altersgrenze: mindestens 16 und h\\u00f6chstens 26 Jahre alt<\\/li>\\n <li>M\\u00f6gliche Bereiche: Gemeinwohl und Soziales (FSJ) sowie Natur- und Umweltschutz oder Umweltbildung (F\\u00d6J)<\\/li>\\n <li>Dauer des freiwilligen Dienstes: mindestens 6 Monate, in der Regel 1 Jahr lang und l\\u00e4ngstens 18 Monate (in besonderen Ausnahmef\\u00e4llen bis zu 24 Monate)<\\/li>\\n <li>F\\u00fcr diesen Vollzeitdienst muss die Vollzeitschulpflicht erf\\u00fcllt sein.<\\/li>\\n<\\/ul>\\n<p><strong>Bundesfreiwilligendienst (BFD)<\\/strong><\\/p>\\n<ul>\\n <li>Der BFD ist ein Angebot f\\u00fcr Personen jeden Alters, sich au\\u00dferhalb von Beruf und Schule f\\u00fcr das Allgemeinwohl zu engagieren.<\\/li>\\n <li>M\\u00f6gliche Bereiche: Sozialer, \\u00f6kologischer und kultureller Bereich sowie im Bereich des Sports, der Integration sowie im Zivil- und Katastrophenschutz<\\/li>\\n <li>Dauer des freiwilligen Dienstes: mindestens 6,in der Regel 12, und l\\u00e4ngstens 24 Monate.<\\/li>\\n <li>F\\u00fcr diesen Vollzeitdienst muss die Vollzeitschulpflicht erf\\u00fcllt sein.<\\/li>\\n<\\/ul>\\n<p><strong>Europ\\u00e4ischer Freiwilligendienst (EFD)<\\/strong><\\/p>\\n<ul>\\n <li>Der EFD ist Teil des Programms Jugend in Aktion und damit des EU-Programms Erasmus+<\\/li>\\n <li>Altersgrenze: mindestens 17 und h\\u00f6chstens 30 Jahre alt<\\/li>\\n <li>M\\u00f6gliche Bereiche: Soziales, Jugend, Umwelt und Kultur<\\/li>\\n <li>Dauer des freiwilligen Dienstes: bis zu 1 Jahr<\\/li>\\n <li>Staatsangeh\\u00f6rigkeit eines Partnerlandes des Programms Erasmus+<\\/li>\\n<\\/ul>\\n<p>Die Zustimmung der Bundesagentur f\\u00fcr Arbeit ist nicht erforderlich.<\\/p>\\n<p>Ein Freiwilligendienst ist auch im Anschluss an eine Au-Pair-T\\u00e4tigkeit m\\u00f6glich.<\\/p>\\n<p>Bei Minderj\\u00e4hrigen unter 18 Jahren ist die Zustimmung der sorgeberechtigten Personen (Eltern) erforderlich.<\\/p>\\n<p><strong><u>Hinweise zum Verfahren<\\/u><\\/strong><\\/p>\\n<p><strong>Visum<\\/strong>:Vor der Einreise m\\u00fcssen Sie ein Visum bei der zust\\u00e4ndigen deutschen Auslandsvertretung beantragen.Staatsangeh\\u00f6rige von Australien, Israel, Japan, Kanada, der Republik Korea,Neuseeland, den USA und dem Vereinigten K\\u00f6nigreich k\\u00f6nnen auch ohne Visum einreisen und zur Aufnahme der T\\u00e4tigkeit die Aufenthaltserlaubnis beantragen. <strong>Nach der Einreise:<\\/strong><\\/p>\\n<p>Sie m\\u00fcssen zuerst Ihren Wohnsitz im <a href=\\\"https:\\/\\/www.muenchen.de\\/dienstleistungsfinder\\/muenchen\\/1063475\\/n0\\/\\\">B\\u00fcrgerb\\u00fcro<\\/a> anmelden.<\\/p>\\n<p><strong>Antrag auf Aufenthaltserlaubnis:<\\/strong><\\/p>\\n<p>Bevor Ihr Visum\\/ Aufenthaltstitel abl\\u00e4uft, m\\u00fcssen Sie die Aufenthaltserlaubnis beantragen. K\\u00f6nnen Sie zu diesem Zweck visafrei einreisen, m\\u00fcssen Sie den Antrag innerhalb von 90 Tagen nach Ihrer Einreise stellen.<\\/p>\\n<p>F\\u00fcr die Beantragung senden Sie uns bitte Ihr Antragsformular sowie die ben\\u00f6tigten Unterlagen <a href=\\\"https:\\/\\/service.muenchen.de\\/intelliform\\/forms\\/01\\/02\\/02\\/kontaktabhsonstigebeschaeftigung\\/index\\\">online<\\/a>(bitte w\\u00e4hlen Sie hier unter \\u201eArt der Besch\\u00e4ftigung\\u201c auch f\\u00fcr den EFD die Antwort \\u201eBundesfreiwilligendienst\\u201c aus) oder per Post zu. Nach der Pr\\u00fcfung Ihres Antrags erhalten Sie von uns einen Termin.<\\/p>\",\"meta\":{\"lastupdate\":\"2026-10-10T19:57:44\",\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/{serviceId}\",\"locale\":\"de\",\"keywords\":\"Aufenthalt, Freiwilliges Soziales Jahr, Bundesfreiwilligengesetz, Freiwilliges \\u00d6kologisches Jahr, Bundesfreiwilligendienst, Studienvorbereitung, Spracherwerb, Au-Pair\",\"translated\":true,\"hash\":\"\",\"id\":\"1087850\"},\"authorities\":[{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"}],\"locations\":[{\"location\":\"10446\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1087850\\/locations\\/10446\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1087850\\/locations\\/10446\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10462\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1087850\\/locations\\/10462\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1087850\\/locations\\/10462\",\"slots\":\"0\",\"external\":false,\"multiple\":\"1\",\"allowed\":true},\"responsibility\":null,\"responsibility_hint\":null,\"hint\":false},{\"location\":\"10459\",\"authority\":{\"id\":\"1\",\"name\":\"Stadtverwaltung M\\u00fcnchen\",\"webinfo\":\"https:\\/\\/muenchen.de\"},\"url\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\/#\\/services\\/1087850\\/locations\\/10459\",\"appointment\":{\"link\":\"https:\\/\\/stadt.muenchen.de\\/en\\/buergerservice\\/terminvereinbarung.html\\